async function bootModules() {
  try { ({ parseOTIO } = await import("./parsers/otio.js")); } catch {}
  try { ({ parseXMEML } = await import("./parsers/xml.js")); } catch {}
  try { ({ parseALE }   = await import("./parsers/ale.js")); } catch {}
  try { ({ parseEDL }   = await import("./parsers/edl.js")); } catch {}
  try { ({ parsePRPROJ } = await import("./parsers/prproj.js")); } catch {}
  try { ({ buildEDLFiles } = await import("./modules/edl_export.js")); } catch {}
  try { Filters = await import("./modules/filters.js"); } catch {}
  try { VFXRename = await import("./modules/filters_vfxRename.js"); } catch {}
  // Nuke importer helper (some packages store it in root instead of ./modules)
  try { ({ downloadNukeImporterPy } = await import("./modules/nuke_import_script.js")); }
  catch(e1){
    try { ({ downloadNukeImporterPy } = await import("./nuke_import_script.js")); }
    catch(e2){ /* optional */ }
  }
  // VFX Mapping module (still stored as amf_convert.js for compatibility)
  // VFX Mapping module (some packages store it in root instead of ./modules)
  try { AMF = await import("./modules/amf_convert.js"); }
  catch(e1){
    try { AMF = await import("./amf_convert.js"); }
    catch(e2){
      console.warn("VFX Mapping module failed to load", e1);
      console.warn("VFX Mapping module fallback also failed", e2);
    }
  }
  try { CutDiff = await import("./modules/cutdiff.js"); } catch(e){ console.warn("CUT DIFF module failed to load", e); }
}

