function isMainPaneVisible(key){
  try{
    if (document.hidden) return false;
    if (document.body?.dataset?.main === key) return true;
    const main = document.getElementById(`main-${key}`);
    return !!main && getComputedStyle(main).display !== 'none';
  }catch{
    return false;
  }
}

