// -------------------------------------------------------------
// Viewport Fit (Tab mode): keep UI consistent across notebook + ultrawide
// - Uses CSS zoom on #appShell (Chrome-supported) so the whole app fits.
// - Clamps max zoom so ultrawide doesn't blow up the UI.
// -------------------------------------------------------------
function setupViewportFit(){
  const shell = document.getElementById('appShell');
  if (!shell) return;

  // Default shell width (keeps notebook layout consistent)
  // Users requested smaller left/right margins on wide displays.
  // Allow a wider shell while keeping a small outer gap.
  const MAX_W_DEFAULT = 2400; // visual max width
  const EDGE_GAP = 32;        // total horizontal outer gap (≈16px each side)
  const BASE_W = 1560;
  const BASE_H = 900;
  const MIN_Z = 0.82;
  const MAX_Z = 1.00;

  const measure = () => {
    const vv = window.visualViewport;
    const vw = (vv && vv.width)  ? vv.width  : window.innerWidth;
    const vh = (vv && vv.height) ? vv.height : window.innerHeight;
    return { vw, vh };
  };

  const apply = () => {
    const { vw, vh } = measure();

    // Keep a consistent max width across ALL tabs (so left/right margins match)
    const maxW = MAX_W_DEFAULT;

    // Fit within both width and height, but never upscale beyond MAX_Z
    const raw = Math.min(vw / BASE_W, vh / BASE_H);
    const z = Math.max(MIN_Z, Math.min(raw, MAX_Z));

    // Set CSS zoom (affects layout + rendering). Width/height are in *CSS px before zoom*.
    // Keep a small outer gap so the UI doesn't touch browser edges.
    const w = Math.min(maxW, Math.max(320, (vw - EDGE_GAP) / z));
    const h = vh / z;

    shell.style.zoom = z.toFixed(4);
    shell.style.width = w.toFixed(2) + 'px';
    shell.style.height = h.toFixed(2) + 'px';

    // CSS fallback var (useful for styles / debug)
    document.documentElement.style.setProperty('--ui-zoom', z.toFixed(4));
  };

  // Allow other code (tab switch) to re-run fit logic.
  try{ window.__pfxApplyViewportFit = apply; }catch{}

  apply();
  window.addEventListener('resize', apply, { passive: true });
  if (window.visualViewport){
    window.visualViewport.addEventListener('resize', apply, { passive: true });
    window.visualViewport.addEventListener('scroll', apply, { passive: true });
  }
}

// Apply immediately (ui.js is loaded at the end of <body>)
try{ setupViewportFit(); }catch(_){ }

function pad2(n){ return String(n).padStart(2,"0"); }

function stemNoExt(path=""){
  const s=String(path||"");
  const i=s.lastIndexOf(".");
  return i>0 ? s.slice(0,i) : s;
}

// ─── Export Filename Template ──────────────────────────────────────────────────
const PFX_FILENAME_TPL_KEY     = 'pfx.export.filenameTpl.v1';
const PFX_FILENAME_TPL_DEFAULT = '%{project}_%{date}';

function _pfxResolveTpl(template, ctx = {}) {
  const ymd     = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const safeVal = s => String(s || '').replace(/[^a-zA-Z0-9\-]/g, '_').replace(/__+/g, '_').replace(/^_+|_+$/g, '');
  const result  = (template || PFX_FILENAME_TPL_DEFAULT)
    .replace(/%\{project\}/g, safeVal(ctx.project || 'Project'))
    .replace(/%\{date\}/g,    ymd)
    .replace(/%\{fps\}/g,     String(ctx.fps || ''))
    .replace(/%\{year\}/g,    ymd.slice(0, 4))
    .replace(/%\{month\}/g,   ymd.slice(4, 6))
    .replace(/%\{day\}/g,     ymd.slice(6, 8))
    .replace(/[^a-zA-Z0-9_\-]/g, '_')
    .replace(/__+/g, '_').replace(/^_+|_+$/g, '');
  return result || safeVal(ctx.project || 'Project');
}
// Expose for use in prep_mark.js
window.__pfxResolveTpl = _pfxResolveTpl;

// ─── Parse Progress Toast ─────────────────────────────────────────────────────
function _parseProgressShow(msg, state = 'loading') {
  const el = document.getElementById('pfxParseProgress');
  if (!el) return;
  clearTimeout(el._hideTimer);
  el.dataset.state = state;
  el.innerHTML = state === 'loading'
    ? `<span class="pfx-pp-spinner" aria-hidden="true"></span><span class="pfx-pp-msg">${esc(msg)}</span>`
    : `<span class="pfx-pp-check" aria-hidden="true">✓</span><span class="pfx-pp-msg">${esc(msg)}</span>`;
  el.classList.add('pfx-pp-on');
  if (state === 'done') {
    el._hideTimer = setTimeout(() => el.classList.remove('pfx-pp-on'), 2800);
  }
}
function _parseProgressHide() {
  const el = document.getElementById('pfxParseProgress');
  if (!el) return;
  clearTimeout(el._hideTimer);
  el.classList.remove('pfx-pp-on');
}

// Both count on the whole-frame base, not the playback rate: 23.976 fits 24 frame
// fields into a timecode second and 29.97 NDF fits 30. Multiplying seconds by the
// fractional rate made a four-second span measure 95.904 frames, and dividing by it
// in framesToTC put a fractional number in the frame field — "00:00:05:0.12000000000000455"
// reached the Inspector's duration label that way.
//
// tcToFrames still answers 0 for anything it cannot read, because thirty call sites
// in this file add its result straight into a running total and a NaN would poison
// every row after it. That 0 is only safe for callers that add; callers that *test*
// the result for validity must not use this — Number.isFinite(0) is true, so the
// test always passes. Those callers use parseTimecodeFrames from modules/eventDuration.js,
// which answers NaN.
function tcToFrames(tc,fps=24){
  const m = tc&&String(tc).trim().match(/^(\d+)[:;](\d+)[:;](\d+)[:;](\d+)(?:\.\d+)?$/);
  if(!m)return 0;
  return (+m[1]*3600+ +m[2]*60+ +m[3])*nominalBase(fps) + +m[4];
}

function framesToTC(fr,fps=24){
  const base=nominalBase(fps);
  fr=Math.round(fr||0);
  const s=Math.floor(fr/base);
  const ff=fr%base;
  const hh=Math.floor(s/3600), mm=Math.floor((s%3600)/60), ss=s%60;
  const p=n=>String(n).padStart(2,"0");
  return `${p(hh)}:${p(mm)}:${p(ss)}:${p(ff)}`;
}

// -------------------------------------------------------------
// FPS helpers
// -------------------------------------------------------------
// UI timecode helpers in this project assume an integer FPS.
// When we detect a non-integer (e.g. 23.976/29.97/59.94), we normalize
// to the nominal integer used by most editorial UIs.
function normalizeFpsNominal(fpsMaybe, fallback=24){
  const r = Number(fpsMaybe);
  if (!Number.isFinite(r) || r <= 0) return (Number(fallback) || 24);

  // Common exact rates (with small tolerance)
  if (Math.abs(r - 23.976) < 0.05 || Math.abs(r - 24) < 0.05) return 24;
  if (Math.abs(r - 29.97)  < 0.05 || Math.abs(r - 30) < 0.05) return 30;
  if (Math.abs(r - 59.94)  < 0.05 || Math.abs(r - 60) < 0.05) return 60;

  // Otherwise, prefer nearest integer
  const ri = Math.round(r);
  if (Math.abs(r - ri) < 0.05) return ri;
  return ri || (Number(fallback) || 24);
}

function parseFpsFromText(txt){
  if (!txt) return null;
  const s = String(txt);
  // e.g. "A_48fps", "23.976fps", "FPS 50"
  let m = s.match(/(\d+(?:\.\d+)?)\s*fps\b/i);
  if (m) return Number(m[1]);
  m = s.match(/\bfps\s*(\d+(?:\.\d+)?)/i);
  if (m) return Number(m[1]);
  return null;
}

function getSourceFpsForEvent(ev, timelineFps){
  if (!ev) return normalizeFpsNominal(timelineFps, 24);
  // Prefer explicit source fps fields if present
  const direct = ev.srcFps || ev.sourceFps || ev.mediaFps || ev.clipFps;
  const fromDirect = Number(direct);
  if (Number.isFinite(fromDirect) && fromDirect > 0) return normalizeFpsNominal(fromDirect, timelineFps);

  // Cache best-effort guess to avoid regex work on every render
  if (Number.isFinite(ev._srcFpsGuess) && ev._srcFpsGuess > 0) return ev._srcFpsGuess;

  const candidates = [
    ev.clipName,
    ev.srcFile,
    ev.assetName,
    ev.reel,
    ev.edlSource,
    ev.loc,
    ev._marker?.name
  ];
  for (const c of candidates){
    const v = parseFpsFromText(c);
    if (Number.isFinite(v) && v > 0){
      ev._srcFpsGuess = normalizeFpsNominal(v, timelineFps);
      return ev._srcFpsGuess;
    }
  }

  ev._srcFpsGuess = normalizeFpsNominal(timelineFps, 24);
  return ev._srcFpsGuess;
}

// Compute base frame number for Rec TC so UI can display Rec starting at 00:00:00:00.
// NOTE: This is a UI-only rebase for Event Table (and any callers that opt-in).
function computeRecBaseFrames(events=[], fps=24){
  // Some parsers may emit placeholder recIn = 00:00:00:00 for items without a real record TC.
  // For UI rebase we want the earliest *positive* record TC. Only fall back to 0 if *all* are 0/invalid.
  let minPos = Infinity;
  let sawAny = false;
  for (const e of (events||[])){
    const tc = e?.recIn;
    if (!tc) continue;
    const fr = tcToFrames(tc, fps);
    if (!Number.isFinite(fr)) continue;
    sawAny = true;
    if (fr > 0 && fr < minPos) minPos = fr;
  }
  if (!sawAny) return 0;
  if (minPos === Infinity) return 0; // all are 0/invalid
  return minPos;
}


function rebaseRecTC(tc, baseFrames=0, fps=24){
  if (!tc) return "—";
  const fr = tcToFrames(tc, fps);
  const out = Math.max(0, fr - (baseFrames||0));
  return framesToTC(out, fps);
}

// Compute sequential EDL-style record timecodes (start at 00:00:00:00, back-to-back),
// matching the EDL export record timeline.
function computeEdlRecMap(view=[], rowOrder=[], fps=24, selectedSet=null){
  const useSelected = selectedSet && selectedSet.size > 0;
  const order = (rowOrder||[]).filter(i => !useSelected || selectedSet.has(i));

  const map = new Map(); // i -> {inTC,outTC,inF,outF,durF}
  let cur = 0;

  // durationFrames, else source span, else record span. Lives in
  // modules/eventDuration.js so it can be tested — the record fallback used to be
  // unreachable here (tcToFrames answered 0, and Number.isFinite(0) is true, so the
  // source branch claimed every event), and nothing in the suite could reach this
  // file to notice. See tests-js/eventDuration.test.mjs.
  const durFramesFor = (e) => durationFramesFor(e, fps);

  for (const i of order){
    const e = view[i];
    const d = durFramesFor(e);
    const inTC = framesToTC(cur, fps);
    const outTC = framesToTC(cur + d, fps);
    map.set(i, { inTC, outTC, inF: cur, outF: cur + d, durF: d });
    cur += d;
  }
  return { map, useSelected };
}

function esc(v){
  const str = (v === null || v === undefined || v === "") ? "—" : String(v);
  return str.replace(/[&<>"]/g, c => (
    c === "&" ? "&amp;" :
    c === "<" ? "&lt;"  :
    c === ">" ? "&gt;"  : "&quot;"
  ));
}

