function isTimelineFileName(name=""){
  const n = String(name||"").toLowerCase();
  return (
    n.endsWith(".fcpxml") ||
    n.endsWith(".xml") ||
    n.endsWith(".otio") ||
    n.endsWith(".otioz") ||
    n.endsWith(".ale") ||
    n.endsWith(".json") ||
    n.endsWith(".edl") ||
    n.endsWith(".aaf") ||
    n.endsWith(".prproj") ||
    n.endsWith(".drp")
  );
}
function pickTimelineFiles(files=[]){
  return (files||[]).filter(f => isTimelineFileName(f?.name || f?.virtualPath || ""));
}

// VFX Mapping status helper (fix: "No folder selected." persists after scan)
function setAMFStatus(text){
  const main = $("#main-amf") || document.getElementById("main-amf");
  if (!main) return;


  const targets = [];

  // common ids across versions
  [
    "amfStatus","amfStatusText",
    "amfFolderStatusText","amfFolderHint","amfFolderMsg","amfFolderInfo",
    "amfFolderStatus","amfFolderLabel","amfFolderName"
  ].forEach(id => {
    const el = document.getElementById(id);
    if (el) targets.push(el);
  });

  // common selectors (optional)
  targets.push(...Array.from(main.querySelectorAll(
    "[data-amf-status], .amf-status, .amf-status-text, .amf-folder-status, .amf-banner"
  )));

  // exact leftover text node inside VFX Mapping main panel
  const leftover = Array.from(main.querySelectorAll("*"))
    .find(n => n.childElementCount === 0 && (n.textContent || "").trim() === "No folder selected.");
  if (leftover) targets.push(leftover);

  const uniq = Array.from(new Set(targets.filter(Boolean)));
  uniq.forEach(el => { el.textContent = text || ""; });
}

// VFX Mapping export status helper (Action bar red-box)
function initAMFExportStatusUI(){
  const box = document.getElementById("amfExportStatusBox");
  const main = document.getElementById("amfExportStatusMain");
  const sub  = document.getElementById("amfExportStatusSub");
  if (!box || !main) return;

  function apply(state="idle", text="Status: Ready", subtext=""){
    const st = String(state || "idle").toLowerCase();

    box.classList.remove("is-idle","is-work","is-ok","is-err");
    if (st === "work" || st === "working" || st === "busy") box.classList.add("is-work");
    else if (st === "ok" || st === "success" || st === "done") box.classList.add("is-ok");
    else if (st === "err" || st === "error" || st === "fail" || st === "failed") box.classList.add("is-err");
    else box.classList.add("is-idle");

    main.textContent = text || "";
    if (sub){
      const s = String(subtext || "").trim();
      sub.textContent = s || "—";
    }

    // auto return to idle after a short time (keeps UI clean)
    try{ clearTimeout(box._mpsExportStatusTimer); }catch{}
    if (box.classList.contains("is-ok") || box.classList.contains("is-err")){
      box._mpsExportStatusTimer = setTimeout(() => {
        try{
          box.classList.remove("is-work","is-ok","is-err");
          box.classList.add("is-idle");
          main.textContent = "Status: Ready";
          if (sub) sub.textContent = "—";
        }catch{}
      }, 4500);
    }
  }

  // global hook for modules (amf_convert.js)
  window.MPS_setExportStatus = apply;

  // default
  apply("idle", "Status: Ready", "—");
}


