const amfSortState = { col: null, dir: 1 };

function _amfGetTable(){
  return (
    document.querySelector('#amfTableWrap table') ||
    document.querySelector('#amfTable table') ||
    document.querySelector('#main-amf table')
  );
}

function _amfLooksLikeHeaderRow(tr){
  try{
    const known = ["SHOT","SEQUENCE","EDL","LOOK","PATTERN","LOOK FILE","EDL USED"];
    const texts = Array.from(tr?.cells || []).map(c => String((c.innerText || c.textContent || "")).trim().toUpperCase());
    return known.some(k => texts.includes(k));
  }catch{
    return false;
  }
}

function _amfGetHeaderInfo(table){
  if (!table) return null;

  // Standard: <thead>
  if (table.tHead && table.tHead.rows && table.tHead.rows[0]){
    const row = table.tHead.rows[0];
    return { row, cells: Array.from(row.cells || []), headerInTbody: false };
  }

  // Fallback: first <tr> is treated as header (some legacy HTML uses tbody only)
  const row = (table.rows && table.rows[0]) ? table.rows[0] : table.querySelector('tr');
  if (!row) return null;
  const cells = Array.from(row.cells || row.children || []);
  const headerInTbody = !!row.closest('tbody') && _amfLooksLikeHeaderRow(row);
  return { row, cells, headerInTbody };
}

function _amfHeaderCellHasCheckbox(cell){
  return !!(cell && cell.querySelector && cell.querySelector('input[type=checkbox]'));
}

function _amfCellText(cell){
  if (!cell) return "";
  return String(cell.innerText || cell.textContent || "").trim().replace(/\s+/g, " ");
}

function _amfParseSortVal(text){
  const t = String(text || "").trim();
  if (!t || t === "—") return { t: "", n: NaN };

  const num = t
    .replace(/,/g, "")
    .replace(/f$/i, "")
    .replace(/%$/i, "");

  const n = /^-?\d+(?:\.\d+)?$/.test(num) ? Number(num) : NaN;
  return { t: t.toUpperCase(), n };
}

function _amfEnsureGroupClickHandler(table){
  const tbody = table && table.tBodies && table.tBodies[0];
  if (!tbody || tbody._amfGroupWired) return;
  tbody._amfGroupWired = true;

  // Click: collapse/expand groups (ignore clicks on the group checkbox)
  tbody.addEventListener('click', (e) => {
    if (e.target && e.target.closest && e.target.closest('input.amf-group-check')) return;
    const tr = e.target.closest('tr.amf-group-row');
    if (!tr) return;

    const key = tr.getAttribute('data-amf-group') || tr.dataset.group || '';
    const isCollapsed = tr.classList.toggle('collapsed');

    if (key){
      if (!amfGroupState.collapsed) amfGroupState.collapsed = new Set();
      if (isCollapsed) amfGroupState.collapsed.add(key);
      else amfGroupState.collapsed.delete(key);
    }

    const caret = tr.querySelector('.amf-group-caret');
    if (caret){
      caret.textContent = '';
      caret.classList.toggle('is-closed', isCollapsed);
      caret.classList.toggle('is-open', !isCollapsed);
    }

    // Hide/show children until the next group header
    let n = tr.nextElementSibling;
    while (n && !n.classList.contains('amf-group-row')){
      n.style.display = isCollapsed ? 'none' : '';
      n = n.nextElementSibling;
    }
  });

  // Change: group checkbox selects/deselects all children.
  // We dispatch "change" on each child checkbox so the VFX Mapping module updates its selection state.
  tbody.addEventListener('change', (e) => {
    const t = e.target;
    if (!t) return;

    // Group checkbox changed
    if (t.matches && t.matches('input.amf-group-check')){
      const tr = t.closest('tr.amf-group-row');
      if (!tr) return;
      const checked = !!t.checked;

      let n = tr.nextElementSibling;
      while (n && !n.classList.contains('amf-group-row')){
        const child = n.querySelector && n.querySelector('input.amf-shot-check');
        if (child && child.checked !== checked){
          child.checked = checked;
          child.dispatchEvent(new Event('change', { bubbles: true }));
        }
        n = n.nextElementSibling;
      }

      const table = _amfGetTable();
      if (table){
        requestAnimationFrame(() => {
          _amfUpdateGroupStates(table);
          amfApplyShowSelectedOnly();
        });
      }
      return;
    }

    // Any row selection change → refresh group states and Selected-only filter
    if ((t.matches && t.matches('input.amf-shot-check')) || (t.id === 'amfShotSelAll')){
      const table = _amfGetTable();
      if (table){
        requestAnimationFrame(() => {
          _amfUpdateGroupStates(table);
          amfApplyShowSelectedOnly();
        });
      }
    }
  });
}

function _amfMakeGroupRow(key, count, colSpan){
  const tr = document.createElement('tr');
  tr.className = 'amf-group-row';
  tr.dataset.group = key;
  tr.setAttribute('data-amf-group', key);

  // Keep the original total count so we can show Selected-only summary like "(2/18)".
  tr.dataset.total = String(count);

  // Column 0: group checkbox (select all children)
  const td0 = document.createElement('td');
  td0.className = 'amf-col-check amf-group-checkcell';
  const cb = document.createElement('input');
  cb.type = 'checkbox';
  cb.className = 'amf-group-check';
  cb.setAttribute('aria-label', `Select group ${key}`);
  td0.appendChild(cb);

  // Column 1..N: group label + caret
  const td = document.createElement('td');
  td.className = 'amf-group-cell';
  td.colSpan = Math.max(1, colSpan - 1);

  const caret = document.createElement('span');
  caret.className = 'amf-group-caret';

  const collapsed = amfGroupState.collapsed && amfGroupState.collapsed.has(key);
  caret.textContent = '';
  caret.classList.add(collapsed ? 'is-closed' : 'is-open');

  const label = document.createElement('span');
  label.className = 'amf-group-label';
  label.textContent = key || '—';

  const meta = document.createElement('span');
  meta.className = 'amf-group-meta';
  meta.textContent = ` (${count})`;

  td.appendChild(caret);
  td.appendChild(label);
  td.appendChild(meta);

  tr.appendChild(td0);
  tr.appendChild(td);

  if (collapsed) tr.classList.add('collapsed');
  return tr;
}

function _amfUpdateGroupStates(table){
  if (!table) return;
  const tbody = table.tBodies && table.tBodies[0];
  if (!tbody) return;

  // Build group -> {total, selected}
  const groups = new Map();
  [...tbody.rows].forEach((tr) => {
    if (tr.classList.contains('amf-group-row')){
      const key = tr.dataset.group || '';
      const total = Number(tr.dataset.total || 0);
      groups.set(key, { total, selected: 0, tr });
      return;
    }
    const key = tr.dataset.group;
    if (!key) return;
    const info = groups.get(key);
    if (!info) return;
    const cb = tr.querySelector('input.amf-shot-check');
    if (cb && cb.checked) info.selected += 1;
  });

  // Update UI (checkbox + meta)
  for (const [key, info] of groups.entries()){
    const tr = info.tr;
    const gcb = tr.querySelector('input.amf-group-check');
    const meta = tr.querySelector('.amf-group-meta');
    if (meta){
      const showSelectedOnly = !!amfGroupState.showSelectedOnly;
      meta.textContent = showSelectedOnly ? ` (${info.selected}/${info.total})` : ` (${info.total})`;
    }
    if (gcb){
      gcb.indeterminate = false;
      if (info.total <= 0){
        gcb.checked = false;
      } else if (info.selected === 0){
        gcb.checked = false;
      } else if (info.selected === info.total){
        gcb.checked = true;
      } else {
        gcb.checked = false;
        gcb.indeterminate = true;
      }
    }
  }
}

function _amfSortRows(table, col, dir){
  if (!table) return;
  const tbody = table.tBodies && table.tBodies[0];
  if (!tbody) return;

  let rows = Array.from(tbody.rows || []);
  if (rows.length <= 1) return;

  // Preserve legacy first-row header inside tbody (if any)
  let headerRow = null;
  if (!table.tHead && rows.length > 1 && _amfLooksLikeHeaderRow(rows[0])){
    headerRow = rows[0];
    rows = rows.slice(1);
  }

  // Remove any previously-inserted group rows
  rows = rows.filter(tr => tr && !tr.classList.contains('amf-group-row'));
  if (!rows.length) return;

  const colMap = amfGetTableHeaderColMap(table);
  const shotCol = (typeof colMap.shot === 'number') ? colMap.shot : 1;

  // Index map for stable sorting
  const idx = new Map();
  rows.forEach((tr, i) => idx.set(tr, i));

  function sortVal(tr){
    const cell = tr.cells && tr.cells[col];
    const t = _amfCellText(cell);
    // numeric if possible
    const n = Number(t);
    if (t && !Number.isNaN(n) && /^[-+]?\d+(?:\.\d+)?$/.test(t)) return n;
    return t;
  }

  function cmp(a, b){
    const va = sortVal(a);
    const vb = sortVal(b);
    let out = 0;
    if (typeof va === 'number' && typeof vb === 'number') out = va - vb;
    else out = String(va).localeCompare(String(vb));
    if (out === 0) out = (idx.get(a) || 0) - (idx.get(b) || 0);
    return dir * out;
  }

  // Group by shot prefix ("LMP_017" from "LMP_017_170")
  const groups = new Map();
  for (const tr of rows){
    const shot = _amfCellText(tr.cells && tr.cells[shotCol]);
    const g = amfExtractGroupKey(shot) || shot || '';
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push(tr);
  }

  const groupKeys = Array.from(groups.keys()).sort((a, b) => String(a).localeCompare(String(b)));
  const totalCols = headerRow ? headerRow.cells.length : (rows[0].cells ? rows[0].cells.length : 1);

  // Rebuild tbody: headerRow (optional) + group header rows + grouped rows
  const frag = document.createDocumentFragment();
  if (headerRow) frag.appendChild(headerRow);

  for (const g of groupKeys){
    const arr = groups.get(g) || [];
    if (typeof col === 'number') arr.sort(cmp);

    const gRow = _amfMakeGroupRow(g, arr.length, totalCols);
    frag.appendChild(gRow);

    const collapsed = amfGroupState.collapsed && amfGroupState.collapsed.has(g);
    for (const tr of arr){
      tr.dataset.group = g;
      tr.classList.add('amf-child-row');
      tr.style.display = collapsed ? 'none' : '';
      frag.appendChild(tr);
    }
  }

  tbody.innerHTML = '';
  tbody.appendChild(frag);

  _amfEnsureGroupClickHandler(table);

  // Keep group checkbox + meta in sync, and then apply Selected-only filtering if enabled.
  _amfUpdateGroupStates(table);
  amfApplyShowSelectedOnly();
}

function _amfUpdateArrows(table){
  if (!table) return;
  const info = _amfGetHeaderInfo(table);
  if (!info || !info.cells || !info.cells.length) return;

  const dir = amfSortState.dir || 1;

  info.cells.forEach((cell) => {
    if (_amfHeaderCellHasCheckbox(cell)) return;
    if (!cell || !cell.dataset) return;

    if (!cell.dataset._sortBaseHtml){
      cell.dataset._sortBaseHtml = cell.innerHTML;
    }

    const isActive =
      (typeof amfSortState.col === "number") &&
      (cell.cellIndex === amfSortState.col);

    cell.style.cursor = "pointer";
    cell.style.userSelect = "none";

    const arrow = isActive ? (dir > 0 ? "▲" : "▼") : "↕";
    const opacity = isActive ? 1 : 0.25;

    cell.innerHTML = cell.dataset._sortBaseHtml +
      `<span style="opacity:${opacity};margin-left:6px;">${arrow}</span>`;
  });
}

function applyAMFTableSortIfNeeded(){
  const table = _amfGetTable();
  if (!table) return;

  // Always show ↕ on headers like the EDL Convert table
  _amfUpdateArrows(table);

  // Default: Group by Shot on first render
  if (typeof amfSortState.col !== "number"){
    const colMap = amfGetTableHeaderColMap(table);
    if (typeof colMap.shot === "number"){
      amfSortState.col = colMap.shot;
      amfSortState.dir = 1;
    }
  }

  // Re-apply last sort after re-render
  if (typeof amfSortState.col === "number"){
    _amfSortRows(table, amfSortState.col, amfSortState.dir);
  }
}

// VFX Mapping table: show only selected rows (checked) when any are selected
function amfApplyShowSelectedOnly(){
  const table = _amfGetTable();
  if (!table) return;
  const tbody = table.tBodies && table.tBodies[0];
  if (!tbody) return;
  const rows = Array.from(tbody.rows || []);

  // Detect if we have any selected items at all.
  let anySelected = false;
  for (const tr of rows){
    if (tr.classList && tr.classList.contains('amf-group-row')) continue;
    const cb = tr.querySelector && tr.querySelector('input.amf-shot-check');
    if (cb && cb.checked){ anySelected = true; break; }
  }

  // Build per-group counts so group rows can show (selected/total) when filtered.
  const counts = new Map(); // key -> {total, sel}
  for (const tr of rows){
    if (tr.classList && tr.classList.contains('amf-group-row')) continue;
    const key = tr.dataset.group || '';
    if (!key) continue;
    const cb = tr.querySelector && tr.querySelector('input.amf-shot-check');
    const st = counts.get(key) || { total: 0, sel: 0 };
    st.total++;
    if (cb && cb.checked) st.sel++;
    counts.set(key, st);
  }

  // Apply visibility rules:
  // - When anySelected: show only selected rows, but keep group headers for groups that contain selections.
  // - When none selected: show everything and restore group meta.
  for (const tr of rows){
    const isGroup = !!(tr.classList && tr.classList.contains('amf-group-row'));
    if (isGroup){
      const key = tr.dataset.group || '';
      const st = counts.get(key) || { total: Number(tr.dataset.total || 0) || 0, sel: 0 };
      const meta = tr.querySelector && tr.querySelector('.amf-group-meta');
      if (anySelected){
        tr.style.display = st.sel > 0 ? '' : 'none';
        if (meta) meta.textContent = ` (${st.sel}/${st.total})`;
      } else {
        tr.style.display = '';
        if (meta) meta.textContent = ` (${st.total})`;
      }
      continue;
    }

    const cb = tr.querySelector && tr.querySelector('input.amf-shot-check');
    if (!cb){ tr.style.display = ''; continue; }
    tr.style.display = anySelected ? (cb.checked ? '' : 'none') : '';
  }
}

let _amfSelFilterRAF = 0;
function amfRequestApplyShowSelectedOnly(){
  try{
    if (_amfSelFilterRAF) cancelAnimationFrame(_amfSelFilterRAF);
    _amfSelFilterRAF = requestAnimationFrame(() => {
      _amfSelFilterRAF = 0;
      try{ amfApplyShowSelectedOnly(); }catch{}
    });
  }catch{
    try{ amfApplyShowSelectedOnly(); }catch{}
  }
}


function wireAMFTableSorting(){
  const wrap = document.getElementById("amfTableWrap") || document.getElementById("amfTable");
  if (!wrap || wrap._amfSortWired) return;

  on(wrap, "click", (ev) => {
    const cell = ev.target && ev.target.closest ? ev.target.closest("th,td") : null;
    if (!cell) return;

    // Ignore checkbox clicks
    if (ev.target && ev.target.matches && ev.target.matches("input[type=checkbox]")) return;
    if (_amfHeaderCellHasCheckbox(cell)) return;

    const table = cell.closest("table");
    if (!table) return;

    const info = _amfGetHeaderInfo(table);
    if (!info || !info.row) return;

    // Only header row is sortable
    if (cell.parentElement !== info.row) return;

    const col = cell.cellIndex;
    if (typeof col !== "number" || col < 0) return;

    if (amfSortState.col === col) amfSortState.dir *= -1;
    else { amfSortState.col = col; amfSortState.dir = 1; }

    _amfSortRows(table, amfSortState.col, amfSortState.dir);
    _amfUpdateArrows(table);
  });

  on(wrap, "change", (ev) => {
    if (!ev.target || !ev.target.matches) return;
    if (!ev.target.matches("input[type=checkbox]")) return;
    amfRequestApplyShowSelectedOnly();
  });

  wrap._amfSortWired = true;
}


// -------------------------------------------------------------
// VFX Mapping — Group by Shot (fast selection) + Export NK per group
// -------------------------------------------------------------
const amfGroupState = {
  groups: new Map(),
  shotCol: null,
  colMap: {},
  totalShots: 0,
  lastSig: "",
  observer: null,
  observedWrap: null,
  debounce: null,
  wired: false,
  exportWired: false,
  collapsed: new Set()
};

function amfExtractGroupKey(shotName){
  const s = String(shotName || "").trim();
  if (!s) return "";
  const parts = s.split(/[_\s]+/).filter(Boolean);
  // Shot grouping policy (Plate Link):
  // Group by the first 3 tokens to match common VFX shot naming.
  // Example: HSM_104_001_010_PL01_v001 -> HSM_104_001
  // Fallback: first 2 tokens.
  if (parts.length >= 3) return parts[0] + "_" + parts[1] + "_" + parts[2];
  if (parts.length >= 2) return parts[0] + "_" + parts[1];
  return s;
}

function amfGetTableHeaderColMap(table){
  const info = _amfGetHeaderInfo(table);
  const out = {};
  if (!info?.cells?.length) return out;
  for (const cell of info.cells){
    const idx = cell.cellIndex;
    const t = _amfCellText(cell).toUpperCase();
    if (!t) continue;
    if (t === "SHOT") out.shot = idx;
    else if (t === "SEQUENCE") out.sequence = idx;
    else if (t === "EDL") out.edl = idx;
    else if (t === "LOOK") out.look = idx;
    else if (t === "PATTERN") out.pattern = idx;
    else if (t === "LOOK FILE") out.lookFile = idx;
    else if (t === "EDL USED") out.edlUsed = idx;
  }
  return out;
}

function amfBuildGroupsFromTable(){
  const table = _amfGetTable();
  const groups = new Map();
  if (!table) return { table:null, groups, totalShots:0, shotCol:null, colMap:{} };

  const colMap = amfGetTableHeaderColMap(table);
  const shotCol = (typeof colMap.shot === "number") ? colMap.shot : 1;
  const tbody = table.tBodies && table.tBodies[0];
  const rows = tbody ? Array.from(tbody.rows || []) : [];

  let total = 0;
  for (const tr of rows){
    if (!tr || !tr.cells || !tr.cells.length) continue;
    if (!table.tHead && _amfLooksLikeHeaderRow(tr)) continue;
    if (tr.classList && tr.classList.contains('amf-group-row')) continue;

    const shot = _amfCellText(tr.cells[shotCol]);
    if (!shot) continue;

    total += 1;
    const g = amfExtractGroupKey(shot) || shot;
    if (!groups.has(g)) groups.set(g, []);

    const cb = tr.querySelector("input[type=checkbox]");
    groups.get(g).push({ tr, cb, shot });
  }

  return { table, groups, totalShots: total, shotCol, colMap };
}

function amfRefreshGroupUI(force=false){
  const sel = document.getElementById("amfGroupSelect");
  const infoEl = document.getElementById("amfGroupInfo");
  if (!sel) return;

  const built = amfBuildGroupsFromTable();
  const sig = built.table ? (built.totalShots + "|" + built.groups.size) : "0|0";
  if (!force && sig === amfGroupState.lastSig) return;

  amfGroupState.lastSig = sig;
  amfGroupState.groups = built.groups;
  amfGroupState.totalShots = built.totalShots;
  amfGroupState.shotCol = built.shotCol;
  amfGroupState.colMap = built.colMap;

  const current = sel.value || "";
  const keys = Array.from(built.groups.keys()).sort((a,b)=>a.localeCompare(b, undefined, { numeric:true, sensitivity:"base" }));

  sel.innerHTML = '<option value="">—</option>' + keys.map(k => {
    const n = built.groups.get(k)?.length || 0;
    return '<option value="' + esc(k) + '">' + esc(k) + ' (' + n + ')</option>';
  }).join("");

  if (current && built.groups.has(current)) sel.value = current;
  else sel.value = "";

  sel.disabled = !built.table || keys.length === 0;

  if (infoEl){
    infoEl.textContent = (!built.table || !built.totalShots)
      ? "No shots"
      : ('Groups: ' + built.groups.size + ' • Shots: ' + built.totalShots);
  }
}

function amfDispatchChange(el){
  try{ el.dispatchEvent(new Event("change", { bubbles:true })); }catch{}
}

function amfClearShotSelection(){
  const table = _amfGetTable();
  if (!table) return;

  const cbs = Array.from(table.querySelectorAll("tbody input[type=checkbox]"));
  for (const cb of cbs){
    if (cb && !cb.disabled && cb.checked){
      cb.checked = false;
      amfDispatchChange(cb);
    }
  }

  // header checkbox (if any)
  const headCb = table.querySelector("thead input[type=checkbox]") ||
                 (table.rows && table.rows[0] ? table.rows[0].querySelector("input[type=checkbox]") : null);
  if (headCb){
    headCb.checked = false;
    headCb.indeterminate = false;
    amfDispatchChange(headCb);
  }
}

function amfSelectGroup(groupKey, mode='replace'){
  if (!groupKey) return;
  amfRefreshGroupUI();
  const rows = amfGroupState.groups.get(groupKey) || [];
  if (!rows.length) return;

  if (mode === 'replace') amfClearShotSelection();

  for (const r of rows){
    const cb = r.cb || r.tr?.querySelector?.("input[type=checkbox]");
    if (cb && !cb.disabled && !cb.checked){
      cb.checked = true;
      amfDispatchChange(cb);
    }
  }
}

function amfGetSelectedShotsFromDom(){
  const table = _amfGetTable();
  if (!table) return [];

  const colMap = amfGetTableHeaderColMap(table);
  const shotCol = (typeof amfGroupState.shotCol === 'number') ? amfGroupState.shotCol : ((typeof colMap.shot === 'number') ? colMap.shot : 1);

  const tbody = table.tBodies && table.tBodies[0];
  const rows = tbody ? Array.from(tbody.rows || []) : [];
  const out = [];

  for (const tr of rows){
    if (!tr || !tr.cells || !tr.cells.length) continue;
    if (!table.tHead && _amfLooksLikeHeaderRow(tr)) continue;
    if (tr.classList && tr.classList.contains('amf-group-row')) continue;

    const cb = tr.querySelector("input[type=checkbox]");
    if (!cb || !cb.checked) continue;

    const shot = _amfCellText(tr.cells[shotCol]);
    if (shot) out.push(shot);
  }

  return out;
}

function amfFindEdlTitleInDom(){
  const wrap = document.getElementById('amfTableWrap');
  if (!wrap) return '';

  // Prefer explicit label text if present
  const nodes = Array.from(wrap.querySelectorAll('*')).filter(n => n.childElementCount === 0);
  const hit = nodes.find(n => /EDL\s*Title\s*:/i.test((n.textContent || '')));
  if (!hit) return '';

  const m = String(hit.textContent || '').match(/EDL\s*Title\s*:\s*(.+)$/i);
  return m ? String(m[1]).trim() : '';
}

function amfIsOkCell(text){
  const t = String(text || '').trim().toUpperCase();
  return t === 'OK' || t === 'YES' || t === 'TRUE' || t === 'READY';
}

function amfFilterAMFResultByShotSet(orig, shotSet){
  if (!orig || !shotSet || !shotSet.size) return orig;

  const pickName = (o) => {
    if (!o) return '';
    return String(o.shot || o.shotName || o.name || o.id || '').trim();
  };

  const sub = { ...orig };

  if (Array.isArray(orig.shots)) sub.shots = orig.shots.filter(x => shotSet.has(pickName(x)));
  if (Array.isArray(orig.rows))  sub.rows  = orig.rows.filter(x  => shotSet.has(pickName(x)));

  if (orig.mapping && typeof orig.mapping === 'object' && !Array.isArray(orig.mapping)) {
    const m2 = {};
    for (const k of Object.keys(orig.mapping)){
      if (shotSet.has(k)) m2[k] = orig.mapping[k];
    }
    sub.mapping = m2;
  }

  // best-effort stats
  const list = Array.isArray(sub.shots) ? sub.shots : (Array.isArray(sub.rows) ? sub.rows : []);
  const ready = list.filter(o => {
    const seq = o.sequence ?? o.seq ?? o.sequenceOk ?? o.seqOk;
    const edl = o.edl ?? o.edlOk;
    const look = o.look ?? o.lookOk;
    const seqOk = (typeof seq === 'boolean') ? seq : amfIsOkCell(seq);
    const edlOk = (typeof edl === 'boolean') ? edl : amfIsOkCell(edl);
    const lookOk = (typeof look === 'boolean') ? look : amfIsOkCell(look);
    return seqOk && edlOk && lookOk;
  }).length;

  sub.stats = {
    shots: list.length,
    ready: ready,
    missing: Math.max(0, list.length - ready)
  };

  return sub;
}

function amfCompatResultFromTable(shotSet, groupKey='', titleSuffix=''){
  const table = _amfGetTable();
  const titleBase = (amfResult && (amfResult.edlTitle || amfResult.title)) ? String(amfResult.edlTitle || amfResult.title) : (amfFindEdlTitleInDom() || 'VFX_MAPPING');
  const title = titleSuffix ? (titleBase + '_' + titleSuffix) : titleBase;

  const nativeRoot = (document.getElementById('amfNativeRootText')?.textContent || '').trim();

  const outShots = [];
  const mapping = {};

  if (table){
    const colMap = amfGetTableHeaderColMap(table);
    const shotCol = (typeof colMap.shot === 'number') ? colMap.shot : 1;

    const tbody = table.tBodies && table.tBodies[0];
    const rows = tbody ? Array.from(tbody.rows || []) : [];

    const cell = (tr, idx) => {
      try{ return (typeof idx === 'number') ? _amfCellText(tr.cells[idx]) : ''; }catch{ return ''; }
    };

    for (const tr of rows){
      if (!tr || !tr.cells || !tr.cells.length) continue;
      if (!table.tHead && _amfLooksLikeHeaderRow(tr)) continue;
    if (tr.classList && tr.classList.contains('amf-group-row')) continue;

      const shot = _amfCellText(tr.cells[shotCol]);
      if (!shot) continue;
      if (shotSet && shotSet.size && !shotSet.has(shot)) continue;

      const seqTxt  = cell(tr, colMap.sequence);
      const edlTxt  = cell(tr, colMap.edl);
      const lookTxt = cell(tr, colMap.look);

      const pattern = cell(tr, colMap.pattern);
      const lookFile = cell(tr, colMap.lookFile);
      const edlUsed = cell(tr, colMap.edlUsed);

      const obj = {
        shot: shot,
        shotName: shot,
        name: shot,
        groupKey: groupKey || amfExtractGroupKey(shot),

        sequence: seqTxt,
        edl: edlTxt,
        look: lookTxt,

        sequenceOk: amfIsOkCell(seqTxt),
        edlOk: amfIsOkCell(edlTxt),
        lookOk: amfIsOkCell(lookTxt),

        pattern: pattern,
        sequencePattern: pattern,
        lookFile: lookFile,
        lookPath: lookFile,
        edlUsed: edlUsed,
        edlPath: edlUsed
      };

      outShots.push(obj);
      mapping[shot] = obj;
    }
  }

  const ready = outShots.filter(s => s.sequenceOk && s.edlOk && s.lookOk).length;

  return {
    rootName: title,
    edlTitle: title,
    title: title,
    nativeRoot: nativeRoot,
    stats: { shots: outShots.length, ready: ready, missing: Math.max(0, outShots.length - ready) },
    shots: outShots,
    rows: outShots,
    mapping: mapping
  };
}

function wireAMFGroupByShotControls(){
  if (amfGroupState.wired) return;
  amfGroupState.wired = true;

  const sel = document.getElementById('amfGroupSelect');
  const addBtn = document.getElementById('amfGroupAdd');
  const clearBtn = document.getElementById('amfGroupClearSel');

  if (sel){
    sel.addEventListener('change', () => {
      const g = sel.value || '';
      if (!g) return;
      amfSelectGroup(g, 'replace');
    });
  }

  if (addBtn){
    addBtn.addEventListener('click', () => {
      const g = sel?.value || '';
      if (!g) return;
      amfSelectGroup(g, 'add');
    });
  }

  if (clearBtn){
    clearBtn.addEventListener('click', () => {
      amfClearShotSelection();
    });
  }

  const syncObserver = () => {
    const wrap = document.getElementById('amfTableWrap');
    if (amfGroupState.debounce) {
      clearTimeout(amfGroupState.debounce);
      amfGroupState.debounce = null;
    }
    if (!amfGroupState.observer){
      amfGroupState.observer = new MutationObserver(() => {
        if (!isAmfVisible()) return;
        if (amfGroupState.debounce) clearTimeout(amfGroupState.debounce);
        amfGroupState.debounce = setTimeout(() => {
          if (!isAmfVisible()) return;
          amfRefreshGroupUI(true);
        }, 60);
      });
    }
    try{ amfGroupState.observer.disconnect(); }catch{}
    amfGroupState.observedWrap = null;
    if (!wrap || !isAmfVisible()) return;
    amfGroupState.observer.observe(wrap, { childList:true, subtree:true });
    amfGroupState.observedWrap = wrap;
    setTimeout(() => {
      if (isAmfVisible()) amfRefreshGroupUI(true);
    }, 0);
  };

  document.addEventListener('visibilitychange', syncObserver, { passive:true });
  document.addEventListener('mps:mainTabChanged', syncObserver, { passive:true });
  syncObserver();
}

function wireAMFExportNkPerGroup(){
  if (amfGroupState.exportWired) return;
  const btn = document.getElementById('amfExportNukeNK');
  if (!btn) return;

  amfGroupState.exportWired = true;

  btn.addEventListener('click', async (e) => {
    const _retry = () => setTimeout(() => { try{ btn.click(); }catch{} }, 0);
    try{ if (!(await window.MPS_validateBeforeExport?.("exr", _retry))) return; }catch{}

    // New VFX Mapping UI renders shot cards inside grouped rows.
    // In this mode, we do NOT override the module's exporter behavior (avoid mis-parsing shot names from card text).
    try{
      const vfxCards = document.querySelector('#main-amf table[data-mps-vfxcards="1"]');
      if (vfxCards) return;
    }catch{}

    const hasExporter = !!(AMF && (typeof AMF.exportNukeNK === 'function' || typeof AMF.exportNukeScriptNK === 'function'));
    if (!hasExporter) return; // let normal behavior handle errors

    // Build grouping either from explicit user selection OR from the full table.
    // User request: Nuke export should be per *group shot* (even if nothing is selected).
    let selectedShots = amfGetSelectedShotsFromDom();
    const groups = new Map();

    if (!selectedShots.length){
      // No selection => export ALL shots, split by group.
      const built = amfBuildGroupsFromTable();
      if (!built?.table || !built?.groups?.size) return;
      for (const [g, items] of built.groups.entries()){
        const shots = (items || []).map(it => it?.shot).filter(Boolean);
        if (shots.length) groups.set(g, shots);
      }
      selectedShots = Array.from(groups.values()).flat();
      if (!selectedShots.length) return;
    }else{
      for (const s of selectedShots){
        const g = amfExtractGroupKey(s) || s;
        if (!groups.has(g)) groups.set(g, []);
        groups.get(g).push(s);
      }
    }

    // Override default: export one .nk per group
    if (e.cancelable) e.preventDefault();
    e.stopImmediatePropagation();
    e.stopPropagation();

    const exporter = (typeof AMF.exportNukeNK === 'function') ? AMF.exportNukeNK : AMF.exportNukeScriptNK;

    // Smart behavior (B):
    // - If selection spans only ONE group: export ONE .nk for selected shots, without adding a _GROUP suffix.
    // - If selection spans MULTIPLE groups: export one .nk per group, adding _GROUP suffix.
    const multiGroup = groups.size > 1;

    if (!multiGroup){
      const onlyKey = Array.from(groups.keys())[0] || '';
      const shots = groups.get(onlyKey) || selectedShots;
      const set = new Set(shots);

      let sub = null;
      if (amfResult){
        sub = amfFilterAMFResultByShotSet(amfResult, set);
        const baseTitle = String(sub?.edlTitle || sub?.title || sub?.rootName || amfFindEdlTitleInDom() || 'VFX_MAPPING');
        sub = { ...sub, edlTitle: baseTitle, title: baseTitle, rootName: baseTitle };
      } else {
        sub = amfCompatResultFromTable(set, onlyKey, onlyKey);
      }

      try{
        exporter(sub);
      } catch(err){
        console.error('Export NK (single group) failed:', err);
        showError(err?.message || String(err));
      }
      return;
    }

    for (const [g, shots] of groups.entries()){
      const set = new Set(shots);

      let sub = null;
      if (amfResult){
        sub = amfFilterAMFResultByShotSet(amfResult, set);
        const baseTitle = String(sub?.edlTitle || sub?.title || sub?.rootName || amfFindEdlTitleInDom() || 'VFX_MAPPING');
        sub = { ...sub, edlTitle: baseTitle + '_' + g, title: baseTitle + '_' + g, rootName: baseTitle + '_' + g };
      } else {
        sub = amfCompatResultFromTable(set, g, g);
      }

      try{
        exporter(sub);
      } catch(err){
        console.error('Export NK per group failed:', err);
        showError(err?.message || String(err));
        break;
      }

      // Yield to keep UI responsive + avoid download throttling
      await new Promise(r => setTimeout(r, 40));
    }
  }, true); // capture = true (override module click)
}

// Native Host (.aep) — state
let amfNativeRoot = "";

// Auto-load EDL from selected VFX folder (prefer Attached_Files).
// We only auto-override the timeline when the current timeline was also auto-loaded.
let autoLoadingVfxEdl = false;
let lastLoadWasAutoVfxEdl = false;
let amfNativeBase = "";
let amfSelectedRootName = ""; // last chosen VFX root folder name (for UI sync; no prompt on choose)
let aepActiveRequestId = null;
let aepLastFileName = "VFX_Project.aep";
let aepChunkTotal = 0;
let aepChunks = [];

function safeFileName(name=""){
  const s = String(name || "");
  const cleaned = s
    .replace(/\s+/g, "_")
    .replace(/[\/:*?"<>|]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  return cleaned || "VFX_Project.aep";
}

function loadAmfNativeRoot(){
  try { amfNativeRoot = localStorage.getItem("mps.amf.nativeRoot") || ""; } catch {}
  try { amfNativeBase = localStorage.getItem("mps.amf.nativeBase") || ""; } catch {}
  try { amfSelectedRootName = localStorage.getItem("mps.amf.rootName") || ""; } catch {}
  updateAmfNativeRootUI();
}
function updateAmfNativeRootUI(text){
  const el = getById("amfNativeRootText", "amfNativeRootLabel", "amfNativeRoot");
  if (!el) return;
  if (typeof text === "string") { el.textContent = text; return; }
  const fallback = (amfSelectedRootName && String(amfSelectedRootName).trim()) ? String(amfSelectedRootName).trim() : "—";
  el.textContent = (amfNativeRoot && String(amfNativeRoot).trim()) ? String(amfNativeRoot).trim() : fallback;
}
function amfNormSlash(p = "")
{
  return String(p || "").replace(/\\/g, "/");
}

function amfTrimSlashEnd(p = ""){
  const s = amfNormSlash(p).trim();
  // keep "C:/" as-is, but trim extra trailing slashes
  if (/^[A-Za-z]:\/$/.test(s)) return s;
  return s.replace(/\/+$/g, "");
}

function amfDirName(p = ""){
  const s = amfTrimSlashEnd(p);
  if (!s) return "";
  const i = s.lastIndexOf("/");
  if (i < 0) return "";
  if (i == 0) return "/";
  return s.slice(0, i);
}

function amfJoinPath(a = "", b = ""){
  const aa = amfTrimSlashEnd(a);
  const bb = amfNormSlash(b).replace(/^\/+/, "");
  if (!aa) return bb;
  if (!bb) return aa;
  return aa + "/" + bb;
}

function getSelectedVfxRootName(){
  // 1) legacy UI scan result
  let name = (amfResult && amfResult.rootName) ? String(amfResult.rootName) : "";

  // 2) module-owned UI (preferred)
  if (!name && AMF && typeof AMF.getLastResult === "function"){
    try{
      const r = AMF.getLastResult();
      if (r && r.rootName) name = String(r.rootName);
    } catch {}
  }

  // 3) derive from selected files (webkitRelativePath root segment)
  if (!name){
    let files = (amfFiles && amfFiles.length) ? amfFiles : null;
    if (!files && AMF && typeof AMF.getLastFiles === "function"){
      try{ files = AMF.getLastFiles(); } catch { files = null; }
    }
    for (const f of (files || [])){
      const wp = amfNormSlash(f?.webkitRelativePath || f?.virtualPath || "");
      if (wp.includes("/")){
        name = wp.split("/")[0];
        break;
      }
    }
  }

  return String(name || "").trim() || "";
}

function deriveAmfNativeBase(rootName = ""){
  const baseStored = amfTrimSlashEnd(amfNativeBase);
  if (baseStored) return baseStored;

  const nr = amfTrimSlashEnd(amfNativeRoot);
  if (!nr) return "";

  const last = nr.split("/").pop() || "";
  if (rootName && last === rootName) return amfDirName(nr) || "";

  // If the stored nativeRoot doesn't end with rootName, treat it as BASE path
  return nr;
}

function computeAmfNativeBaseFromInput(inputPath = "", selectedRootName = ""){
  const p = amfTrimSlashEnd(inputPath);
  if (!p) return "";
  const last = p.split("/").pop() || "";

  // If user typed a base folder (not the selected root), store as base
  if (selectedRootName && last && last !== selectedRootName) return p;

  // Otherwise store the parent folder as base
  const d = amfDirName(p);
  return d || p;
}

function setAmfNativeRoot(path, selectedRootName = ""){
  amfNativeRoot = String(path || "").trim();
  try { localStorage.setItem("mps.amf.nativeRoot", amfNativeRoot); } catch {}

  amfNativeBase = computeAmfNativeBaseFromInput(amfNativeRoot, selectedRootName);
  try { localStorage.setItem("mps.amf.nativeBase", amfNativeBase); } catch {}

  updateAmfNativeRootUI();
}

function autoSyncAmfNativeRootFromFiles(files){
  // Chrome's folder picker doesn't expose absolute paths.
  // Auto-sync is only possible by combining a user-provided BASE path
  // (stored in localStorage) with the selected folder name.

  const list = Array.isArray(files) ? files : Array.from(files || []);
  if (!list.length) return false;

  // Derive root folder name from webkitRelativePath ("Root/...")
  let rootName = "";
  for (const f of list){
    const wp = amfNormSlash(f?.webkitRelativePath || f?.virtualPath || "");
    if (wp && wp.includes("/")){
      rootName = wp.split("/")[0] || "";
      break;
    }
  }
  rootName = String(rootName || "").trim();
  if (!rootName) return false;

  amfSelectedRootName = rootName;
  try { localStorage.setItem("mps.amf.rootName", amfSelectedRootName); } catch {}
  // Update UI label even if absolute base path is unknown (no prompt on choose).
  updateAmfNativeRootUI();

  const base = deriveAmfNativeBase(rootName);
  if (!base) return false;

  const next = amfJoinPath(base, rootName);
  if (!next) return false;
  if (next === amfNativeRoot) return true;

  setAmfNativeRoot(next, rootName);
  return true;
}

// Auto-load an .edl found under the chosen VFX folder (default: Attached_Files)
async function autoLoadEdlFromVfxFolder(files){
  try{
    if(!files || !files.length) return;

    // Don't override a timeline the user loaded manually.
    if(raw?.events?.length && !lastLoadWasAutoVfxEdl) return;

    const candidates = [];
    for(const f of files){
      const n = (f?.name||"").toLowerCase();
      if(!n.endsWith(".edl")) continue;
      const rp = f.webkitRelativePath || f.relativePath || f.name || "";
      const rpl = rp.toLowerCase();
      const inAttached = rpl.includes("/attached_files/") || rpl.includes("\\attached_files\\") || rpl.startsWith("attached_files/") || rpl.includes("attached_files/");
      const depth = rp.split(/[\\/]/).filter(Boolean).length;
      candidates.push({ f, rp, inAttached, depth, size: f.size||0 });
    }
    if(!candidates.length) return;

    candidates.sort((a,b)=>{
      if(a.inAttached !== b.inAttached) return a.inAttached ? -1 : 1;
      if(a.depth !== b.depth) return a.depth - b.depth;
      return (b.size||0) - (a.size||0);
    });

    const best = candidates[0];
    autoLoadingVfxEdl = true;
    await handleFiles([best.f]);
    autoLoadingVfxEdl = false;

    // Mark that the current timeline came from auto-load so future folder picks can replace it.
    lastLoadWasAutoVfxEdl = true;
    console.log("📌 Auto-loaded EDL from VFX folder: " + best.rp);
  }catch(err){
    autoLoadingVfxEdl = false;
    console.warn("Auto-load EDL failed", err);
  }
}

function promptSetAmfNativeRoot(){
  const rootName = getSelectedVfxRootName();

  // If we already know a base path + selected folder name → auto-sync (no prompt)
  if (rootName){
    const base = deriveAmfNativeBase(rootName);
    if (base){
      const newRoot = amfJoinPath(base, rootName);
      setAmfNativeRoot(newRoot, rootName);
      return !!amfNativeRoot;
    }
  }

  // Otherwise ask once (prefill with best guess)
  const cur = String(amfNativeRoot || "").trim();
  let hint = cur;

  // Try best-effort guess using stored base + current selected folder name.
  if (!hint){
    const base = String(amfNativeBase || "").trim();
    if (base && rootName) hint = amfJoinPath(base, rootName);
    else if (base) hint = base;
  }

  // IMPORTANT: do not prefill with fake "/Users/<you>/..." placeholders.
  // Put guidance in the prompt message instead, and keep the input empty unless
  // we already have a real path.
  const example = rootName
    ? `/Users/YOUR_USERNAME/Movies/${rootName}`
    : `/Users/YOUR_USERNAME/Movies/<VFX_ROOT>`;
  const msg = `Set Native VFX Root (absolute path)\nExample: ${example}`;

  const path = prompt(msg, hint || "");
  if (path === null) return false;

  const p = String(path || "").trim();
  if (!p){
    showError("Native VFX Root is required.");
    return false;
  }
  if (/(<you>|<username>|YOUR_USERNAME)/i.test(p)){
    showError("Please replace YOUR_USERNAME with your macOS username.");
    return false;
  }

  setAmfNativeRoot(p, rootName);
  return !!amfNativeRoot;
}

function buildAMFMappingPayload(result){
  const payload = {
    generatedAt: new Date().toISOString(),
    rootName: result?.rootName || "VFX_ROOT",
    fps: result?.fps || 24,
    edlRoot: result?.edlRoot || null,
    stats: result?.stats || {},
    shots: (result?.shots || []).map(s => ({
      shotName: s.shotName,
      compName: s.compName || s.locShotName || s.shotName || null,
      locShotName: s.locShotName || null,
      scopeOfWork: String(s?.scopeOfWork || s?.sow || "").trim() || null,
      seq: s.seq ? {
        firstFileRel: s.seq.firstFileRel,
        patternRel: s.seq.patternRel,
        start: s.seq.start,
        end: s.seq.end,
        padding: s.seq.padding,
        ext: s.seq.ext,
        count: s.seq.count
      } : null,
      look: s.look ? {
        relPath: s.look.relPath,
        type: s.look.type,
        cdl: s.look.cdl || null,
        cdlWorkingSpace: s.look.cdlWorkingSpace || null,
        amfLooks: Array.isArray(s.look.amfLooks) ? s.look.amfLooks.slice() : null,
        amfLooksAll: Array.isArray(s.look.amfLooksAll) ? s.look.amfLooksAll.slice() : null,
        amfCdlApplied: (typeof s.look.amfCdlApplied === "boolean") ? s.look.amfCdlApplied : null
      } : null,
      edl: s.edl ? {
        relPath: s.edl.relPath,
        mode: s.edl.mode,
        hits: (s.edl.hits || []).map(h => ({
          num: h.num,
          reel: h.reel,
          srcIn: h.srcIn,
          srcOut: h.srcOut,
          recIn: h.recIn,
          recOut: h.recOut,
          speedPct: (Number(h.speedPct) || 100),
          speedIsDynamic: !!h.speedIsDynamic,
          speedRaw: h.speedRaw || null
        }))
      } : null,
      flags: s.flags || null
    }))
  };
  return payload;
}

function aepResetChunks(){
  aepChunkTotal = 0;
  aepChunks = [];
}

function aepUI(){
  return {
    panel: getById("amfAepProgress"),
    dot: getById("amfAepDot"),
    status: getById("amfAepStatus"),
    step: getById("amfAepStep"),
    bar: getById("amfAepBar"),
    log: getById("amfAepLog"),
    hint: getById("amfAepHint"),
    install: getById("amfAeInstallPanel"),
    btnCopy: getById("amfAepCopyPath"),
    btnClose: getById("amfAepClose"),
  };
}

function aepShow(){
  const ui = aepUI();
  if (ui.panel) ui.panel.style.display = "block";
}

function aepHide(){
  const ui = aepUI();
  if (ui.panel) ui.panel.style.display = "none";
}

function aepSet(status="", step="", pct=null, level="busy"){
  const ui = aepUI();
  if (ui.status) ui.status.textContent = status || "";
  if (ui.step) ui.step.textContent = step || "";
  if (ui.bar && typeof pct === "number") ui.bar.style.width = `${Math.max(0, Math.min(100, pct))}%`;

  if (ui.dot){
    const c = level === "ok" ? "rgba(0,255,197,0.85)"
            : level === "err" ? "rgba(255,76,76,0.90)"
            : level === "warn" ? "rgba(255,199,92,0.90)"
            : "rgba(186,0,255,0.85)";
    ui.dot.style.background = c;
    ui.dot.style.boxShadow = "0 0 0 3px rgba(255,255,255,0.06), 0 0 18px rgba(186,0,255,0.18)";
  }
}

function aepHint(text="", show=true){
  const ui = aepUI();
  if (!ui.hint) return;
  ui.hint.textContent = text || "";
  ui.hint.style.display = (show && text) ? "block" : "none";
}

function aepInstallPanel(html="", show=true){
  const ui = aepUI();
  if (!ui.install) return;
  ui.install.innerHTML = html || "";
  ui.install.style.display = (show && html) ? "block" : "none";
}

function aepLog(line=""){
  const ui = aepUI();
  if (!ui.log) return;
  const prev = ui.log.textContent || "";
  const next = prev ? (prev + "\n" + String(line)) : String(line);
  // keep last ~200 lines
  const parts = next.split(/\r?\n/);
  const trimmed = parts.slice(-200).join("\n");
  ui.log.textContent = trimmed;
  ui.log.scrollTop = ui.log.scrollHeight;
}


function bgSend(message){
  return new Promise((resolve) => {
    try{
      chrome.runtime.sendMessage(message, (resp) => {
        const err = chrome.runtime.lastError?.message;
        if (err) return resolve({ ok:false, error: err });
        resolve(resp || { ok:true });
      });
    } catch(e){
      resolve({ ok:false, error: e?.message || String(e) });
    }
  });
}


function prettyJSON(v){
  try{ return JSON.stringify(v, null, 2); } catch { return String(v); }
}

// HTML-escape helper for status/help panels (prevents broken UI when errors include < > etc.)
function escapeHtml(v){
  const s = String(v ?? "");
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function nativeExtId(){
  try{ return chrome?.runtime?.id || ""; } catch { return ""; }
}

function nativeExtOrigin(){
  const id = nativeExtId();
  return id ? `chrome-extension://${id}/` : "";
}

function isNativeForbiddenError(msg){
  const m = String(msg || "");
  return /forbidden/i.test(m) || /native messaging host is forbidden/i.test(m);
}

// Prefer direct Native Host .aep build when available; fall back to file-based handoff when offline.
const NATIVE_HOST_ENABLED = false;

function nativeHostFixHTML(reason=""){
  const host = NATIVE_HOST_NAME;
  const id = nativeExtId();
  const origin = nativeExtOrigin();

  const lines = [];
  if (reason) lines.push(`<div class="muted" style="margin-bottom:10px;">${escapeHtml(reason)}</div>`);
  if (origin){
    lines.push(`<div style="margin:10px 0 8px 0;"><b>Extension ID</b>: <span class="mono">${escapeHtml(id)}</span></div>`);
    lines.push(`<div style="margin:0 0 10px 0;"><b>Required allowed origin</b>: <span class="mono">${escapeHtml(origin)}</span></div>`);
    lines.push(`<div class="muted" style="margin:0 0 10px 0;">Update the native host manifest <span class="mono">${escapeHtml(host)}</span> to include this origin in <span class="mono">allowed_origins</span>, then restart Chrome and reload the extension.</div>`);
    lines.push(`<pre class="mono" style="white-space:pre-wrap;">"allowed_origins": ["${escapeHtml(origin)}"]</pre>`);
    lines.push(`<div class="muted" style="margin-top:10px;">Common macOS locations:</div>`);
    lines.push(`<div class="muted" style="margin-top:6px;"><span class="mono">/Library/Google/Chrome/NativeMessagingHosts/${escapeHtml(host)}.json</span></div>`);
    lines.push(`<div class="muted" style="margin-top:4px;"><span class="mono">~/Library/Application Support/Google/Chrome/NativeMessagingHosts/${escapeHtml(host)}.json</span></div>`);
    lines.push(`<div class="muted" style="margin-top:10px;">Expected host binary:</div>`);
    lines.push(`<div class="muted" style="margin-top:4px;"><span class="mono">/Library/Application Support/MPS_AE_Bridge_NativeHost/bin/mps_ae_bridge_host</span></div>`);
  } else {
    lines.push(`<div class="muted">Cannot read extension ID. Please reload the extension page.</div>`);
  }

  return `<div style="padding:10px 12px; border-radius:12px; border:1px solid rgba(255,255,255,.12); background:rgba(0,0,0,.35);">${lines.join("")}</div>`;
}


function setNativeHostStatusDot(state){
  const dot = document.getElementById("amfHostDot");
  if (!dot) return;
  dot.classList.remove("ok", "bad");
  if (state === "ok") dot.classList.add("ok");
  else if (state === "bad") dot.classList.add("bad");
}

function setNativeHostStatusText(text="Native Host", title=""){
  const el = document.getElementById("amfHostStatusText");
  if (!el) return;
  el.textContent = text || "Native Host";
  try{ el.title = title || ""; }catch{}
}

let __nativeHostStatusLastCheck = 0;
async function requestNativeHostStatusSilent(force=false){
  if (!NATIVE_HOST_ENABLED){
    setNativeHostStatusDot("bad");
    setNativeHostStatusText("Native Host disabled", "Native host support removed in this build.");
    return;
  }
  const now = Date.now();
  if (!force && (now - __nativeHostStatusLastCheck) < 8000) return;
  __nativeHostStatusLastCheck = now;

  setNativeHostStatusDot("");
  setNativeHostStatusText("Native Host…", "");

  const resp = await bgSend({ type: "AE_HOST_STATUS" });
  const ping = resp?.ping || null;
  const st = resp?.status || null;

  if (!resp || resp.ok === false || (ping && ping.ok === false)) {
    const err = ping?.error || resp?.error || resp?.message || "Native host not available";
    setNativeHostStatusDot("bad");
    // Keep label short; put details in tooltip
    if (isNativeForbiddenError(err)) setNativeHostStatusText("Native Host blocked", err);
    else setNativeHostStatusText("Native Host offline", err);
    return;
  }

  if (!st || st.ok === false) {
    const err = st?.error || resp?.error || "STATUS failed";
    setNativeHostStatusDot("bad");
    setNativeHostStatusText("Native Host error", err);
    return;
  }

  setNativeHostStatusDot("ok");
  setNativeHostStatusText("Native Host OK", "");
}

async function requestNativeHostStatusUI(){
  if (!NATIVE_HOST_ENABLED){
    aepShow();
    aepSet("Native Host disabled", "Native Host", 12, "ok");
    aepHint("This build does not use a native messaging host.", true);
    return;
  }
  aepShow();
  aepSet("Checking…", "Native Host Status", 12, "busy");
  aepHint("", false);
  aepInstallPanel("", false);

  setNativeHostStatusDot("");

  const ui = aepUI();
  if (ui.log) ui.log.textContent = "";

  aepLog("🟦 Native Host Status");
  aepLog("Step 1/2: PING (open native port)");
  aepLog("Step 2/2: STATUS (query host info)");

  const resp = await bgSend({ type: "AE_HOST_STATUS" });

  // PING failed
  const ping = resp?.ping || null;
  if (!resp || resp.ok === false && ping && ping.ok === false){
    const err = ping?.error || resp?.error || resp?.message || "Native host not available";
    aepSet("Native Host not available", err, 0, "err");
    aepLog(`❌ PING failed: ${err}`);
    if (isNativeForbiddenError(err)){
      aepHint("Native Host is installed but this extension is not allowed (allowed_origins). Update the host manifest, restart Chrome (Cmd+Q), then reload the extension.", true);
    } else {
      aepHint("Install the Native Host, restart Chrome (Cmd+Q), then reload the extension.", true);
    }
    aepInstallPanel(nativeHostFixHTML(err), true);
    setNativeHostStatusDot("bad");
    try{ window.MPS_setExportStatus?.("err", "❌ Export failed: AE Project (.aep)", err); }catch{}
    return;
  }

  if (ping && ping.ok === false){
    const err = ping.error || resp?.error || "Native host not available";
    aepSet("Native Host not available", err, 0, "err");
    aepLog(`❌ PING failed: ${err}`);
    if (isNativeForbiddenError(err)){
      aepHint("Native Host is installed but this extension is not allowed (allowed_origins). Update the host manifest, restart Chrome (Cmd+Q), then reload the extension.", true);
    } else {
      aepHint("Install the Native Host, restart Chrome (Cmd+Q), then reload the extension.", true);
    }
    aepInstallPanel(nativeHostFixHTML(err), true);
    setNativeHostStatusDot("bad");
    try{ window.MPS_setExportStatus?.("err", "❌ Export failed: AE Project (.aep)", err); }catch{}
    return;
  }

  aepLog(`✅ PING: OK (${resp?.host || ping?.host || "com.mps.ae_bridge"})`);

  // STATUS
  const st = resp?.status || null;
  if (!st || st.ok === false){
    const err = st?.error || resp?.error || "STATUS failed";
    aepSet("STATUS failed", err, 0, "err");
    setNativeHostStatusDot("bad");
    aepLog(`❌ STATUS failed: ${err}`);
    aepLog("Details:");
    if (st?.resp) aepLog(prettyJSON(st.resp));
    if (isNativeForbiddenError(err)){
      aepHint("Native Host is installed but this extension is not allowed (allowed_origins). Update the host manifest, restart Chrome (Cmd+Q), then reload the extension.", true);
      aepInstallPanel(nativeHostFixHTML(err), true);
    }
    return;
  }

  aepSet("OK", `Native Host online (${resp?.ms || st?.ms || 0}ms)`, 100, "ok");
  setNativeHostStatusDot("ok");
  aepLog("✅ STATUS:");
  aepLog(prettyJSON(st.resp || st));
}

async function aepDownloadFromBase64(bytesBase64, filename="VFX_Project.aep"){
  const name = safeFileName(filename || "VFX_Project.aep");
  aepLastFileName = name;

  // decode base64 -> blob
  const b64 = String(bytesBase64 || "");
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i=0;i<len;i++) bytes[i] = bin.charCodeAt(i);
  const blob = new Blob([bytes], { type: "application/octet-stream" });
  const url = URL.createObjectURL(blob);

  // prefer downloads API (does not require user gesture)
  if (chrome?.downloads?.download){
    return new Promise((resolve) => {
      chrome.downloads.download({
        url,
        filename: `Attached_Files/${name}`,
        saveAs: false
      }, (downloadId) => {
        const err = chrome.runtime.lastError?.message;
        setTimeout(() => URL.revokeObjectURL(url), 30000);
        if (err) return resolve({ ok:false, error: err });
        resolve({ ok:true, downloadId });
      });
    });
  }

  // fallback: anchor download (may be blocked if not within gesture)
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 30000);
  return { ok:true, downloadId: null };
}

async function exportAEProjectHandoffPackage(exportResult, opts={}){
  if (!AMF || typeof AMF.exportAEProjectPackage !== "function"){
    showError("AE Project handoff exporter is not available in this build.");
    return;
  }

  const tlBase = opts?.tlBase || safeFilename(exportResult?.edlTitle || exportResult?.rootName || "VFX_Project");
  const estJobs = Math.max(1, Array.isArray(exportResult?.shots) ? exportResult.shots.length : 1);
  const readmeName = safeFileName(`${tlBase}_AEP_README.txt`);
  const fallbackErr = String(opts?.fallbackError || "").trim();
  aepLastFileName = safeFileName(`${tlBase}_SHOT.aep`);

  aepShow();
  aepSet("Preparing…", `Creating ${estJobs} per-shot AE handoff ${estJobs > 1 ? 'jobs' : 'job'}`, 8, "busy");
  aepHint(
    fallbackErr
      ? `Native Host direct .aep build is unavailable (${fallbackErr}). Exporting the AE handoff package instead.`
      : "AE Project export now works per shot: one job JSON + one builder JSX per shot, plus RenderSpec/DeliverySpec sidecars. Files are organized into 00_MASTER + 01_SHOTS/<shot> package folders, with 04_RENDERS/<shot> and 05_DELIVERY/<shot> prepared too. The shared queue-helper can now auto-map __RENDER comps to the per-shot render folders from RenderSpec.",
    true
  );
  aepInstallPanel("", false);
  const ui = aepUI();
  if (ui.log) ui.log.textContent = "";
  if (fallbackErr){
    aepLog(`⚠️ Native Host unavailable: ${fallbackErr}`);
    aepLog("Falling back to file-based AE handoff export.");
  } else {
    aepLog("🟣 AE Project export uses file-based handoff (per shot, no Native Host).");
  }
  aepLog(`Batch: ${tlBase}`);
  aepLog(`Jobs: ${estJobs} shot${estJobs > 1 ? 's' : ''}`);
  aepLog(`Shared helpers: 00_MASTER/PostFlowX_AE_WatchFolder.jsx, 00_MASTER/PostFlowX_AE_Panel.jsx, 00_MASTER/Install_PostFlowX_AE_Panel.command, 00_MASTER/${readmeName}`);
  aepLog("Modes: one-shot builder + optional AE watch mode + dockable AE panel.");
  if (amfNativeRoot) aepLog(`Native VFX Root hint: ${amfNativeRoot}`);

  try{ window.MPS_setExportStatus?.("work", "Exporting: AE Project handoff…", `${estJobs} per-shot job${estJobs > 1 ? 's' : ''}`); }catch{}

  try{
    const info = await AMF.exportAEProjectPackage(exportResult);
    const jobCount = Math.max(1,
      Number(info?.jobCount) ||
      (Array.isArray(info?.jobNames) ? info.jobNames.length : 0) ||
      estJobs
    );
    const sharedFiles = [info?.watchName, info?.panelName, info?.installName, info?.readmeName].filter(Boolean);
    const files = Array.isArray(info?.files) && info.files.length ? info.files : [];
    const subLabel = info?.savedToVfxRoot
      ? `Saved to VFX Root: ${jobCount} per-shot jobs + shared AE helpers`
      : `Downloaded: ${jobCount} per-shot jobs + shared AE helpers`;

    aepSet("Done", info?.savedToVfxRoot ? "Saved per-shot build files to VFX Root" : "Downloaded per-shot build files", 100, "ok");
    aepHint("Recommended: install the dockable AE panel once, then use Auto ON for future per-shot builds.", true);
    aepInstallPanel(`
      <div style="padding:10px 12px; border-radius:12px; border:1px solid rgba(255,255,255,.12); background:rgba(0,0,0,.35);">
        <div style="font-weight:800; margin-bottom:8px;">AE Project handoff exported (per shot)</div>
        <div class="muted" style="margin-bottom:6px;">Projects ready: <span class="mono">${escapeHtml(String(jobCount))}</span> shot${jobCount > 1 ? 's' : ''}</div>
        <div class="muted" style="margin-bottom:10px;">Each shot gets its own <span class="mono">*_AEP_Job.json</span>, <span class="mono">*_Build_AE_Project.jsx</span>, <span class="mono">*_RenderSpec.json</span>, and <span class="mono">*_DeliverySpec.json</span> inside <span class="mono">01_SHOTS/&lt;shot&gt;/</span>, plus prepared <span class="mono">04_RENDERS/&lt;shot&gt;/</span> and <span class="mono">05_DELIVERY/&lt;shot&gt;/</span> folders and a shared queue-helper JSX in <span class="mono">00_MASTER/</span> that can auto-map <span class="mono">__RENDER</span> comps to the correct per-shot render folders.</div>
        <div class="muted" style="margin-bottom:8px; font-weight:700;">Recommended setup: dockable AE panel</div>
        <div class="muted" style="margin-bottom:6px;">1) Run <span class="mono">${escapeHtml(info?.installName || 'Install_PostFlowX_AE_Panel.command')}</span></div>
        <div class="muted" style="margin-bottom:6px;">2) Choose the After Effects ScriptUI Panels folder</div>
        <div class="muted" style="margin-bottom:6px;">3) Open or restart After Effects</div>
        <div class="muted" style="margin-bottom:6px;">4) Open <span class="mono">Window &gt; ${escapeHtml(String(info?.panelName || 'PostFlowX_AE_Panel.jsx').replace(/\.jsx$/i, ''))}</span></div>
        <div class="muted" style="margin-bottom:10px;">5) Choose the exported VFX root (or <span class="mono">01_SHOTS</span>) and click <span class="mono">Auto ON</span></div>
        <div class="muted" style="margin-bottom:12px;">Shared helper files: <span class="mono">${escapeHtml(sharedFiles.join(', '))}</span></div>
        <div class="muted" style="margin-bottom:8px; font-weight:700;">One-shot build</div>
        <div class="muted" style="margin-bottom:6px;">Run any exported <span class="mono">*_Build_AE_Project.jsx</span> file from AE via File &gt; Scripts &gt; Run Script File…</div>
        <div class="muted" style="margin-bottom:8px; font-weight:700;">Portable watch mode</div>
        <div class="muted" style="margin-bottom:6px;">Run <span class="mono">${escapeHtml(info?.watchPath || info?.watchName || '00_MASTER/PostFlowX_AE_WatchFolder.jsx')}</span> directly in AE without installing a panel</div>
        <div class="muted">Guide: <span class="mono">${escapeHtml(info?.readmePath || info?.readmeName || ('00_MASTER/' + readmeName))}</span></div>
      </div>
    `, true);
    aepLog(subLabel);
    if (Array.isArray(info?.jobPaths) && info.jobPaths.length){
      aepLog(`Job folders: ${info.jobPaths.join(', ')}`);
    } else if (Array.isArray(info?.jobNames) && info.jobNames.length){
      aepLog(`Jobs: ${info.jobNames.join(', ')}`);
    } else if (files.length){
      aepLog(`Files: ${files.join(', ')}`);
    }

    try{ window.MPS_setExportStatus?.("ok", "✅ Exported: AE Project handoff", subLabel); }catch{}
    try{
      window.MPS_auditAdd?.({
        type:'AE_AEP_HANDOFF',
        intent:'exr',
        count: jobCount,
        files: files.slice(),
        note:'Export AE Project handoff per shot (job+jsx+renderSpec+deliverySpec+watch+panel+queue+install+readme)'
      });
    }catch{}
  } catch(err){
    const errTxt = err?.message || String(err || "Export failed");
    aepSet("Failed", errTxt, 0, "err");
    aepHint("", false);
    try{ window.MPS_setExportStatus?.("err", "❌ Export failed: AE Project (.aep)", errTxt); }catch{}
    aepLog(`❌ ${errTxt}`);
    showError(errTxt);
  }
}

async function requestNativeAEPBuild(){
  loadAmfNativeRoot();

  let exportResult = null;

  if (AMF && typeof AMF.getSelectedResult === "function"){
    try{
      const sel = AMF.getSelectedResult();
      if (sel && Array.isArray(sel.shots) && sel.shots.length){
        exportResult = sel;
      }
    } catch {}
  }

  if (!exportResult && !amfResult && AMF && typeof AMF.getLastResult === "function"){
    try{
      const r = AMF.getLastResult();
      if (r){
        amfResult = r;
        if (AMF && typeof AMF.getLastFiles === "function"){
          const fs = AMF.getLastFiles();
          if (fs && fs.length) amfFiles = fs;
        }
      }
    } catch {}
  }

  if (!exportResult && amfResult && Array.isArray(amfResult.shots) && amfResult.shots.length){
    exportResult = amfResult;
  }

  if (!exportResult){
    showError("Scan a VFX folder first.");
    return;
  }

  if (!AMF || typeof AMF.exportAEPXPackage !== "function"){
    showError("AE XML exporter (.aepx) is not available in this build.");
    return;
  }

  const tlBase = safeFilename(exportResult?.edlTitle || exportResult?.rootName || "VFX_Project");
  const estJobs = Math.max(1, Array.isArray(exportResult?.shots) ? exportResult.shots.length : 1);
  aepActiveRequestId = null;
  aepResetChunks();
  aepLastFileName = safeFileName(`${tlBase}.aepx`);

  aepShow();
  aepSet("Preparing…", "Extension-only AE XML export (.aepx)", 8, "busy");
  aepHint("Creating AE XML starter projects (.aepx) directly in the extension. No Native Host is used.", true);
  aepInstallPanel("", false);
  const ui = aepUI();
  if (ui.log) ui.log.textContent = "";
  aepLog("🟦 AE XML export (.aepx) — extension-only");
  aepLog(`Batch: ${tlBase}`);
  aepLog(`Shots: ${estJobs}`);
  aepLog("Output: one starter .aepx + one *_AEPX_Manifest.json per shot");
  aepLog(amfNativeRoot ? `Native VFX Root: ${amfNativeRoot}` : "Native VFX Root: not set (downloads fallback)");
  try{ window.MPS_setExportStatus?.("work", "Exporting: AE XML (.aepx)…", `${estJobs} shot${estJobs > 1 ? 's' : ''}`); }catch{}

  try{
    const info = await AMF.exportAEPXPackage(exportResult);
    const jobCount = Math.max(1,
      Number(info?.jobCount) ||
      (Array.isArray(info?.aepxNames) ? info.aepxNames.length : 0) ||
      estJobs
    );
    const subLabel = info?.savedToVfxRoot
      ? `Saved to VFX Root: ${jobCount} starter .aepx project${jobCount > 1 ? 's' : ''} + manifests`
      : `Downloaded: ${jobCount} starter .aepx project${jobCount > 1 ? 's' : ''} + manifests`;

    aepSet("Done", info?.savedToVfxRoot ? "Saved starter .aepx package to VFX Root" : "Downloaded starter .aepx package", 100, "ok");
    aepHint("Open any exported .aepx in After Effects, then use the matching *_AEPX_Manifest.json sidecar for source plate / look / EDL metadata.", true);
    aepInstallPanel(`
      <div style="padding:10px 12px; border-radius:12px; border:1px solid rgba(255,255,255,.12); background:rgba(0,0,0,.35);">
        <div style="font-weight:800; margin-bottom:8px;">AE XML starter export completed (.aepx)</div>
        <div class="muted" style="margin-bottom:6px;">Projects ready: <span class="mono">${escapeHtml(String(jobCount))}</span> shot${jobCount > 1 ? 's' : ''}</div>
        <div class="muted" style="margin-bottom:10px;">Each shot gets one <span class="mono">.aepx</span> starter project and one matching <span class="mono">*_AEPX_Manifest.json</span> sidecar with sequence / look / EDL metadata.</div>
        <div class="muted" style="margin-bottom:6px;">1) Open any exported <span class="mono">.aepx</span> file in After Effects</div>
        <div class="muted" style="margin-bottom:6px;">2) Read the matching sidecar manifest next to it for plate / look / timing references</div>
        <div class="muted" style="margin-bottom:6px;">3) Import or relink footage in After Effects as needed</div>
        <div class="muted">Guide: <span class="mono">${escapeHtml(info?.readmePath || info?.readmeName || '00_MASTER/PostFlowX_AEPX_README.txt')}</span></div>
      </div>
    `, true);

    aepLog(subLabel);
    if (Array.isArray(info?.aepxPaths) && info.aepxPaths.length){
      aepLog(`AEPX: ${info.aepxPaths.join(', ')}`);
    }
    if (Array.isArray(info?.manifestPaths) && info.manifestPaths.length){
      aepLog(`Manifests: ${info.manifestPaths.join(', ')}`);
    }
    if (info?.readmePath){
      aepLog(`Readme: ${info.readmePath}`);
    }

    try{ window.MPS_setExportStatus?.("ok", "✅ Exported: AE XML (.aepx)", subLabel); }catch{}
    try{
      window.MPS_auditAdd?.({
        type:'AE_AEPX',
        intent:'plate_link',
        count: jobCount,
        files: Array.isArray(info?.files) ? info.files.slice() : [],
        note:'Export AE XML starter package (.aepx + manifest) extension-only'
      });
    }catch{}
  } catch(err){
    const errTxt = err?.message || String(err || "Export failed");
    aepSet("Failed", errTxt, 0, "err");
    aepHint("", false);
    try{ window.MPS_setExportStatus?.("err", "❌ Export failed: AE XML (.aepx)", errTxt); }catch{}
    try{ AMF?.autoTrimPlateLinkMemory?.(180); }catch{}
    aepLog(`❌ ${errTxt}`);
    showError(errTxt);
  }
}

function wireAEPBridge(){
  if (wireAEPBridge._wired) return;
  wireAEPBridge._wired = true;
  // listener wiring continues below
  loadAmfNativeRoot();

  const ui = aepUI();
  if (ui.btnClose){
    ui.btnClose.addEventListener("click", (e) => {
      e.preventDefault();
      aepHide();
    });
  }
  if (ui.btnCopy){
    ui.btnCopy.addEventListener("click", async (e) => {
      e.preventDefault();
      const txt = amfNativeRoot || aepLastFileName || "";
      try{ await navigator.clipboard.writeText(txt); } catch {}
    });
  }

  // Listen to background/native-host events
  if (chrome?.runtime?.onMessage){
    chrome.runtime.onMessage.addListener((msg) => {
      if (!msg || typeof msg !== "object") return;

      const type = msg.type || msg.event || msg.kind;
      if (!type || !String(type).startsWith("AE_")) return;

      const rid = msg.requestId || msg.rid;
      if (aepActiveRequestId && rid && rid !== aepActiveRequestId) return;

      // ensure visible
      aepShow();

      if (type === "AE_BUILD_LOG"){
        aepLog(msg.line || msg.message || msg.text || "");
        return;
      }

      if (type === "AE_BUILD_PROGRESS"){
        const pct =
          (typeof msg.pct === "number") ? msg.pct :
          (typeof msg.percent === "number") ? msg.percent :
          (typeof msg.progress === "number") ? Math.round(msg.progress * 100) : null;
        aepSet(msg.status || "Building…", msg.step || "", pct, "busy");
        return;
      }

      if (type === "AE_BUILD_START"){
        aepSet("Building…", msg.step || msg.message || "", 12, "busy");
        if (msg.message) aepLog(msg.message);
        return;
      }

      if (type === "AE_BUILD_CHUNK"){
        const total = Number(msg.total || msg.totalChunks || 0);
        const index = Number(msg.index || msg.i || 0);
        const chunk = msg.chunkBase64 || msg.bytesBase64 || msg.chunk || "";
        if (!chunk) return;

        if (total && total !== aepChunkTotal){
          aepChunkTotal = total;
          aepChunks = new Array(total).fill("");
        }
        if (aepChunkTotal && index >= 0 && index < aepChunks.length){
          aepChunks[index] = chunk;
        } else {
          aepChunks.push(chunk);
        }

        const filled = aepChunks.filter(Boolean).length;
        const pct = aepChunkTotal ? Math.round((filled / aepChunkTotal) * 100) : null;
        aepSet("Receiving project…", `Chunk ${index+1}/${aepChunkTotal||"?"}`, pct, "busy");
        return;
      }

      if (type === "AE_BUILD_ERROR"){
        const err = msg.error || msg.message || msg.reason || "Unknown error";
        aepSet("Failed", err, 0, "err");
        try{ window.MPS_setExportStatus?.("err", "❌ Export failed: AE Project (.aep)", err); }catch{}
        aepLog(`❌ Failed:
${err}`);
        showError(err);

        if (/AfterFX executable not found/i.test(err)){
          aepInstallPanel(
            `<div class="muted" style="font-size:12px;line-height:1.4;">
              <div style="font-weight:800;margin-bottom:6px;">After Effects not found</div>
              <div>Install After Effects, or ensure the Native Host can find <b>AfterFX</b> in PATH.</div>
            </div>`,
            true
          );
        }
        return;
      }

      if (type === "AE_BUILD_DONE"){
        const ok = (msg.ok !== false);
        const name = msg.fileName || msg.filename || msg.aepName || aepLastFileName || "VFX_Project.aep";

        let bytesBase64 = msg.bytesBase64 || msg.dataBase64 || "";
        if (!bytesBase64 && aepChunks && aepChunks.length){
          bytesBase64 = aepChunks.join("");
        }

        if (!ok || !bytesBase64){
          const err = msg.error || msg.message || "No project data returned.";
          aepSet("Failed", err, 0, "err");
          try{ window.MPS_setExportStatus?.("err", "❌ Export failed: AE Project (.aep)", err); }catch{}
          aepLog(`❌ Failed:
${err}`);
          showError(err);
          return;
        }

        aepSet("Downloading…", name, 96, "busy");
        aepLog("AE_BUILD_DONE (received bytes)");

        aepDownloadFromBase64(bytesBase64, name).then((r) => {
          if (!r.ok){
            aepSet("Download failed", r.error || "", 0, "err");
            try{ window.MPS_setExportStatus?.("err", "❌ Export failed: AE Project (.aep)", r.error || "Download failed"); }catch{}
            showError(r.error || "Download failed");
            return;
          }
          aepSet("Done", `Saved: Attached_Files/${safeFileName(name)}`, 100, "ok");
          try{ window.MPS_setExportStatus?.("ok", "✅ Exported: AE Project (.aep)", "Attached_Files/" + safeFileName(name)); }catch{}
          try{
            const shotCount = Array.isArray(msg?.shots) ? msg.shots.length : 0;
            window.MPS_auditAdd?.({ type:'AE_AEP', intent:'exr', count: shotCount, files:[safeFileName(name)], note:'Export AE .aep' });
          }catch{}
          aepHint("TIP: Open chrome://downloads (Cmd+J) to confirm the download.", true);
          const ui2 = aepUI();
          if (ui2.btnCopy){
            ui2.btnCopy.style.display = "inline-flex";
          }
        }).catch((err) => {
          // A rejection (vs a resolved {ok:false}) would otherwise leave the UI
          // stuck at "Downloading… 96%" with an unhandled promise rejection.
          const m = (err && err.message) ? err.message : String(err);
          aepSet("Download failed", m, 0, "err");
          try { window.MPS_setExportStatus?.("err", "❌ Export failed: AE Project (.aep)", m); } catch {}
          showError(m);
        });
        return;
      }

      // fallback: show raw
      aepLog(JSON.stringify(msg));
    });
  }
}

function getSafeAMFResultHost(){
  const main = $("#main-amf") || document.getElementById("main-amf");

  // Prefer tbody targets (safe)
  const tbody =
    getById("amfTableBody", "amfShotsBody") ||
    document.querySelector("#amfTable tbody") ||
    document.querySelector("[data-amf='table-body']");

  if (tbody) return { type:"tbody", el: tbody };

  // Prefer a dedicated host that does NOT contain buttons (avoid nuking UI)
  const candidates = [
    getById("amfResultHost", "amfMappingHost", "amfListHost", "amfMapping"),
    document.querySelector("[data-amf='result-host']"),
    document.querySelector("[data-amf='mapping-host']")
  ].filter(Boolean);

  for (const el of candidates){
    if (!el) continue;
    if (el === main) continue;
    // If it contains buttons/controls, don't use it as a write target
    if (el.querySelector && el.querySelector("button, .btn")) continue;
    return { type:"div", el };
  }

  // Last resort: create our own safe host under main
  if (main){
    let host = main.querySelector("#__amfMappingHost");
    if (!host){
      host = document.createElement("div");
      host.id = "__amfMappingHost";
      host.style.marginTop = "10px";
      host.style.padding = "8px";
      host.style.opacity = "0.9";
      host.style.fontSize = "12px";
      host.style.borderTop = "1px solid rgba(255,255,255,0.06)";
      main.appendChild(host);
    }
    return { type:"div", el: host };
  }

  return null;
}

function renderAMFResult(result){
  const sumEl  = getById("amfSummary", "amfSummaryText");
  const hostInfo = getSafeAMFResultHost();

  // Summary can be either legacy text ("Shots: X · Ready: Y · Missing: Z")
  // or KPI cards (amfKpiShots/amfKpiReady/amfKpiMissing). Update safely.
  function setAMFSummary(stats){
    const s = stats || { shots:0, ready:0, missing:0 };
    const shots = (typeof s.shots === "number") ? s.shots : parseInt(s.shots || 0, 10) || 0;
    const ready = (typeof s.ready === "number") ? s.ready : parseInt(s.ready || 0, 10) || 0;
    const miss  = (typeof s.missing === "number") ? s.missing : parseInt(s.missing || 0, 10) || 0;

    const kShots = document.getElementById("amfKpiShots");
    const kReady = document.getElementById("amfKpiReady");
    const kMiss  = document.getElementById("amfKpiMissing");

    // KPI card mode
    if (kShots && kReady && kMiss){
      kShots.textContent = String(shots);
      kReady.textContent = String(ready);
      kMiss.textContent  = String(miss);
      return;
    }

    // Legacy text mode (do NOT clobber KPI cards)
    if (sumEl){
      const hasCards = !!(sumEl.querySelector && sumEl.querySelector(".amf-kpi"));
      if (!hasCards){
        sumEl.textContent = `Shots: ${shots} · Ready: ${ready} · Missing: ${miss}`;
      }
    }
  }

  if (!result){
    setAMFStatus("No folder selected.");
    setAMFSummary({ shots:0, ready:0, missing:0 });

    if (hostInfo?.el){
      if (hostInfo.type === "tbody"){
        hostInfo.el.innerHTML = "";
        // optional: add a single row if table exists
        const tr = document.createElement("tr");
        const td = document.createElement("td");
        td.colSpan = 6;
        td.style.padding = "8px";
        td.style.opacity = "0.7";
        td.textContent = "No folder selected.";
        tr.appendChild(td);
        hostInfo.el.appendChild(tr);
      } else {
        hostInfo.el.innerHTML = "<div style='padding:8px;opacity:.7'>No folder selected.</div>";
      }
    }
    return;
  }

  // Update status label (fix: stale "No folder selected.")
  setAMFStatus(result.rootName ? result.rootName : "Folder selected.");

  const stats = result.stats || { shots:0, ready:0, missing:0 };
  setAMFSummary(stats);

  // If module can render HTML table, render into safe host only
  if (hostInfo?.el){
    if (hostInfo.type === "tbody"){
      // If module provides rows HTML, prefer that
      if (AMF && typeof AMF.buildMappingTableRowsHTML === "function"){
        hostInfo.el.innerHTML = AMF.buildMappingTableRowsHTML(result);
      } else if (AMF && typeof AMF.buildMappingTableHTML === "function"){
        // If returns a full table, convert to rows if possible; otherwise fallback
        const html = AMF.buildMappingTableHTML(result);
        // try to extract tbody innerHTML if it contains <tbody>
        const m = html && html.match(/<tbody[^>]*>([\s\S]*?)<\/tbody>/i);
        hostInfo.el.innerHTML = m ? m[1] : "";
      } else {
        hostInfo.el.innerHTML = "";
      }
    } else {
      if (AMF && typeof AMF.buildMappingTableHTML === "function"){
        hostInfo.el.innerHTML = AMF.buildMappingTableHTML(result);
      } else {
        hostInfo.el.innerHTML = "<div style='padding:8px;opacity:.7'>Mapping ready.</div>";
      }
    }
  }

// Enable header sorting for VFX Mapping table (like EDL Converter)
// and re-apply the last sort after each re-render.
try{
  wireAMFTableSorting();
  requestAnimationFrame(() => applyAMFTableSortIfNeeded());
}catch{}


}

async function runVFXScan(files){
  // Prefer NEW module API (self-wired)
  if (AMF && (
      typeof AMF.initVFXMapping === "function" ||
      typeof AMF.initAMFConverter === "function" ||
      typeof AMF.initAMF === "function" ||
      typeof AMF.default === "function"
    )){
    // If module owns the UI, do nothing here.
    return;
  }

  // Legacy API
  if (!AMF || typeof AMF.scanVFXFolder !== "function"){
    showError("VFX Mapping module not available.");
    return;
  }
  if (!files || !files.length){
    setAMFStatus("No folder selected.");
    showError("No VFX folder selected.");
    return;
  }

  setAMFStatus("Scanning…");

  const labelEl = getById("amfFolderLabel", "amfFolderName", "amfFolderStatus");
  let folderName = "VFX Folder";
  if (files.length){
    const first = files[0];
    const full  = (first.webkitRelativePath || first.virtualPath || first.name || "").split("/");
    folderName = full[0] || "VFX Folder";
  }

  if (labelEl){
    labelEl.textContent = folderName;
  }
  // Ensure the visible status banner/label updates too
  setAMFStatus(folderName);

  try{
    const res = await AMF.scanVFXFolder(files);
    amfFiles  = files;
    amfResult = res;

    // Prefer scan result rootName if provided
    if (res?.rootName) setAMFStatus(res.rootName);
    else setAMFStatus(folderName);

    renderAMFResult(res);
    showError("");
  } catch(err){
    console.error("VFX Mapping scan error", err);
    setAMFStatus("No folder selected.");
    showError(err?.message || String(err));
  }
}

function ensureAMFFolderInput(){
  let folderInput = getById("amfFolderPicker", "amfFolderInput", "amfVfxFolderInput", "__amfFolderPicker");
  if (folderInput) return folderInput;

  folderInput = document.createElement("input");
  folderInput.type = "file";
  folderInput.id   = "__amfFolderPicker";
  folderInput.multiple = true;
  folderInput.setAttribute("webkitdirectory", "true");
  folderInput.setAttribute("directory", "true");

  // IMPORTANT: NOT display:none — keep offscreen
  folderInput.style.position = "fixed";
  folderInput.style.left = "-9999px";
  folderInput.style.top = "0px";
  folderInput.style.width = "1px";
  folderInput.style.height = "1px";
  folderInput.style.opacity = "0";
  folderInput.style.pointerEvents = "none";

  document.body.appendChild(folderInput);
  return folderInput;
}

function wireAMF(){
  const main = $("#main-amf");
  if (!main) return;
  try{ initAMFExportStatusUI(); }catch{}

  // Group-by Shot UI + NK per-group export (works for both legacy + module-owned renderers)
  try{ wireAMFGroupByShotControls(); }catch{}
  try{ wireAMFExportNkPerGroup(); }catch{}

  // Load saved Native VFX Root/Base early so we can auto-sync on folder pick.
  loadAmfNativeRoot();

  // NEW module path (preferred): module binds itself safely (folder scan + json/jsx/nuke)
  // But Native Host (.aep) buttons are owned by ui.js, so we always wire them here.
  let moduleOwnsUI = false;
  try{
    const initFn =
      AMF?.initVFXMapping ||
      AMF?.initAMFConverter ||
      AMF?.initAMF ||
      AMF?.default;

    if (typeof initFn === "function"){
      const ok = initFn();
      moduleOwnsUI = !!ok;
      if (!moduleOwnsUI){
        console.warn("VFX Mapping module init returned false; falling back to legacy wiring.");
      }
    }
  } catch(e){
    console.warn("VFX Mapping init failed:", e);
  }

  // If module owns the UI, we only need to wire Native Root + Export AEP.
  if (moduleOwnsUI){
    const amfButtons = Array.from(main.querySelectorAll("button, .btn"));
    function findByText(regex){
      return amfButtons.find(b => regex.test((b.textContent || "").trim()));
    }

    let aepBtn = getById("amfGenerateAEP", "amfExportAEP", "btnExportAEP", "amfAepBtn") ||
                 findByText(/export\s+ae\s+project|\.aep/i);
    let nativeRootBtn = getById("amfSetNativeRoot", "btnSetNativeRoot", "amfNativeRootBtn", "btnVFXRootNative") ||
                        findByText(/set\s+vfx\s+root\s*\(native\)|native\s+vfx\s+root/i);

    if (nativeRootBtn){
      nativeRootBtn.removeAttribute("disabled");
      nativeRootBtn.disabled = false;
      on(nativeRootBtn, "click", () => {
        promptSetAmfNativeRoot();
      });
    }

    if (aepBtn){
      aepBtn.removeAttribute("disabled");
      aepBtn.disabled = false;
      on(aepBtn, "click", () => {
        requestNativeAEPBuild();
      });
    }

    // Native Host Status button (PING/STATUS)
    let hostStatusBtn = getById("amfHostStatus", "btnNativeHostStatus", "amfNativeHostStatus") ||
                        findByText(/native\s+host\s+status|host\s+status/i);
    if (hostStatusBtn){
      hostStatusBtn.removeAttribute("disabled");
      hostStatusBtn.disabled = false;
      on(hostStatusBtn, "click", () => {
        requestNativeHostStatusUI();
      });
    }

    // Clear VFX Folder + Native VFX Root (Auto)
    let clearBtn = getById("amfClear", "btnClearVFXFolder", "amfClearBtn") ||
                   findByText(/^clear$/i);
    if (clearBtn){
      clearBtn.removeAttribute("disabled");
      clearBtn.disabled = false;
      on(clearBtn, "click", () => {
        // Reset ui.js shared state (module will clear its internal state + UI)
        amfFiles = [];
        amfResult = null;
        lastLoadWasAutoVfxEdl = false;
        autoLoadingVfxEdl = false;

        // Reset native root cache + storage (so next folder pick starts clean)
        amfNativeRoot = "";
        amfNativeBase = "";
      amfSelectedRootName = "";
        try{
          localStorage.removeItem("mps.amf.nativeRoot");
          localStorage.removeItem("mps.amf.nativeBase");
        localStorage.removeItem("mps.amf.rootName");
        }catch{}
        updateAmfNativeRootUI("—");
        setAMFStatus("No folder selected.");
        showError("");
      });
    }

    // ✅ Auto-sync Native VFX Root when user chooses a VFX folder
    const folderInput = getById("amfFolderPicker", "__amfFolderPicker");
    if (folderInput && folderInput.dataset && folderInput.dataset.mpsAutoSyncNative !== "1"){
      folderInput.dataset.mpsAutoSyncNative = "1";
      folderInput.addEventListener("change", (e) => {
  try{
    const fs = Array.from(e?.target?.files || []);
    amfFiles = fs;
    const synced = autoSyncAmfNativeRootFromFiles(fs);
    autoLoadEdlFromVfxFolder(fs).catch(err => { console.error('[PFX] autoLoadEdlFromVfxFolder error:', err); });
  } catch {}
}, { passive: true });
    }

    return;
  }

  // Legacy wiring (scanVFXFolder/exportMappingJSON/exportAEJSX/exportNukePY/...)
  const folderInput = ensureAMFFolderInput();

  on(folderInput, "change", (e) => {
    const fs = [...(e.target.files || [])];
    amfFiles = fs;
  const synced = autoSyncAmfNativeRootFromFiles(fs);
    autoLoadEdlFromVfxFolder(fs).catch(err => { console.error('[PFX] autoLoadEdlFromVfxFolder error:', err); });
    if (fs.length) runVFXScan(fs);
    else {
      setAMFStatus("No folder selected.");
      renderAMFResult(null);
    }
  });

  let chooseBtn = getById("amfChooseFolder", "btnChooseVFXFolder", "amfChooseBtn", "btnVFXFolder");
  let rescanBtn = getById("amfRescan", "btnRescanVFX", "amfRescanBtn", "btnVFXRescan");
  let clearBtn  = getById("amfClear", "btnClearVFXFolder", "amfClearBtn");
  let mapBtn    = getById("amfExportJson", "btnExportMapping", "amfExportMapping", "amfExportMappingBtn");
  let aeBtn     = getById("amfExportAE", "btnExportAE", "amfExportAEBtn");
  let nukeBtn   = getById("amfExportNuke", "btnExportNuke", "amfExportNukeBtn");
  let nukeNKBtn = getById("amfExportNukeNK", "btnExportNukeNK", "amfExportNukeNKBtn");
  let aepBtn    = getById("amfGenerateAEP", "amfExportAEP", "btnExportAEP", "amfAepBtn");
  let nativeRootBtn = getById("amfSetNativeRoot", "btnSetNativeRoot", "amfNativeRootBtn", "btnVFXRootNative");
  let hostStatusBtn = getById("amfHostStatus", "btnNativeHostStatus", "amfNativeHostStatus");

  const amfButtons = Array.from(main.querySelectorAll("button, .btn"));
  function findByText(regex){
    return amfButtons.find(b => regex.test((b.textContent || "").trim()));
  }

  if (!chooseBtn) chooseBtn = findByText(/choose\s+vfx\s+folder/i);
  if (!rescanBtn) rescanBtn = findByText(/rescan/i);
  if (!clearBtn)  clearBtn  = findByText(/^clear$/i);
  if (!mapBtn)    mapBtn    = findByText(/export\s+mapping/i);
  if (!aeBtn)     aeBtn     = findByText(/export\s+ae\s+script/i);
  if (!nukeBtn)   nukeBtn   = findByText(/export\s+nuke\s+script/i);
  if (!nukeNKBtn) nukeNKBtn = findByText(/export\s+nuke\s+script\s*\(\.nk\)|export\s+nuke\s+script\s*\.nk/i);
  if (!aepBtn)    aepBtn    = findByText(/export\s+ae\s+project|\.aep/i);
  if (!nativeRootBtn) nativeRootBtn = findByText(/set\s+vfx\s+root\s*\(native\)|native\s+vfx\s+root/i);
  if (!hostStatusBtn) hostStatusBtn = findByText(/native\s+host\s+status|host\s+status/i);

  if (chooseBtn){
    chooseBtn.removeAttribute("disabled");
    on(chooseBtn, "click", () => {
      folderInput.value = "";
      folderInput.click(); // must be called directly under user gesture
    });
  }

  if (rescanBtn){
    rescanBtn.removeAttribute("disabled");
    on(rescanBtn, "click", () => {
      if (amfFiles && amfFiles.length){
        runVFXScan(amfFiles);
      } else {
        setAMFStatus("No folder selected.");
        showError("No VFX folder selected.");
      }
    });
  }

  if (clearBtn){
    clearBtn.removeAttribute("disabled");
    on(clearBtn, "click", () => {
      // Clear module state if supported
      try{ AMF?.clearVFXMapping?.(); } catch {}

      amfFiles = [];
      amfResult = null;
      lastLoadWasAutoVfxEdl = false;
      autoLoadingVfxEdl = false;

      amfNativeRoot = "";
      amfNativeBase = "";
      amfSelectedRootName = "";
      try{
        localStorage.removeItem("mps.amf.nativeRoot");
        localStorage.removeItem("mps.amf.nativeBase");
        localStorage.removeItem("mps.amf.rootName");
      }catch{}
      updateAmfNativeRootUI("—");

      setAMFStatus("No folder selected.");
      renderAMFResult(null);
      showError("");
    });
  }


  if (nativeRootBtn){
    nativeRootBtn.removeAttribute("disabled");
    on(nativeRootBtn, "click", () => {
      promptSetAmfNativeRoot();
    });
  }

  if (hostStatusBtn){
    hostStatusBtn.removeAttribute("disabled");
    on(hostStatusBtn, "click", () => {
      requestNativeHostStatusUI();
    });
  }

  if (aepBtn){
    aepBtn.removeAttribute("disabled");
    on(aepBtn, "click", () => {
      requestNativeAEPBuild();
    });
  }

  if (mapBtn){
    mapBtn.removeAttribute("disabled");
    on(mapBtn, "click", async () => {
      const _retry = () => setTimeout(() => { try{ mapBtn.click(); }catch{} }, 0);
      try{ if (!(await window.MPS_validateBeforeExport?.("exr", _retry))) return; }catch{}

      if (!amfResult){
        showError("Scan a VFX folder first.");
        return;
      }
      if (AMF && typeof AMF.exportMappingJSON === "function"){
        AMF.exportMappingJSON(amfResult);
        try{ window.MPS_auditAdd?.({ type:'VFX_MAPPING_JSON', intent:'exr', count: (amfResult?.shots?.length||amfResult?.length||0), files:['VFX_mapping.json'], note:'Export Mapping' }); }catch{}
      }
    });
  }

  if (aeBtn){
    aeBtn.removeAttribute("disabled");
    on(aeBtn, "click", async () => {
      const _retry = () => setTimeout(() => { try{ aeBtn.click(); }catch{} }, 0);
      try{ if (!(await window.MPS_validateBeforeExport?.("exr", _retry))) return; }catch{}
      if (!amfResult){
        showError("Scan a VFX folder first.");
        return;
      }
      if (AMF && typeof AMF.exportAEJSX === "function"){
        AMF.exportAEJSX(amfResult);
        try{
          const tl = safeFilename(amfResult?.edlTitle || amfResult?.rootName || 'TIMELINE');
          window.MPS_auditAdd?.({ type:'AE_JSX', intent:'exr', count: (amfResult?.shots?.length||amfResult?.length||0), files:[`${tl}_Create_AE_Project.jsx`], note:'Export AE Script' });
        }catch{}
      }
    });
  }

  if (nukeNKBtn){
    nukeNKBtn.removeAttribute("disabled");
    on(nukeNKBtn, "click", async () => {
      const _retry = () => setTimeout(() => { try{ nukeNKBtn.click(); }catch{} }, 0);
      try{ if (!(await window.MPS_validateBeforeExport?.("exr", _retry))) return; }catch{}

      if (!amfResult){
        showError("Scan a VFX folder first.");
        return;
      }
      if (AMF && typeof AMF.exportNukeNK === "function"){
        AMF.exportNukeNK(amfResult);
        try{
          const tl = safeFilename(amfResult?.edlTitle || amfResult?.rootName || 'TIMELINE');
          window.MPS_auditAdd?.({ type:'NUKE_NK', intent:'exr', count: (amfResult?.shots?.length||amfResult?.length||0), files:[`${tl}_Nuke_PerShot.nk`], note:'Export Nuke .nk' });
        }catch{}
      } else if (AMF && typeof AMF.exportNukeScriptNK === "function"){
        AMF.exportNukeScriptNK(amfResult);
        try{
          const tl = safeFilename(amfResult?.edlTitle || amfResult?.rootName || 'TIMELINE');
          window.MPS_auditAdd?.({ type:'NUKE_NK', intent:'exr', count: (amfResult?.shots?.length||amfResult?.length||0), files:[`${tl}_Nuke_PerShot.nk`], note:'Export Nuke .nk' });
        }catch{}
      }
    });
  }

  if (nukeBtn){
    nukeBtn.removeAttribute("disabled");
    on(nukeBtn, "click", async () => {
      const _retry = () => setTimeout(() => { try{ nukeBtn.click(); }catch{} }, 0);
      try{ if (!(await window.MPS_validateBeforeExport?.("exr", _retry))) return; }catch{}

      if (!amfResult){
        showError("Scan a VFX folder first.");
        return;
      }
      if (AMF && typeof AMF.exportNukePY === "function"){
        Promise.resolve(AMF.exportNukePY(amfResult)).catch(()=>{});
        try{
          const tl = safeFilename(amfResult?.edlTitle || amfResult?.rootName || 'TIMELINE');
          window.MPS_auditAdd?.({ type:'NUKE_PY', intent:'exr', count: (amfResult?.shots?.length||amfResult?.length||0), files:[`${tl}_Nuke_PerShot.py`], note:'Export Nuke .py' });
        }catch{}
      }
    });
  }

  renderAMFResult(null);
}

// -------------------------------------------------------------
// State
// -------------------------------------------------------------
const qsState = {
  conform:    false,
  vfxrename:  false,
  vfxmarker:  false,
  merge:      false,
  flatten:    false,
  decompose:  false,
  metadata:   false,
  autosplit:  false,
  df:         false,
  extra:      false
};

let raw = { events: [], fps: 24, projectName: "PROJECT" };
let view = [];
// Diff: snapshot of previous view keyed by reel|srcIn before each EDL reload
let _diffPrevKeys = null; // Map<key, {srcOut,recIn,recOut}> | null

// Scene/Take persistence: survives EDL reloads via localStorage
// key = "reel|srcIn", value = { scene, take }
let _evtMetaStore = (() => {
  try {
    const d = localStorage.getItem('pfx.eventMeta.v1');
    return d ? new Map(Object.entries(JSON.parse(d))) : new Map();
  } catch { return new Map(); }
})();
function _evtMetaSave() {
  try { localStorage.setItem('pfx.eventMeta.v1', JSON.stringify(Object.fromEntries(_evtMetaStore))); } catch {}
}
let selectedIndex = -1;

// ── Match Back state ──────────────────────────────────────────────────────────
let _mbLookup   = new Map();  // stemLower(renamed) → original camera name
let _mbFileMeta = [];         // [{ name, count }]
let _mbEvLists  = [];         // raw ALE event arrays (for re-merge on more drops)
let _mbApplied  = false;
let selectedForExport = new Set();

// Event Table navigation state (visual order + range selection)
let evtRowOrder = [];
let evtRowOrderPos = new Map();
let evtRangeAnchor = -1;
let evtLastFocusedRow = -1;


// Event Table "Only" filters (header checkboxes)
// - Advanced FDL ▸ Only  -> show/select only rows that need advanced finishing
// - Advanced FDL ▸ inv   -> invert filter (show/select only NOT-matching rows)
// - Handles ▸ Only       -> show/select only rows that have speed handles (±fr)
// - Handles ▸ inv        -> invert filter (show/select only NOT-matching rows)
// Modes are mutually exclusive.
const evtOnlyState = { mode: "" };

function _onlyMatchAdvFdl(ev){
  try{ return !!hasAdvancedFDL(ev); }catch{ return false; }
}

function _onlyMatchHandles(ev){
  try{ return handlesTextFor(ev) !== "—"; }catch{ return false; }
}

function _onlyMatchByMode(ev, mode){
  const m = String(mode || "");
  if (m === "adv")       return _onlyMatchAdvFdl(ev);
  if (m === "advInv")    return !_onlyMatchAdvFdl(ev);
  if (m === "handles")   return _onlyMatchHandles(ev);
  if (m === "handlesInv")return !_onlyMatchHandles(ev);
  return true;
}


function setEventOnlyMode(mode){
  const m0 = String(mode || "");
  const m = m0.toLowerCase().replace(/\s+/g,"");

  const toAdvOnly = (m === "adv" || m === "advfdl" || m === "advanced");
  const toAdvInv  = (m === "advinv" || m === "adv-inv" || m === "adv_inv" || m === "invadv" || m === "!adv" || m === "notadv");
  const toHanOnly = (m === "handles" || m === "handle");
  const toHanInv  = (m === "handlesinv" || m === "handles-inv" || m === "handles_inv" || m === "invhandles" || m === "!handles" || m === "nothandles");

  const nextMode = toAdvOnly ? "adv" : (toAdvInv ? "advInv" : (toHanOnly ? "handles" : (toHanInv ? "handlesInv" : "")));

  // toggle state (single active mode)
  evtOnlyState.mode = nextMode;

  // When turning ON a mode -> auto-select only matching rows.
  // When turning OFF -> restore default auto-select (Conform/VFX modes) if active.
  if (nextMode){
    selectedForExport.clear();
    for (let i=0; i<view.length; i++){
      const ev = view[i];
      if (_onlyMatchByMode(ev, nextMode)) selectedForExport.add(i);
    }
  } else {
    // restore default ready-to-export selection when QS modes are active
    if (qsState.conform || qsState.vfxrename || qsState.vfxmarker){
      selectedForExport.clear();
      for (let i=0; i<view.length; i++) selectedForExport.add(i);
    }
    // otherwise: keep current selection as-is
  }

  renderKPIs(view);
  renderTable();
  try{ renderEDLTimeline(); }catch{}
  updateInspector();
  try{ window.MPS_updateValidation?.({}); }catch{}

  // After file load / major recompute the layout settles on the next frame.
  // Re-ensure Event Table DOM + selection once sizes are known.
  // (Fixes cases where the Event Table area looks "empty" right after load.)
  if (view && view.length){
    try{
      setTimeout(() => {
        try{ ensureEventTableRendered(); }catch(e){}
        try{ applySelectionToDOM({ force:true }); }catch(e){}
      }, 0);
      setTimeout(() => {
        try{ ensureEventTableRendered(); }catch(e){}
        try{ applySelectionToDOM({ force:true }); }catch(e){}
      }, 180);
    }catch(e){}
  }
}

// Manual Handles override (per event)
const manualHandlesByKey = new Map();


const DEFAULT_SPEED_HANDLES = 24; // default per-side frames for speed-change clips
function eventKey(ev){
  if(!ev) return "";
  return `${ev.reel||""}|${ev.clipName||""}|${ev.recIn||""}|${ev.recOut||""}`;
}

function ensureBaseSrc(ev){
  if(!ev) return;
  if(!ev._srcInBase) ev._srcInBase = ev.srcIn;
  if(!ev._srcOutBase) ev._srcOutBase = ev.srcOut;
}

function applyManualHandlesToEvent(ev, headFrames, tailFrames){
  if(!ev) return;
  ensureBaseSrc(ev);
  const fps = ev.fps || raw.fps || 24;
  const baseIn  = tcToFrames(ev._srcInBase, fps);
  const baseOut = tcToFrames(ev._srcOutBase, fps);

  const h = Math.max(0, Math.floor(Number(headFrames)||0));
  const t = Math.max(0, Math.floor(Number(tailFrames)||0));

  const newIn  = Math.max(0, baseIn - h);
  const newOut = Math.max(newIn, baseOut + t);

  ev.srcIn  = framesToTC(newIn, fps);
  ev.srcOut = framesToTC(newOut, fps);
  ev._manualHandles = { head: h, tail: t };
}

function applyDefaultSpeedHandles(evs){
  if(!Array.isArray(evs) || !evs.length) return evs;
  const out = evs.map(ev => {
    try{
      if(!hasSpeedChange(ev)) return ev;
      const key = eventKey(ev);
      if(manualHandlesByKey.has(key)) return ev; // user override wins
      applyManualHandlesToEvent(ev, DEFAULT_SPEED_HANDLES, DEFAULT_SPEED_HANDLES);
    }catch{}
    return ev;
  });
  return out;
}

function applyManualHandlesMap(evs){
  if(!Array.isArray(evs) || !manualHandlesByKey.size) return evs;
  return evs.map(ev => {
    const mh = manualHandlesByKey.get(eventKey(ev));
    if(!mh) return ev;

    const both = mh.both ?? mh.head ?? 0;
    const head = both;
    const tail = (mh.both != null) ? both : (mh.tail ?? both);

    applyManualHandlesToEvent(ev, head, tail);
    return ev;
  });
}

function updateSelectedRowSrcCells(){
  const tr = document.querySelector(`#eventTable tr[data-i="${selectedIndex}"]`);
  if(!tr) return;
  const ev = view && view[selectedIndex];
  if(!ev) return;

  // columns: 1 checkbox, 2 event, 3 reel, 4 clip, 5 scene, 6 take, 7 cam, 8 storage, 9 advFdl, 10 handles, 11 srcIn, 12 srcOut ...
  const tds = tr.querySelectorAll("td");
  if(tds && tds.length >= 12){
    const handlesSpan = tds[9].querySelector("span");
    if(handlesSpan) handlesSpan.textContent = handlesTextFor(ev);
    const srcInSpan  = tds[10].querySelector("span");
    const srcOutSpan = tds[11].querySelector("span");
    if(srcInSpan)  srcInSpan.textContent  = ev.srcIn || "—";
    if(srcOutSpan) srcOutSpan.textContent = ev.srcOut || "—";
  }
}


// Event table pagination (Content Hub style)
// rpp: rows per page (0 = All)
const pagingState = {
  page: 1,
  rpp: 0 // paging disabled (continuous scroll)
};

// Locator override storage
const locatorOverrides = new Map();

function locatorKey(ev){
  return [
    ev.reel || "",
    ev.srcIn || "",
    ev.recIn || "",
    ev.clipName || ""
  ].join("|");
}

// -------------------------------------------------------------
// Helpers (UI / layout)
// -------------------------------------------------------------
function showError(msg){
  // Display lives in core/errorBanner.js. This used to look up an element with
  // id="errors" and return early when it was null — which it always was, since
  // no page has ever contained one. See that file for the history.
  showErrorBanner(msg || "");
}

function setInnerTab(key){
  const wantInput = key === "input";
  $$(".inner-tab").forEach(x => x.classList.toggle("active", x.getAttribute("data-itab") === key));
  const a = $("#itab-input"), b = $("#itab-inspector");
  if (a && b){
    a.style.display = wantInput ? "block" : "none";
    b.style.display = wantInput ? "none" : "block";
  }
}

function setAllOffActive(onFlag){
  const b = $("#qsAllOff");
  if (!b) return;
  b.classList.toggle("active", !!onFlag);
  b.setAttribute("aria-pressed", onFlag ? "true" : "false");
}

function syncAllOffWidth(){
  const a = $("#qsAllOff");
  if (!a) return;
  // If All OFF is inside #qsRow the grid handles sizing — clear any explicit width.
  if (a.closest('#qsRow')) { a.style.width = ""; a.style.minWidth = ""; return; }
  // Otherwise (legacy: All OFF outside grid) match Conform button width.
  const f = document.querySelector('#qsRow .qs-btn[data-key="conform"]')
         || document.querySelector('#qsRow .qs-btn:not(#qsAllOff)');
  if (f){
    const w = f.getBoundingClientRect().width;
    a.style.width = w ? `${w}px` : "";
  }
}

// -------------------------------------------------------------
// File list renderer
// -------------------------------------------------------------
function ensureFileListHost(){
  let host = document.getElementById("fileList");
  if (!host){
    const dz = document.getElementById("dropZone");
    host = document.createElement("div");
    host.id = "fileList";
    host.style.marginTop = "10px";
    host.style.opacity = "0.85";
    host.style.fontSize = "12px";
    host.style.lineHeight = "1.4";
    host.style.whiteSpace = "nowrap";
    host.style.overflow = "hidden";
    host.style.textOverflow = "ellipsis";
    (dz?.parentNode || document.body).appendChild(host);
  }
  return host;
}

function renderFileList(fs = []){
  const host = ensureFileListHost();
  if (!fs?.length){
    host.innerHTML = "";
    return;
  }
  host.innerHTML = fs.map(f => {
    const p = f.virtualPath || f.name || "—";
    return `<div class="file-row">📄 ${esc(p)}</div>`;
  }).join("");
}

