// Sprint A.2: Global Project Bar (multi-project UX)
// -------------------------------------------------------------
function _storageGet(keys){
  try{
    const result = {};
    for(const k of (Array.isArray(keys) ? keys : [keys])){
      try{
        const raw = localStorage.getItem(k);
        if(raw !== null) result[k] = JSON.parse(raw);
      }catch{}
    }
    return Promise.resolve(result);
  }catch{ return Promise.resolve({}); }
}
function _storageSet(obj){
  try{
    for(const [k, v] of Object.entries(obj)){
      try{
        if(v === null || v === undefined) localStorage.removeItem(k);
        else localStorage.setItem(k, JSON.stringify(v));
      }catch{}
    }
    return Promise.resolve(true);
  }catch{ return Promise.resolve(false); }
}

function _storageClearArea(area){
  return new Promise((resolve) => {
    try{
      const api = chrome?.storage?.[area];
      if (!api?.clear) return resolve(false);
      api.clear(() => resolve(true));
    }catch{
      resolve(false);
    }
  });
}

async function _deleteIndexedDbByName(name){
  const dbName = String(name || '').trim();
  if (!dbName) return false;
  return await new Promise((resolve) => {
    try{
      const req = indexedDB.deleteDatabase(dbName);
      let done = false;
      const finish = (ok) => { if (done) return; done = true; resolve(!!ok); };
      req.onsuccess = () => finish(true);
      req.onerror = () => finish(false);
      req.onblocked = () => finish(false);
    }catch{
      resolve(false);
    }
  });
}

async function clearPostFlowXChromeMemory(){
  const report = {
    sessionStorage: 0,
    chromeSession: false,
    mediaElements: 0,
    blobUrls: 0,
    objectRefs: 0,
    customCleanupEvent: false
  };

  // Light cleanup only:
  // - keep localStorage / chrome.storage.local / chrome.storage.sync / IndexedDB intact
  // - clear transient session-only state and unload current media/blob memory
  // This reduces browser work without wiping saved project/settings memory.

  // 1) Session-only storage.
  try{
    report.sessionStorage = sessionStorage.length || 0;
    sessionStorage.clear();
  }catch{}
  try{ report.chromeSession = await _storageClearArea('session'); }catch{}

  // 2) Let feature modules do their own best-effort cleanup if they listen for it.
  try{
    window.dispatchEvent(new CustomEvent('mps:beforeClearRuntimeMemory', { detail: report }));
    report.customCleanupEvent = true;
  }catch{}

  // 3) Unload media elements and revoke blob URLs currently attached to the page.
  try{
    const els = Array.from(document.querySelectorAll('video, audio, img, source'));
    const seenBlob = new Set();
    for (const el of els){
      try{
        const src = String(el.currentSrc || el.src || el.getAttribute?.('src') || '').trim();
        if (src && src.startsWith('blob:')) seenBlob.add(src);
      }catch{}
      try{
        const poster = String(el.poster || '').trim();
        if (poster && poster.startsWith('blob:')) seenBlob.add(poster);
      }catch{}
      try{
        if (el.tagName === 'VIDEO' || el.tagName === 'AUDIO'){
          report.mediaElements += 1;
          try{ el.pause?.(); }catch{}
          try{ el.removeAttribute('src'); }catch{}
          try{ el.srcObject = null; }catch{}
          try{ Array.from(el.querySelectorAll('source')).forEach((s) => s.removeAttribute('src')); }catch{}
          try{ el.load?.(); }catch{}
        }else if (el.tagName === 'IMG' || el.tagName === 'SOURCE'){
          try{ el.removeAttribute('src'); }catch{}
        }
      }catch{}
    }
    for (const url of seenBlob){
      try{ URL.revokeObjectURL(url); report.blobUrls += 1; }catch{}
    }
  }catch{}

  // 4) Best-effort reset of large in-memory globals for the current page before reload.
  const refs = [
    '__MPS_EDL_RAW',
    '__MPS_CD_SNAPSHOT',
    '__MPS_SM_SNAPSHOT',
    '__MPS_AMF_STATE',
    '__MPS_AMF_FILE_PARSED',
    '__MPS_OCIO_FILE_META'
  ];
  for (const k of refs){
    try{ if (k in window){ window[k] = null; report.objectRefs += 1; } }catch{}
  }
  try{ window.__MPS_OCIO_HASH = ''; }catch{}
  try{ window.__MPS_OCIO_PROJECT_HASH = ''; }catch{}
  try{ window.__MPS_PROJECT_DIRTY = false; }catch{}

  return report;
}

// Project Bar scope (per main tab). We store recents + current name separately per tab.
// main tabs (current data-main keys): prepmark/cutdiff2/platelink2/reviews/trlconf/imf/about
// project shards: pull_prep/cut_diff/plate_link/review/imf/settings  (TAB_FILES keys)
const __PFX_PROJECT_SCOPE_MAP = {
  // Current tab keys
  prepmark:   'pull_prep',
  cutdiff2:   'cut_diff',
  platelink2: 'plate_link',
  reviews:    'review',
  trlconf:    'trl_conf',
  imf:        'imf',
  bwav:       'bwav',
  preflight:  'preflight',
  aceslook:   'aces_look',
  renderq:    'render_queue',
  about:      'settings',
  // Legacy aliases (old data-main values kept for backwards compat)
  edl:        'pull_prep',
  cutdiff:    'cut_diff',
  shotmarker: 'markers',
  markers:    'markers',
  amf:        'plate_link',
};

function _pfxActiveMainTab(){
  try{ return String(document.body?.dataset?.main || '').trim() || (document.querySelector('.tabs .tab.active')?.getAttribute('data-main') || 'edl'); }
  catch{ return 'edl'; }
}

// Called on every tab switch — refreshes recent list + project name + dirty dot for the new scope.
async function _pfxRefreshProjectBarForTab(){
  try{
    const scope = _pfxProjectScope();
    const kName  = `currentProjectName:${scope}`;
    const kLast  = `lastActiveProject:${scope}`;
    const kRecent = `recentProjects:${scope}`;
    const data = await _storageGet([kName, kLast, kRecent]);

    // Update project name input
    const nameInput = document.getElementById('projectNameGlobal');
    const currentName = String(data?.[kName] || data?.[kLast] || '').trim();
    if (nameInput) nameInput.value = currentName;

    // Sync legacy fields used by Pull Prep
    try{ syncProjectNameEverywhere(currentName); }catch{}

    // Refresh the hidden <select> (drives the recent panel list)
    await refreshProjectSelect();

    // Update the Recent button label
    try{
      const lbl = document.querySelector('#projRecentBtn .proj-recent-btn-label');
      if (lbl) lbl.textContent = currentName ? (currentName.length > 18 ? currentName.slice(0,17)+'…' : currentName) + ' ▾' : 'Recent ▾';
    }catch{}

    // Sync dirty dot for this scope
    try{
      const dot = document.getElementById('projDirtyDot');
      if (dot) dot.classList.toggle('on', !!__PFX_DIRTY_BY_SCOPE[scope]);
      window.__MPS_PROJECT_DIRTY = !!__PFX_DIRTY_BY_SCOPE[scope];
    }catch{}

    // Update save status label
    try{
      const st = document.getElementById('projSaveStatus');
      if (st && !__PFX_DIRTY_BY_SCOPE[scope]) st.textContent = currentName ? `${currentName}` : 'Ready';
    }catch{}
  }catch(_){}
}

function _pfxProjectScope(){
  const m = _pfxActiveMainTab();
  return __PFX_PROJECT_SCOPE_MAP[m] || 'pull_prep';
}

function _pfxKey(base){
  return `${base}:${_pfxProjectScope()}`;
}

// Dirty state must also be per tab (so the dot matches the current tab).
const __PFX_DIRTY_BY_SCOPE = Object.create(null);

function setDirty(onDirty){
  const dot = document.getElementById("projDirtyDot");
  const scope = _pfxProjectScope();
  __PFX_DIRTY_BY_SCOPE[scope] = !!onDirty;
  if (dot) dot.classList.toggle("on", !!onDirty);
  try{ window.__MPS_PROJECT_DIRTY = __PFX_DIRTY_BY_SCOPE[scope] || false; }catch{}
}
// After a full project load (all tabs), clear every scope's dirty flag.
function _clearAllScopesDirty(){
  const allScopes = Array.from(new Set(Object.values(__PFX_PROJECT_SCOPE_MAP || {})));
  for (const sc of allScopes) __PFX_DIRTY_BY_SCOPE[sc] = false;
  const dot = document.getElementById("projDirtyDot");
  if (dot) dot.classList.remove("on");
  try{ window.__MPS_PROJECT_DIRTY = false; }catch{}
}
// After a full project load (all tabs), propagate the project name to every scope's storage key
// so tab-switching shows the correct name in the project bar.
function _syncNameToAllScopes(name){
  const n = String(name || "");
  const allScopes = Array.from(new Set(Object.values(__PFX_PROJECT_SCOPE_MAP || {})));
  const updates = {};
  for (const sc of allScopes){
    updates[`currentProjectName:${sc}`] = n;
    updates[`lastActiveProject:${sc}`]  = n;
  }
  try{ _storageSet(updates); }catch{}
}

// Sprint A.3: Autosave + Crash Recovery (best-effort)
// Per-scope state so one tab's save never blocks or throttles another tab's save.
const __mpsAutosaveTimerByScope   = Object.create(null);
const __mpsLastAutosaveByScope    = Object.create(null);
const __mpsAutosaveInFlightScope  = Object.create(null);

function _formatTimeHM(ts){
  try{
    const d = new Date(ts);
    const hh = String(d.getHours()).padStart(2,"0");
    const mm = String(d.getMinutes()).padStart(2,"0");
    return `${hh}:${mm}`;
  }catch{ return ""; }
}

// Core per-scope autosave — scope and name captured at schedule time, not at fire time.
async function _doAutosaveForScope(scope, name, reason){
  if (!scope || !name) return;
  if (!__PFX_DIRTY_BY_SCOPE[scope]) return;
  if (__mpsAutosaveInFlightScope[scope]) return;
  const now = Date.now();
  if ((now - (__mpsLastAutosaveByScope[scope] || 0)) < 10_000) return;
  __mpsAutosaveInFlightScope[scope] = true;
  try{
    const _SHARD_KEYS = new Set(['pull_prep','cut_diff','markers','plate_link','imf','review','trl_conf','aces_look','render_queue','settings','shots']);
    const r = _SHARD_KEYS.has(scope)
      ? await saveTabProjectAutosave(scope, name)
      : await saveUnifiedProjectAutosave(name);
    if (r?.ok){
      __mpsLastAutosaveByScope[scope] = Date.now();
      __PFX_DIRTY_BY_SCOPE[scope] = false;
      // Only update the dot when this scope is still the active one.
      if (_pfxProjectScope() === scope){
        const dot = document.getElementById("projDirtyDot");
        if (dot){
          dot.classList.remove("on");
          dot.title = `Autosaved ${_formatTimeHM(__mpsLastAutosaveByScope[scope])}${reason ? " • " + reason : ""}`;
        }
        try{ window.__MPS_PROJECT_DIRTY = false; }catch{}
      }
    }
  }catch{}
  __mpsAutosaveInFlightScope[scope] = false;
}

// Called by interval + visibilitychange: saves the currently-visible scope.
async function _doAutosave(reason){
  const scope = _pfxProjectScope();
  const nameInput = document.getElementById("projectNameGlobal");
  const name = (nameInput?.value || (scope === 'pull_prep' ? (raw?.projectName || window.__MPS_PROJECT_NAME || "") : "")).trim();
  await _doAutosaveForScope(scope, name, reason);
}

function MPS_markProjectDirty(reason){
  setDirty(true);
  // Capture scope + name now so the timer fires for the right tab even if the user
  // switches tabs before the 3 s delay expires.
  const scope = _pfxProjectScope();
  const nameInput = document.getElementById("projectNameGlobal");
  const name = (nameInput?.value || (scope === 'pull_prep' ? (raw?.projectName || window.__MPS_PROJECT_NAME || "") : "")).trim();
  clearTimeout(__mpsAutosaveTimerByScope[scope]);
  if (name) __mpsAutosaveTimerByScope[scope] = setTimeout(() => _doAutosaveForScope(scope, name, reason || "change"), 3000);
}

try{ window.MPS_markProjectDirty = MPS_markProjectDirty; }catch{}

function syncProjectNameEverywhere(name){
  const n = String(name || "");
  // Store per-tab project name (so tabs don't see each other's names).
  try{ _storageSet({ [_pfxKey('currentProjectName')]: n }); }catch{}

  // Only sync to the legacy EDL input when we're on the Pull Prep (EDL) tab.
  if (_pfxProjectScope() === 'pull_prep'){
    const pn = document.getElementById("projectName");
    if (pn) pn.value = n;
    try{ if (raw) raw.projectName = n; }catch{}
    try{ window.__MPS_PROJECT_NAME = n; }catch{}
  }
}

async function refreshProjectSelect(preferList){
  const sel = document.getElementById("projSelect");
  if (!sel) return;

  const kRecent = _pfxKey('recentProjects');
  const data = await _storageGet([kRecent]);
  const recentProjects = Array.isArray(data[kRecent]) ? data[kRecent] : [];
  const items = Array.isArray(preferList) && preferList.length ? preferList : recentProjects;

  sel.innerHTML = "";
  const opt0 = document.createElement("option");
  opt0.value = "";
  opt0.textContent = "Recent…";
  sel.appendChild(opt0);

  items.forEach(p => {
    const o = document.createElement("option");
    o.value = p;
    o.textContent = p;
    sel.appendChild(o);
  });
}

async function addToRecents(name){
  const n = String(name||"").trim();
  if (!n) return;
  const kRecent = _pfxKey('recentProjects');
  const kLast   = _pfxKey('lastActiveProject');
  const data = await _storageGet([kRecent]);
  const cur = Array.isArray(data[kRecent]) ? data[kRecent] : [];
  const next = [n, ...cur.filter(x => x !== n)].slice(0, 15);
  await _storageSet({ [kRecent]: next, [kLast]: n, [_pfxKey('currentProjectName')]: n });
  await refreshProjectSelect(next);
}

function safeClick(id){
  const el = document.getElementById(id);
  if (el) el.click();
}

function __pfxSetText(id, text){
  const el = document.getElementById(id);
  if (el) { el.textContent = String(text ?? ''); el.style.color = ''; }
}

function __pfxRefreshNoteTypesStatus(){
  try{
    const cur = (typeof PFX_getNoteTypesConfig === 'function') ? PFX_getNoteTypesConfig() : __pfxDefaultNoteTypes();
    // The card holds two lists and Reset clears both, so the readout counts both.
    const sow = (typeof PFX_getSowPresets === 'function') ? PFX_getSowPresets() : __pfxDefaultSowPresets();
    const TT = (s)=>{ try{ if (typeof window.PFX_t === 'function') return window.PFX_t(String(s||'')); }catch{} return String(s||''); };
    __pfxSetText('ntStatus', `${TT('Add')} ${cur?.add?.length||0} · ${TT('Remove')} ${cur?.remove?.length||0} · ${TT('Change')} ${cur?.change?.length||0} · ${TT('Scope of Work')} ${sow?.length||0}`);
  }catch{}
}

function __pfxRefreshShortcutStatus(){
  try{
    const TT = (s)=>{ try{ if (typeof window.PFX_t === 'function') return window.PFX_t(String(s||'')); }catch{} return String(s||''); };
    const { total, custom } = computeCustomCount(getShortcutsConfig());
    __pfxSetText('scStatus', `${TT('Custom')} ${custom} / ${total}`);
  }catch{}
}

async function __pfxResetSettingsForNewProject(){
  try{ if (typeof PFX_setNoteTypesConfig === 'function') PFX_setNoteTypesConfig(__pfxDefaultNoteTypes()); }catch{}
  try{ if (typeof PFX_setSowPresets === 'function') PFX_setSowPresets(__pfxDefaultSowPresets()); }catch{}
  try{ resetShortcutsToDefaults(); }catch{}
  try{ await clearMediaRootDir(); }catch{}
  try{ localStorage.removeItem('pfx_media_root_path'); }catch{}
  try{ localStorage.removeItem('pfx_media_root_configured'); }catch{}
  try{ localStorage.removeItem('pfx_project_dir_path'); }catch{}
  try{ window.__PFX_MEDIA_INDEX = null; }catch{}
  try{ safeClick('fbClear'); }catch{}
  try{ __pfxRefreshNoteTypesStatus(); }catch{}
  try{ __pfxRefreshShortcutStatus(); }catch{}
  try{
    const ready = await isProjectDirConfigured();
    __pfxSetText('mmProjectStatus', ready ? 'Project Folder: configured ✓' : 'Project Folder: not set');
  }catch{}
  try{ __pfxSetText('mmMediaStatus', 'Media Root: not set'); }catch{}
  try{ __pfxSetText('mmScanStatus', 'Index: not scanned'); }catch{}
}

async function __pfxResetCurrentTabForNewProject(){
  const main = _pfxActiveMainTab();
  if (main === 'edl'){
    safeClick('btnClear');
    return;
  }
  if (main === 'prepmark'){
    try{ window.__pmClear?.(); }catch{}
    return;
  }
  if (main === 'cutdiff2'){
    try{ cutDiff2Feature?.clear?.(); }catch{}
    try{ window.__MPS_CD_SNAPSHOT = null; }catch{}
    return;
  }
  if (main === 'shotmarker' || main === 'markers'){
    try{
      if (typeof window.PFX_resetShotMarkerForNewProject === 'function'){
        window.PFX_resetShotMarkerForNewProject();
      }else{
        safeClick('smTlBatchClear');
        safeClick('smShotListFilterClear');
        safeClick('smImportTimelineRemove');
        safeClick('smImportVideoRemove');
        safeClick('smImportClearBtn');
      }
    }catch{}
    try{ window.__MPS_SM_SNAPSHOT = null; }catch{}
    return;
  }
  if (main === 'amf'){
    safeClick('amfClear');
    try{ window.__MPS_AMF_STATE = null; }catch{}
    return;
  }
  if (main === 'platelink2'){
    try{ plateLinkFeature?.clear?.(); }catch{}
    try{ window.__MPS_AMF_STATE = null; }catch{}
    return;
  }
  if (main === 'reviews'){
    try{ reviewsTab?.pause?.(); }catch{}
    try{ reviewsTab?.store?.clearAll?.(); }catch{}
    return;
  }
  if (main === 'trlconf'){
    try{ trlConformFeature?.clear?.(); }catch{}
    try{ window.__PFX_TRL_CONF_STATE = null; }catch{}
    return;
  }
  if (main === 'imf'){
    safeClick('imfClearBtn');
    return;
  }
  if (main === 'about'){
    await __pfxResetSettingsForNewProject();
  }
}

let _pfxResetAllInProgress = false;
async function __pfxResetAllTabsForNewProject(){
  if (_pfxResetAllInProgress) return;
  _pfxResetAllInProgress = true;
  try{ await _pfxResetAllTabsImpl(); }finally{ _pfxResetAllInProgress = false; }
}
async function _pfxResetAllTabsImpl(){
  // Pull Prep (EDL)
  try{ safeClick('btnClear'); }catch{}
  // Prep & Mark
  try{ window.__pmClear?.(); }catch{}
  // Cut Diff 2.0
  try{ cutDiff2Feature?.clear?.(); }catch{}
  try{ window.__MPS_CD_SNAPSHOT = null; }catch{}
  try{ __pfxSetText('cutdiffProjectStatus', '—'); }catch{}
  // Markers / Shot Marker
  try{
    if (typeof window.PFX_resetShotMarkerForNewProject === 'function'){
      window.PFX_resetShotMarkerForNewProject();
    } else {
      safeClick('smTlBatchClear');
      safeClick('smShotListFilterClear');
      safeClick('smImportTimelineRemove');
      safeClick('smImportVideoRemove');
      safeClick('smImportClearBtn');
    }
  }catch{}
  try{ window.__MPS_SM_SNAPSHOT = null; }catch{}
  // Plate Link (AMF — legacy)
  try{ safeClick('amfClear'); }catch{}
  try{ window.__MPS_AMF_STATE = null; }catch{}
  // Plate Link 2.0
  try{ plateLinkFeature?.clear?.(); }catch{}
  // Visual QC (Reviews)
  try{ reviewsTab?.pause?.(); }catch{}
  try{ reviewsTab?.store?.clearAll?.(); }catch{}
  // Trailers Conform
  try{ trlConformFeature?.clear?.(); }catch{}
  try{ window.__PFX_TRL_CONF_STATE = null; }catch{}
  // IMF Validation
  try{ safeClick('imfClearBtn'); }catch{}
  // Settings
  try{ await __pfxResetSettingsForNewProject(); }catch{}
  // Clear dirty flags + scoped storage for ALL scopes.
  try{
    const allScopes = Array.from(new Set(Object.values(__PFX_PROJECT_SCOPE_MAP || {})));
    for (const sc of allScopes) __PFX_DIRTY_BY_SCOPE[sc] = false;
    try{ window.__MPS_PROJECT_DIRTY = false; }catch{}
    const dot = document.getElementById('projDirtyDot');
    if (dot) dot.classList.remove('on');
    // Wipe per-scope last-active and current-project-name so auto-restore
    // on next boot doesn't bring back a project that was just cleared.
    const clears = {};
    for (const sc of allScopes){
      clears[`lastActiveProject:${sc}`] = "";
      clears[`currentProjectName:${sc}`] = "";
    }
    _storageSet(clears);
    // Clear legacy Pull Prep name globals (used by _doAutosave / EDL input fallback).
    try{ if (typeof raw !== 'undefined' && raw) raw.projectName = ""; }catch{}
    try{ window.__MPS_PROJECT_NAME = ""; }catch{}
    // Sync the legacy EDL project name input to empty.
    try{ const pn = document.getElementById("projectName"); if (pn) pn.value = ""; }catch{}
  }catch{}
  // Reset project bar UI (name, recent label, save status).
  try{ window.__pfxResetProjectBarForClear?.(); }catch{}
}
window.PFX_clearAllTabs = __pfxResetAllTabsForNewProject;


function __pfxTabLabel(main){
  const key = String(main || _pfxActiveMainTab() || '').trim();
  // Current tab keys
  if (key === 'prepmark')   return 'Pull Prep';
  if (key === 'cutdiff2')   return 'Cut Diff';
  if (key === 'platelink2') return 'Plate Link';
  if (key === 'reviews')    return 'Visual QC';
  if (key === 'trlconf')    return 'Trailers Conform';
  if (key === 'imf')        return 'IMF Validation';
  if (key === 'about')      return 'Settings';
  // Legacy aliases
  if (key === 'edl')        return 'Pull Prep';
  if (key === 'cutdiff')    return 'Cut Diff';
  if (key === 'shotmarker' || key === 'markers') return 'Markers';
  if (key === 'amf')        return 'Plate Link';
  return 'Current Tab';
}

function __pfxHasItems(v){
  return Array.isArray(v) && v.length > 0;
}

function __pfxSameJson(a, b){
  try{ return JSON.stringify(a) === JSON.stringify(b); }catch{ return false; }
}

async function __pfxInspectCurrentTabForNewProject(){
  const main = _pfxActiveMainTab();
  const scope = _pfxProjectScope();
  const reasons = [];
  const seen = new Set();
  const push = (msg) => {
    const s = String(msg || '').trim();
    if (!s || seen.has(s)) return;
    seen.add(s);
    reasons.push(s);
  };

  try{
    const dirty = !!(__PFX_DIRTY_BY_SCOPE[scope] || window.__MPS_PROJECT_DIRTY);
    if (dirty) push('Unsaved changes');
  }catch{}

  try{
    const projectName = String(document.getElementById('projectNameGlobal')?.value || window.__MPS_PROJECT_NAME || '').trim();
    if (projectName) push(`Project name: ${projectName}`);
  }catch{}

  if (main === 'prepmark' || main === 'edl'){
    try{
      const snap = window.__MPS_EDL_RAW || raw || null;
      const events = Array.isArray(snap?.events) ? snap.events.length : 0;
      if (events > 0) push(`Timeline events: ${events}`);
    }catch{}
  }

  if (main === 'cutdiff2'){
    try{
      const snap = window.__MPS_CD_SNAPSHOT || null;
      const diff = Array.isArray(snap?.diff) ? snap.diff.length : 0;
      if (diff > 0) push(`Diff events: ${diff}`);
      else if (snap?.oldEvents?.length || snap?.newEvents?.length) push('Cut Diff data loaded');
    }catch{}
  }

  if (main === 'platelink2'){
    try{
      // plateLinkFeature v2 uses localStorage, not window.__MPS_AMF_STATE
      if (localStorage.getItem('pfx.platelink2.lastResult.v1')) push('Plate link data loaded');
    }catch{}
    try{
      // Legacy AMF state (amf tab / v1 data)
      const st = window.__MPS_AMF_STATE || {};
      if (Object.keys(st).filter(k => k !== 'policy').length > 0) push('Plate link state (legacy)');
    }catch{}
  }

  if (main === 'trlconf'){
    try{
      const tcState = trlConformFeature?.exportState?.() || window.__PFX_TRL_CONF_STATE;
      if (tcState?.analyzed){
        const evCount = Array.isArray(tcState.events) ? tcState.events.length : 0;
        if (evCount > 0) push(`Conform events: ${evCount}`);
        else push('Trailers Conform state');
      }
    }catch{}
  }

  if (main === 'imf'){
    try{
      if (window.__PFX_IMF_STATE != null) push('IMF validation state');
    }catch{}
  }

  if (main === 'shotmarker' || main === 'markers'){
    try{
      const snap = window.__MPS_SM_SNAPSHOT || window.__smGetProjectSnapshot?.() || {};
      const st = snap?.state || {};
      const video = snap?.video || {};
      const markersCount = Array.isArray(st.markers) ? st.markers.length : 0;
      const segmentsCount = Array.isArray(st.segments) ? st.segments.length : 0;
      if (String(video?.name || video?.srcName || '').trim()) push('Imported video');
      if (st.importedTimeline) push('Imported timeline');
      if (markersCount > 0) push(`Markers: ${markersCount}`);
      if (segmentsCount > 0) push(`Cut segments: ${segmentsCount}`);
    }catch{}
  }

  if (main === 'amf'){
    try{
      const shots = Number(document.getElementById('amfKpiShots')?.textContent || 0);
      const ready = Number(document.getElementById('amfKpiReady')?.textContent || 0);
      const missing = Number(document.getElementById('amfKpiMissing')?.textContent || 0);
      if (shots > 0) push(`Mapped shots: ${shots}`);
      if (ready > 0) push(`Ready shots: ${ready}`);
      if (missing > 0) push(`Missing shots: ${missing}`);
    }catch{}
    try{
      const st = window.__MPS_AMF_STATE || {};
      const keys = Object.keys(st || {}).filter(k => k !== 'policy');
      if (keys.length > 0) push('Plate link state');
    }catch{}
  }

  if (main === 'reviews'){
    try{
      const st = reviewsTab?.store?.state || {};
      const clips = Array.isArray(st.clips) ? st.clips.length : 0;
      const markers = Array.isArray(st.markers) ? st.markers.length : 0;
      if (clips > 0) push(`Clips: ${clips}`);
      if (markers > 0) push(`Review markers: ${markers}`);
      if (st.currentClipId != null) push('Selected clip');
    }catch{}
  }

  if (main === 'about'){
    try{
      const noteCfg = (typeof PFX_getNoteTypesConfig === 'function') ? PFX_getNoteTypesConfig() : __pfxDefaultNoteTypes();
      if (!__pfxSameJson(noteCfg, __pfxDefaultNoteTypes())) push('Custom note types');
    }catch{}
    try{
      const cnt = computeCustomCount(getShortcutsConfig());
      if (Number(cnt?.custom || 0) > 0) push(`Custom shortcuts: ${cnt.custom}`);
    }catch{}
    try{
      const mediaRootReady = await isMediaRootConfigured();
      if (mediaRootReady) push('Media Root set');
    }catch{}
    try{
      const feedbackIds = ['fbSubmittedBy','fbSubmitEmail','fbDescription','fbAttachments'];
      const hasText = feedbackIds.some((id) => String(document.getElementById(id)?.value || '').trim());
      const fbProduct = String(document.getElementById('fbProduct')?.value || '').trim();
      const fbType = String(document.getElementById('fbType')?.value || 'Bug').trim();
      if (hasText || fbProduct || (fbType && fbType !== 'Bug')) push('Feedback form values');
    }catch{}
  }

  return {
    main,
    scope,
    title: __pfxTabLabel(main),
    hasData: reasons.length > 0,
    reasons,
  };
}

function __pfxConfirmNewProjectMessage(info){
  const title = String(info?.title || 'Current Tab');
  const reasons = Array.isArray(info?.reasons) ? info.reasons.filter(Boolean) : [];
  const lines = [];
  lines.push(`Start a new project in ${title}?`);
  if (reasons.length){
    lines.push('');
    lines.push('This will clear the current tab data:');
    for (const item of reasons.slice(0, 8)) lines.push(`• ${item}`);
  }
  lines.push('');
  lines.push('Current tab data will be reset and cannot be undone.');
  return lines.join('\n');
}

