function wireInnerTabs(){
  $$(".inner-tab").forEach(tab => {
    on(tab, "click", () => {
      const key = tab.getAttribute("data-itab");
      setInnerTab(key);
    });
    tab.setAttribute("tabindex", "0");
    tab.setAttribute("role", "tab");

    on(tab, "keydown", (e) => {
      if (e.key === "Enter" || e.key === " "){
        if (e.cancelable) e.preventDefault();
        const key = tab.getAttribute("data-itab");
        setInnerTab(key);
      }
    });
  });
}

