// -------------------------------------------------------------
// Google Drive "Latest Version" (manifest.json) loader
// - Requires host_permissions for drive.google.com + drive.usercontent.google.com
// - Reads version from https://drive.google.com/uc?export=download&id=<FILE_ID>
// -------------------------------------------------------------
const _LATEST_CACHE_PREFIX = "mps_latest_manifest_cache_v3";
const DEFAULT_UPDATE_FOLDER_URL = "https://drive.google.com/drive/folders/1vBRSps03hPgijUhzP-39OpMu2tJ-zQOV?usp=drive_link";
const DEFAULT_UPDATE_MANIFEST_FOLDER_URL = "https://drive.google.com/drive/folders/10SukU7ndaHa7f0qf33SSBYRDOdtd_N2l?usp=drive_link";
const DEFAULT_UPDATE_MANIFEST_FILE_URL = "https://drive.google.com/file/d/1e5U7pvO_llQW-ooS2Fky-_pKIiRAkTFv/view?usp=sharing";
const DEFAULT_UPDATE_MANIFEST_PATH = "manifest.json";
const DEFAULT_UPDATE_MANIFEST_FILE_ID = "1e5U7pvO_llQW-ooS2Fky-_pKIiRAkTFv";

function _compareVersions(a, b){
  // Dot (or dash) separated numeric compare. Non-numeric chunks are treated as 0.
  const pa = String(a || "").split(/[^0-9]+/).filter(Boolean).map(n => parseInt(n, 10));
  const pb = String(b || "").split(/[^0-9]+/).filter(Boolean).map(n => parseInt(n, 10));
  const n = Math.max(pa.length, pb.length);
  for (let i = 0; i < n; i++){
    const va = Number.isFinite(pa[i]) ? pa[i] : 0;
    const vb = Number.isFinite(pb[i]) ? pb[i] : 0;
    if (va > vb) return 1;
    if (va < vb) return -1;
  }
  return 0;
}

function _latestCacheKey(sourceKey){
  const k = String(sourceKey || "default").trim() || "default";
  return `${_LATEST_CACHE_PREFIX}:${k}`;
}
function _getLatestCache(sourceKey){
  try{ return JSON.parse(localStorage.getItem(_latestCacheKey(sourceKey)) || "null"); }catch{ return null; }
}
function _setLatestCache(sourceKey, ver){
  try{ localStorage.setItem(_latestCacheKey(sourceKey), JSON.stringify({ ver, ts: Date.now() })); }catch{}
}

