function _nhClassifyError(msg) {
  const m = String(msg || '').toLowerCase();
  if (/not found|cannot find|not_found|no such file/i.test(m)) return 'HOST_NOT_FOUND';
  if (/forbidden|access.*denied|denied.*access/i.test(m))       return 'HOST_FORBIDDEN';
  if (/exited|disconnected|invalid|host has exited/i.test(m))   return 'HOST_CRASHED';
  if (/timeout/i.test(m))                                        return 'TIMEOUT';
  return 'UNKNOWN';
}

function wireNativeHelperCard() {
  const section      = document.getElementById('nativeHelperSection');
  if (!section) return;

  const IS_DESKTOP = !!(window.__PFX_IS_ELECTRON || window.pfxPlatform?.isMacApp);

  const pill           = document.getElementById('nhStatusPill');
  const extIdDisplay   = document.getElementById('nhExtIdDisplay');
  const capsDiv        = document.getElementById('nhCapabilities');
  const capPlayback    = document.getElementById('nhCapPlayback');
  const capAaf         = document.getElementById('nhCapAaf');
  const capFfmpeg      = document.getElementById('nhCapFfmpeg');
  const diagMsg        = document.getElementById('nhDiagMsg');
  const logPaths       = document.getElementById('nhLogPaths');
  const checkBtn       = document.getElementById('nhCheckBtn');
  const fullMacBtn     = document.getElementById('nhFullMacBtn');
  const fullWinBtn     = document.getElementById('nhFullWinBtn');
  const copyExtBtn     = document.getElementById('nhCopyExtIdBtn');
  const aafDetail      = document.getElementById('nhAafDetail');
  const aafDetailMsg   = document.getElementById('nhAafDetailMsg');
  const aafDetailMeta  = document.getElementById('nhAafDetailMeta');
  const repairAafBtn   = document.getElementById('nhRepairAafBtn');
  const testAafBtn     = document.getElementById('nhTestAafBtn');
  const showAafLogsBtn = document.getElementById('nhShowAafLogsBtn');

  const extId = (typeof chrome !== 'undefined' && chrome.runtime?.id && !IS_DESKTOP) ? chrome.runtime.id : '';
  if (extIdDisplay) extIdDisplay.textContent = extId || (IS_DESKTOP ? 'Desktop App' : '(unavailable in non-extension context)');

  // ── Desktop mode: adapt UI for built-in companion, hide Chrome-only elements ─
  if (IS_DESKTOP) {
    // "Browser Mode active" → "Native Mode active"
    const dotEl = section.closest('#proresCard')?.querySelector('.pfx-prs-dot');
    if (dotEl?.nextElementSibling) dotEl.nextElementSibling.textContent = 'Native Mode active — desktop app';

    // Relabel section title
    const nhLabel = section.querySelector('.pfx-nh-label');
    if (nhLabel) nhLabel.textContent = 'COMPANION ENGINE / MEDIA & AAF EXPORT';

    // Rename "Extension ID" row to "Mode"
    const infoRows = section.querySelectorAll('.pfx-nh-info-row');
    if (infoRows[1]) {
      const lbl = infoRows[1].querySelector('.pfx-nh-info-lbl');
      if (lbl) lbl.textContent = 'Mode';
    }

    // Hide Chrome-only elements
    const nhGuide = section.querySelector('.pfx-nh-guide');
    if (nhGuide) nhGuide.style.display = 'none';
    if (fullMacBtn) fullMacBtn.style.display = 'none';
    if (fullWinBtn) fullWinBtn.style.display = 'none';
    if (copyExtBtn) copyExtBtn.style.display = 'none';
  }

  // Global shared state so AAF panels in other modules can read it.
  if (!window.pfxNativeHelperState) {
    window.pfxNativeHelperState = {
      checked: false, available: false,
      aafWriter: false, ffmpeg: false,
      nativePlayback: false, version: null,
      errorCode: null, error: null,
    };
  }

  const setPill = (state, text) => {
    if (!pill) return;
    pill.className = `pfx-nh-pill pfx-nh-pill-${state}`;
    pill.textContent = text;
  };

  const showDiag = (msg, isWarn = false) => {
    if (!diagMsg) return;
    diagMsg.textContent = msg;
    diagMsg.className = isWarn ? 'pfx-nh-diag warn' : 'pfx-nh-diag';
    diagMsg.style.display = msg ? '' : 'none';
  };

  const capHtml = (ok, label = '') => ok
    ? `<span style="color:#4caf80;">&#10003; ${label || 'Ready'}</span>`
    : `<span style="color:#ff6b6b;">&#10007; ${label || 'Not available'}</span>`;

  // ── Check status ─────────────────────────────────────────────────────────────

  const checkStatus = async () => {
    setPill('checking', 'Checking…');
    if (checkBtn) checkBtn.disabled = true;
    if (capsDiv) capsDiv.style.display = 'none';
    if (logPaths) logPaths.style.display = 'none';
    showDiag('');

    try {
      // Step 1: Use COMPANION_CHECK for connection test (atomic connect+getCapabilities)
      const checkResult = await new Promise(resolve => {
        const guard = setTimeout(() => resolve({ ok: false, diagError: 'timeout' }), 13000);
        chrome.runtime.sendMessage({ type: 'COMPANION_CHECK' }, result => {
          clearTimeout(guard);
          void chrome.runtime.lastError;
          resolve(result || { ok: false, diagError: 'no response' });
        });
      });

      if (!checkResult.ok) {
        const rawErr = checkResult.diagError || '';
        const code = _nhClassifyError(rawErr);
        window.pfxNativeHelperState = { checked: true, available: false, aafWriter: false, ffmpeg: false, nativePlayback: false, version: null, errorCode: code, error: rawErr };

        const msgs = IS_DESKTOP ? {
          HOST_NOT_FOUND: 'Companion is not responding. It should start automatically — try restarting the app.',
          HOST_FORBIDDEN: 'Companion rejected the connection.',
          HOST_CRASHED:   'Companion launched but exited immediately. Check companion logs. Common cause: missing postflowx_companion Python package.',
          TIMEOUT:        'Companion did not respond within 12 s. Try restarting the app.',
        } : {
          HOST_NOT_FOUND: 'Native Helper is not installed. Download and run the Full Installer for your OS, then quit and relaunch Chrome.',
          HOST_FORBIDDEN: 'Native Helper is installed but this Extension ID is not allowed. Re-download and run the Full Installer — it will inject the current ID automatically.',
          HOST_CRASHED:   'Native Helper launched but exited immediately. Check the log file below. Common cause: missing postflowx_companion package. Re-run the Full Installer.',
          TIMEOUT:        'Native Helper did not respond within 12 s. The companion may be hanging. Try re-running the Full Installer.',
        };
        const friendlyMsg = msgs[code] || `Connection failed: ${rawErr}`;

        setPill('error', code === 'HOST_NOT_FOUND' ? 'Not Installed' : code === 'HOST_FORBIDDEN' ? 'Access Denied' : code === 'HOST_CRASHED' ? 'Crashed' : 'Error');
        showDiag(friendlyMsg);
        if (code === 'HOST_CRASHED' && logPaths) logPaths.style.display = '';
        return;
      }

      // Step 2: Companion is reachable — fetch AAF capabilities for full status
      const aafResult = await new Promise(resolve => {
        const guard = setTimeout(() => resolve(null), 8000);
        chrome.runtime.sendMessage({
          type: 'IMF_COMPANION_CALL',
          payload: { action: 'aafCapabilities', extensionId: extId },
          timeoutMs: 7000,
        }, resp => {
          clearTimeout(guard);
          void chrome.runtime.lastError;
          resolve(resp);
        });
      });

      const aafData = aafResult?.ok ? (aafResult.response?.data || aafResult.response?.result || {}) : {};
      if (aafData.logFile) window._pfxAafLogFile = aafData.logFile;
      // Also check getCapabilities features from the checkResult
      const gcFeatures = checkResult.features || {};
      const hasAafWriter    = !!(aafData.aafWriter);
      const hasFfmpeg       = !!(aafData.ffmpeg);
      // Desktop always has native playback via pfxPlatform.media (AVFoundation)
      const hasNativePlay   = !!(gcFeatures.nativePlayback || gcFeatures.thumbnailGrab) || IS_DESKTOP;
      const version         = aafData.version || null;

      window.pfxNativeHelperState = { checked: true, available: true, aafWriter: hasAafWriter, ffmpeg: hasFfmpeg, nativePlayback: hasNativePlay, version, errorCode: null, error: null };

      const aafDepsOk = hasAafWriter && hasFfmpeg;
      const pyaaf2Ver = aafData.pyaaf2Version || '';

      if (!aafDepsOk) {
        setPill('warn', hasNativePlay ? 'Partial — AAF unavailable' : 'Partial');
        if (!IS_DESKTOP) {
          showDiag('Native Helper is installed, but AAF support is incomplete. Download and run the Full Installer, then quit Chrome completely (Cmd+Q) and relaunch it, then click Check Helper.', true);
        }
      } else {
        setPill('ready', version ? `Ready  ·  v${version}` : 'Ready');
        showDiag('');
      }

      // Show capability grid
      if (capsDiv) capsDiv.style.display = '';
      if (capPlayback) capPlayback.innerHTML = capHtml(hasNativePlay, hasNativePlay ? 'Ready' : 'Not available');
      const aafCapLabel = hasAafWriter
        ? `Ready${pyaaf2Ver ? `  ·  pyaaf2 ${pyaaf2Ver}` : ''}`
        : (IS_DESKTOP ? 'AAF Export Missing' : 'Missing — run Full Installer');
      if (capAaf) capAaf.innerHTML = capHtml(hasAafWriter, aafCapLabel);
      if (capFfmpeg) capFfmpeg.innerHTML = capHtml(hasFfmpeg, hasFfmpeg ? 'Ready' : (IS_DESKTOP ? 'Missing' : 'Missing — run Full Installer'));

      // ── Desktop-only AAF detail panel ──────────────────────────────────────
      if (IS_DESKTOP && aafDetail) {
        aafDetail.style.display = '';
        if (!hasAafWriter) {
          // Missing state
          if (aafDetailMsg) {
            aafDetailMsg.innerHTML =
              '<strong style="color:#ff6b6b;">AAF Export Missing</strong><br>' +
              '<span style="color:rgba(255,255,255,.5);font-size:10px;">Native Helper is running, but AAF exporter module is not installed. Click Repair AAF Export to fix automatically.</span>';
          }
          if (aafDetailMeta) aafDetailMeta.style.display = 'none';
          if (repairAafBtn)   { repairAafBtn.style.display   = ''; repairAafBtn.disabled = false; }
          if (testAafBtn)     testAafBtn.style.display     = 'none';
          if (showAafLogsBtn) showAafLogsBtn.style.display = '';
        } else {
          // Ready state
          const testOk = !!(aafData.testWriteOK);
          if (aafDetailMsg) {
            aafDetailMsg.innerHTML =
              `<strong style="color:#4caf80;">AAF Export Ready</strong>`;
          }
          if (aafDetailMeta) {
            aafDetailMeta.style.display = '';
            aafDetailMeta.innerHTML =
              `<span class="pfx-nh-aaf-meta-row">Engine: pyaaf2${pyaaf2Ver ? ' ' + pyaaf2Ver : ''}</span>` +
              `<span class="pfx-nh-aaf-meta-row">Test Write: ${testOk ? '✓ Passed' : '— not run'}</span>`;
          }
          if (repairAafBtn)   repairAafBtn.style.display   = 'none';
          if (testAafBtn)     { testAafBtn.style.display     = ''; testAafBtn.disabled = false; }
          if (showAafLogsBtn) showAafLogsBtn.style.display = '';
        }
      }

    } catch (e) {
      setPill('error', 'Error');
      showDiag(`Unexpected error: ${e?.message || e}`);
    } finally {
      if (checkBtn) checkBtn.disabled = false;
      // Notify any open AAF panels to re-render with new state
      try { document.dispatchEvent(new CustomEvent('pfxNativeHelperStateChanged')); } catch {}
    }
  };

  const downloadFullInstaller = (platform) => {
    const id = extId || 'PASTE_YOUR_EXTENSION_ID_HERE';
    const content = (platform === 'mac' ? FULL_MAC_INSTALLER_TEMPLATE : FULL_WINDOWS_INSTALLER_TEMPLATE)
      .replaceAll('__PFX_EXTENSION_ID__', id)
      .replaceAll('__PFX_HOST_NAME__', 'com.postflowx.companion');
    const leftovers = ['__PFX_EXTENSION_ID__', '__PFX_HOST_NAME__'].filter(t => content.includes(t));
    if (leftovers.length) {
      console.error('Installer template still has unreplaced placeholders:', leftovers);
      alert('Installer could not be generated — unreplaced placeholders: ' + leftovers.join(', ') + '\nReload the extension and try again.');
      return;
    }
    const filename = platform === 'mac'
      ? `Install_PostFlowX_Full_Helper_${id}.command`
      : `Install_PostFlowX_Full_Helper_${id}.ps1`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  };

  if (checkBtn)   checkBtn.addEventListener('click', checkStatus);
  if (fullMacBtn) fullMacBtn.addEventListener('click', () => downloadFullInstaller('mac'));
  if (fullWinBtn) fullWinBtn.addEventListener('click', () => downloadFullInstaller('win'));
  if (copyExtBtn) copyExtBtn.addEventListener('click', () => {
    if (!extId) return;
    navigator.clipboard.writeText(extId).then(() => {
      copyExtBtn.textContent = '✓ Copied!';
      setTimeout(() => { copyExtBtn.innerHTML = '<span class="bar"></span>Copy Extension ID'; }, 2500);
    }).catch(() => {
      copyExtBtn.textContent = 'Select from Extension ID field';
    });
  });

  // ── AAF desktop buttons ────────────────────────────────────────────────────
  /** Send a companion action from the desktop renderer. */
  async function _sendCompanionAction(action, extraPayload = {}) {
    return new Promise(resolve => {
      const guard = setTimeout(() => resolve(null), 30000);
      chrome.runtime.sendMessage({
        type: 'IMF_COMPANION_CALL',
        payload: { action, extensionId: extId, ...extraPayload },
        timeoutMs: 28000,
      }, resp => {
        clearTimeout(guard);
        void chrome.runtime.lastError;
        const data = resp?.response?.data || resp?.response?.result || resp?.response || null;
        resolve(data);
      });
    });
  }

  if (repairAafBtn) {
    repairAafBtn.addEventListener('click', async () => {
      repairAafBtn.disabled = true;
      const origHtml = repairAafBtn.innerHTML;
      repairAafBtn.innerHTML = '<span class="bar"></span>Repairing…';
      try {
        const res = await _sendCompanionAction('aafRepair');
        if (res && res.repaired) {
          repairAafBtn.innerHTML = '<span class="bar"></span>Repaired — rechecking…';
        } else {
          repairAafBtn.innerHTML = '<span class="bar"></span>Repair failed — see logs';
          setTimeout(() => { repairAafBtn.innerHTML = origHtml; repairAafBtn.disabled = false; }, 3000);
          return;
        }
      } catch (e) {
        repairAafBtn.innerHTML = '<span class="bar"></span>Error — see logs';
        setTimeout(() => { repairAafBtn.innerHTML = origHtml; repairAafBtn.disabled = false; }, 3000);
        return;
      }
      await checkStatus();
    });
  }

  if (testAafBtn) {
    testAafBtn.addEventListener('click', async () => {
      testAafBtn.disabled = true;
      const origHtml = testAafBtn.innerHTML;
      testAafBtn.innerHTML = '<span class="bar"></span>Testing…';
      try {
        const res = await _sendCompanionAction('aafTestWrite');
        if (res && res.ok) {
          testAafBtn.innerHTML = '<span class="bar"></span>Test Passed ✓';
          if (aafDetailMeta) {
            aafDetailMeta.innerHTML = aafDetailMeta.innerHTML.replace(
              /Test Write:.*?<\/span>/,
              'Test Write: ✓ Passed</span>'
            );
          }
        } else {
          const errMsg = (res && res.error) ? res.error : 'Unknown error';
          testAafBtn.innerHTML = '<span class="bar"></span>Test Failed';
          if (aafDetailMsg) {
            aafDetailMsg.innerHTML += `<br><span style="color:#ff6b6b;font-size:10px;">Test error: ${esc(errMsg)}</span>`;
          }
        }
      } catch (e) {
        testAafBtn.innerHTML = '<span class="bar"></span>Error';
      }
      setTimeout(() => { testAafBtn.innerHTML = origHtml; testAafBtn.disabled = false; }, 3500);
    });
  }

  if (showAafLogsBtn) {
    showAafLogsBtn.addEventListener('click', () => {
      const logPath = window._pfxAafLogFile || null;
      if (!logPath) {
        if (aafDetailMsg) {
          aafDetailMsg.innerHTML += '<br><span style="color:rgba(255,255,255,.4);font-size:10px;">Log path unknown — run Check Helper first.</span>';
        }
        return;
      }
      if (window.pfxPlatform && window.pfxPlatform.revealInFinder) {
        window.pfxPlatform.revealInFinder(logPath);
      } else if (window.pfxElectron && window.pfxElectron.showItemInFolder) {
        window.pfxElectron.showItemInFolder(logPath);
      } else {
        if (aafDetailMsg) {
          aafDetailMsg.innerHTML += `<br><span style="color:rgba(255,255,255,.45);font-size:10px;">Log: ${esc(logPath)}</span>`;
        }
      }
    });
  }

  // Auto-check on card init
  setTimeout(checkStatus, 600);
}



// ─── Fun Box: Snake ───────────────────────────────────────────────────────────
function wireFunBoxSnake() {
  const canvas = document.getElementById('fbSnakeCanvas');
  const scoreEl = document.getElementById('fbSnakeScore');
  const hiEl = document.getElementById('fbSnakeHi');
  const msgEl = document.getElementById('fbSnakeMsg');
  const newBtn = document.getElementById('fbSnakeNew');
  if (!canvas) return;

  const CELL = 18, COLS = 14, ROWS = 14;
  canvas.width = COLS * CELL;   // 252px
  canvas.height = ROWS * CELL;  // 252px
  const ctx = canvas.getContext('2d');

  let snake, dir, next, food, score, running, raf, hi = 0;

  const COLORS = { head:'#b8ff5a', body:'#5bd43a', food:'#ff5f7a', bg:'#0d1117', grid:'rgba(255,255,255,.04)' };

  function rnd(max) { return Math.floor(Math.random() * max); }
  function freePos() {
    let p;
    do { p = { x: rnd(COLS), y: rnd(ROWS) }; }
    while (snake.some(s => s.x === p.x && s.y === p.y));
    return p;
  }

  function reset() {
    const mx = Math.floor(COLS / 2), my = Math.floor(ROWS / 2);
    snake = [{ x: mx, y: my }, { x: mx - 1, y: my }, { x: mx - 2, y: my }];
    dir = { x: 1, y: 0 }; next = { x: 1, y: 0 };
    food = freePos(); score = 0; running = false;
    if (raf) { cancelAnimationFrame(raf); raf = null; }
    scoreEl.textContent = 'Score: 0';
    msgEl.textContent = 'Press any arrow or WASD to start';
    draw();
  }

  function draw() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // grid
    ctx.strokeStyle = COLORS.grid;
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= COLS; x++) { ctx.beginPath(); ctx.moveTo(x*CELL,0); ctx.lineTo(x*CELL,canvas.height); ctx.stroke(); }
    for (let y = 0; y <= ROWS; y++) { ctx.beginPath(); ctx.moveTo(0,y*CELL); ctx.lineTo(canvas.width,y*CELL); ctx.stroke(); }
    // food
    ctx.fillStyle = COLORS.food;
    ctx.beginPath();
    ctx.arc(food.x*CELL + CELL/2, food.y*CELL + CELL/2, CELL/2 - 2, 0, Math.PI*2);
    ctx.fill();
    // snake
    snake.forEach((seg, i) => {
      const r = i === 0 ? 5 : 3;
      ctx.fillStyle = i === 0 ? COLORS.head : `rgba(91,212,58,${Math.max(0.3, 1 - i*0.035)})`;
      ctx.beginPath();
      ctx.roundRect(seg.x*CELL + 1, seg.y*CELL + 1, CELL - 2, CELL - 2, r);
      ctx.fill();
    });
  }

  let lastT = 0;
  const SPEED = 120; // ms per tick

  function tick(t) {
    raf = requestAnimationFrame(tick);
    if (t - lastT < SPEED) return;
    lastT = t;
    dir = { ...next };
    const head = { x: (snake[0].x + dir.x + COLS) % COLS, y: (snake[0].y + dir.y + ROWS) % ROWS };
    if (snake.some(s => s.x === head.x && s.y === head.y)) { gameOver(); return; }
    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
      score++;
      if (score > hi) { hi = score; hiEl.textContent = `Best: ${hi}`; }
      scoreEl.textContent = `Score: ${score}`;
      food = freePos();
    } else {
      snake.pop();
    }
    draw();
  }

  function gameOver() {
    cancelAnimationFrame(raf); raf = null; running = false;
    ctx.fillStyle = 'rgba(0,0,0,.65)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ff5f7a';
    ctx.font = 'bold 18px monospace';
    ctx.textAlign = 'center';
    ctx.fillText('GAME OVER', canvas.width/2, canvas.height/2 - 10);
    ctx.fillStyle = 'rgba(255,255,255,.6)';
    ctx.font = '13px monospace';
    ctx.fillText(`Score: ${score}`, canvas.width/2, canvas.height/2 + 14);
    ctx.textAlign = 'left';
    msgEl.textContent = 'Press N or click New to restart';
  }

  function start() {
    if (running) return;
    running = true;
    msgEl.textContent = '';
    lastT = 0;
    raf = requestAnimationFrame(tick);
  }

  const KEY_MAP = {
    ArrowUp:{x:0,y:-1},ArrowDown:{x:0,y:1},ArrowLeft:{x:-1,y:0},ArrowRight:{x:1,y:0},
    w:{x:0,y:-1},s:{x:0,y:1},a:{x:-1,y:0},d:{x:1,y:0},
    W:{x:0,y:-1},S:{x:0,y:1},A:{x:-1,y:0},D:{x:1,y:0},
  };

  document.addEventListener('keydown', e => {
    const tab = document.querySelector('#topAuxPaneFunBox');
    if (!tab || tab.hidden) return;
    if (e.key === 'n' || e.key === 'N') { reset(); return; }
    const d = KEY_MAP[e.key];
    if (!d) return;
    if (d.x === -dir.x && d.y === -dir.y) return; // no reverse
    if ((e.key.startsWith('Arrow') || 'wasdWASD'.includes(e.key))) e.preventDefault();
    next = d;
    if (!running) start();
  });

  newBtn?.addEventListener('click', reset);
  reset();
}

// ─── Fun Box: Pomodoro Timer ──────────────────────────────────────────────────
function wireFunBoxPomodoro() {
  const arc = document.getElementById('fbPomArc');
  const timeEl = document.getElementById('fbPomTime');
  const labelEl = document.getElementById('fbPomLabel');
  const startBtn = document.getElementById('fbPomStart');
  const resetBtn = document.getElementById('fbPomReset');
  const workBtn = document.getElementById('fbPomWork');
  const breakBtn = document.getElementById('fbPomBreak');
  const dotsEl = document.getElementById('fbPomSessionDots');
  const countEl = document.getElementById('fbPomSessionCount');
  const card = document.getElementById('funPomodoro');
  if (!arc) return;

  const CIRC = 2 * Math.PI * 52; // = 326.73
  let totalSec, remaining, interval, running = false, isBreak = false, sessions = 0;

  function setMode(brk) {
    isBreak = brk;
    totalSec = remaining = (brk ? 5 : 25) * 60;
    workBtn?.classList.toggle('active', !brk);
    breakBtn?.classList.toggle('active', brk);
    card?.classList.toggle('break-active', brk);
    arc?.classList.toggle('break-mode', brk);
    labelEl.textContent = brk ? 'BREAK' : 'WORK';
    updateDisplay();
    if (running) { clearInterval(interval); running = false; startBtn.textContent = '▶ Start'; }
  }

  function updateDisplay() {
    const m = Math.floor(remaining / 60), s = remaining % 60;
    timeEl.textContent = `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
    const pct = remaining / totalSec;
    arc.style.strokeDashoffset = CIRC * (1 - pct);
  }

  function beep() {
    try {
      const ac = new (window.AudioContext || window.webkitAudioContext)();
      [0, 0.15, 0.3].forEach(delay => {
        const o = ac.createOscillator(), g = ac.createGain();
        o.connect(g); g.connect(ac.destination);
        o.frequency.value = isBreak ? 440 : 880;
        g.gain.setValueAtTime(0.18, ac.currentTime + delay);
        g.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + delay + 0.25);
        o.start(ac.currentTime + delay);
        o.stop(ac.currentTime + delay + 0.26);
      });
    } catch(_) {}
  }

  function tick() {
    remaining--;
    updateDisplay();
    if (remaining <= 0) {
      clearInterval(interval); running = false;
      startBtn.textContent = '▶ Start';
      beep();
      if (!isBreak) { sessions++; updateSessions(); }
      setMode(!isBreak); // auto-switch
    }
  }

  function updateSessions() {
    dotsEl.textContent = '🍅'.repeat(Math.min(sessions, 8));
    countEl.textContent = `${sessions} session${sessions !== 1 ? 's' : ''} today`;
  }

  startBtn?.addEventListener('click', () => {
    if (running) {
      clearInterval(interval); running = false;
      startBtn.textContent = '▶ Resume';
    } else {
      interval = setInterval(tick, 1000); running = true;
      startBtn.textContent = '⏸ Pause';
    }
  });

  resetBtn?.addEventListener('click', () => {
    clearInterval(interval); running = false;
    startBtn.textContent = '▶ Start';
    remaining = totalSec;
    updateDisplay();
  });

  workBtn?.addEventListener('click', () => setMode(false));
  breakBtn?.addEventListener('click', () => setMode(true));

  setMode(false);
}

// ─── Fun Box: Film Quotes ─────────────────────────────────────────────────────
function wireFunBoxQuotes() {
  const textEl = document.getElementById('fbQuoteText');
  const authorEl = document.getElementById('fbQuoteAuthor');
  const nextBtn = document.getElementById('fbQuoteNext');
  if (!textEl) return;

  const QUOTES = [
    { q: "The most honest form of filmmaking is to make a film for yourself.", a: "Peter Jackson" },
    { q: "Cinema is a mirror by which we often see ourselves.", a: "Martin Scorsese" },
    { q: "Editing is where movies are made or broken. Many a film has been saved and many a film has been ruined in the cutting room.", a: "Frank Capra" },
    { q: "The job of the editor is to be the first audience.", a: "Walter Murch" },
    { q: "The cut is the most basic and most dramatic act of filmmaking — it is the heartbeat of the medium.", a: "Walter Murch" },
    { q: "Film editing is now something almost everyone can do at a simple level and enjoy. It converges with the editing of writing.", a: "Douglas Adams" },
    { q: "Every film is a dream. Every cut is a wakeup.", a: "Werner Herzog" },
    { q: "Color is everything. Black and white is more.", a: "Dominic Rouse" },
    { q: "Post production is where the story truly begins. The script is a dream; the edit is the reality.", a: "Thelma Schoonmaker" },
    { q: "There's no such thing as a small cut. Every edit is a choice, and every choice tells the audience what to feel.", a: "Anne V. Coates" },
    { q: "VFX is not about what you see — it's about what you believe.", a: "Dennis Muren, ILM" },
    { q: "The frame is a window, and the editor decides how long you look through it.", a: "Carol Littleton" },
    { q: "The best visual effects are the ones the audience never notices.", a: "John Dykstra" },
    { q: "A film is never really finished. It's abandoned.", a: "Jean-Luc Godard" },
    { q: "Sound is 50% of the movie-going experience.", a: "George Lucas" },
    { q: "You have to steal from the best. You can't steal from the worst — there's nothing there worth taking.", a: "Quentin Tarantino" },
    { q: "The most important thing is to be honest — in the script, in the acting, in the editing. Audiences smell dishonesty a mile away.", a: "David Fincher" },
    { q: "Every master shot deserves to be interrupted at exactly the right moment.", a: "Sidney Lumet" },
    { q: "In the digital age, the grader is the last painter on the film.", a: "Roger Deakins" },
    { q: "Offline is just the beginning. The online is where the dream becomes real.", a: "Angus Wall" },
  ];

  let idx = Math.floor(Math.random() * QUOTES.length);

  function show() {
    const q = QUOTES[idx];
    textEl.style.opacity = '0';
    authorEl.style.opacity = '0';
    setTimeout(() => {
      textEl.textContent = `"${q.q}"`;
      authorEl.textContent = `— ${q.a}`;
      textEl.style.opacity = '1';
      authorEl.style.opacity = '1';
    }, 180);
  }

  textEl.style.transition = 'opacity .18s';
  authorEl.style.transition = 'opacity .18s';

  nextBtn?.addEventListener('click', () => {
    idx = (idx + 1) % QUOTES.length;
    show();
  });

  show();
}

function wireFunBoxMinesweeper(){
  const root = $("#funMinesweeper");
  const boardEl = $("#fbMinesBoard");
  const boardWrapEl = boardEl && boardEl.parentElement ? boardEl.parentElement : null;
  const levelEl = $("#fbMinesLevel");
  const newBtn = $("#fbMinesNew");
  const faceEl = $("#fbMinesFace");
  const minesEl = $("#fbMinesMines");
  const flagsEl = $("#fbMinesFlags");
  const timeEl = $("#fbMinesTime");
  const statusEl = $("#fbMinesStatus");
  const bottomBtnEl = $("#fbMinesBottomBtn");
  if (!root || !boardEl || !levelEl || !newBtn || !faceEl || !minesEl || !flagsEl || !timeEl || !statusEl) return;

  const LEVELS = {
    easy:   { rows: 9,  cols: 9,  mines: 10 },
    medium: { rows: 16, cols: 16, mines: 40 },
    hard:   { rows: 16, cols: 30, mines: 99 },
  };

  let game = null;

  const idx = (r, c) => (r * game.cols) + c;
  const inBounds = (r, c) => (r >= 0 && c >= 0 && r < game.rows && c < game.cols);

  function levelCfg(name){
    return LEVELS[name] || LEVELS.medium;
  }

  function formatDisplay(value){
    const n = Math.max(-99, Math.min(999, Number(value) || 0));
    const sign = n < 0 ? '-' : '';
    const abs = String(Math.abs(n)).padStart(sign ? 2 : 3, '0');
    return (sign + abs).slice(-3);
  }

  const LED_SEGMENTS = {
    '0': ['a','b','c','d','e','f'],
    '1': ['b','c'],
    '2': ['a','b','g','e','d'],
    '3': ['a','b','g','c','d'],
    '4': ['f','g','b','c'],
    '5': ['a','f','g','c','d'],
    '6': ['a','f','g','e','c','d'],
    '7': ['a','b','c'],
    '8': ['a','b','c','d','e','f','g'],
    '9': ['a','b','c','d','f','g'],
    '-': ['g'],
    ' ': []
  };

  function renderClassicLed(el, text){
    if (!el) return;
    const chars = String(text || '').padStart(3, ' ').slice(-3).split('');
    el.innerHTML = '';
    el.setAttribute('aria-label', text);
    for (const ch of chars){
      const digit = document.createElement('span');
      digit.className = 'fun-mines-led-digit';
      digit.dataset.char = ch;
      const on = new Set(LED_SEGMENTS[ch] || []);
      for (const segName of ['a','b','c','d','e','f','g']){
        const seg = document.createElement('span');
        seg.className = `fun-mines-led-seg fun-mines-led-seg-${segName}` + (on.has(segName) ? ' is-on' : '');
        digit.appendChild(seg);
      }
      el.appendChild(digit);
    }
  }

  function faceLabel(){
    if (!game) return '☺';
    if (game.over && game.status === 'Cleared') return '😎';
    if (game.over && game.status === 'Boom') return '☹';
    if (game.mouseDown) return '😮';
    return '☺';
  }

  function updateFace(){
    faceEl.textContent = faceLabel();
    faceEl.dataset.state = game && game.over ? (game.status === 'Cleared' ? 'win' : 'lose') : (game && game.mouseDown ? 'press' : 'ready');
    faceEl.title = game && game.over ? (game.status === 'Cleared' ? 'You cleared the board' : 'Boom') : 'New game';
  }

  function shuffle(arr){
    for (let i = arr.length - 1; i > 0; i -= 1){
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function neighborsOf(index){
    const row = Math.floor(index / game.cols);
    const col = index % game.cols;
    const out = [];
    for (let dr = -1; dr <= 1; dr += 1){
      for (let dc = -1; dc <= 1; dc += 1){
        if (!dr && !dc) continue;
        const rr = row + dr;
        const cc = col + dc;
        if (inBounds(rr, cc)) out.push(idx(rr, cc));
      }
    }
    return out;
  }

  function stopTimer(){
    if (game && game.timerId){
      clearInterval(game.timerId);
      game.timerId = null;
    }
  }

  function startTimer(){
    stopTimer();
    game.timerId = setInterval(() => {
      if (!game || game.over) return;
      game.time = Math.min(999, game.time + 1);
      updateHud();
    }, 1000);
  }

  function placeMines(safeIndex){
    const blocked = new Set([safeIndex, ...neighborsOf(safeIndex)]);
    let candidates = [];
    for (let i = 0; i < game.cells.length; i += 1){
      if (!blocked.has(i)) candidates.push(i);
    }
    if (candidates.length < game.mines){
      candidates = [];
      for (let i = 0; i < game.cells.length; i += 1){
        if (i !== safeIndex) candidates.push(i);
      }
    }
    shuffle(candidates);
    const picks = candidates.slice(0, game.mines);
    for (const pick of picks){
      game.cells[pick].mine = true;
    }
    for (let i = 0; i < game.cells.length; i += 1){
      if (game.cells[i].mine) continue;
      let count = 0;
      for (const n of neighborsOf(i)){
        if (game.cells[n].mine) count += 1;
      }
      game.cells[i].count = count;
    }
  }

  function countFlags(){
    return game.cells.reduce((n, c) => n + (c.flagged ? 1 : 0), 0);
  }

  function openAllMines(){
    for (const cell of game.cells){
      if (cell.mine) cell.open = true;
    }
  }

  function revealFlood(startIndex){
    const stack = [startIndex];
    const seen = new Set();
    while (stack.length){
      const current = stack.pop();
      if (seen.has(current)) continue;
      seen.add(current);
      const cell = game.cells[current];
      if (cell.open || cell.flagged) continue;
      cell.open = true;
      if (cell.mine) continue;
      if (cell.count === 0){
        for (const n of neighborsOf(current)){
          const nc = game.cells[n];
          if (!nc.open && !nc.flagged) stack.push(n);
        }
      }
    }
  }

  function checkWin(){
    for (const cell of game.cells){
      if (!cell.mine && !cell.open) return false;
    }
    return true;
  }

  function updateHud(){
    renderClassicLed(minesEl, formatDisplay(game.mines - countFlags()));
    flagsEl.textContent = String(countFlags());
    renderClassicLed(timeEl, formatDisplay(game.time));
    statusEl.textContent = game.status;
    updateFace();
  }

  function syncBoardWrapLayout(){
    if (!boardWrapEl || !boardEl || !game) return;

    const levelName = (levelEl && levelEl.value) || (game.cols >= 30 ? 'hard' : (game.cols >= 16 ? 'medium' : 'easy'));
    const profile = levelName === 'easy'
      ? { minCell: 20, maxCell: 42, padX: 10, padY: 10 }
      : levelName === 'medium'
        ? { minCell: 16, maxCell: 30, padX: 10, padY: 10 }
        : { minCell: 13, maxCell: 22, padX: 8, padY: 8 };

    const wrapW = Math.max(0, boardWrapEl.clientWidth - (profile.padX * 2));
    const wrapH = Math.max(0, boardWrapEl.clientHeight - (profile.padY * 2));
    if (wrapW > 0 && wrapH > 0){
      const maxFit = Math.floor(Math.min(wrapW / game.cols, wrapH / game.rows));
      const fitCell = Math.max(10, maxFit || 10);
      const cellPx = Math.max(Math.min(profile.minCell, fitCell), Math.min(profile.maxCell, fitCell));
      boardEl.style.setProperty('--fun-mines-cell', `${cellPx}px`);
      boardEl.style.gridTemplateColumns = `repeat(${game.cols}, ${cellPx}px)`;
    }

    const fitsX = boardEl.scrollWidth <= boardWrapEl.clientWidth;
    const fitsY = boardEl.scrollHeight <= boardWrapEl.clientHeight;
    boardWrapEl.classList.toggle('is-center-x', !!fitsX);
    boardWrapEl.classList.toggle('is-center-y', !!fitsY);
    boardWrapEl.classList.toggle('is-centered', !!(fitsX && fitsY));
    if (!fitsX) boardWrapEl.scrollLeft = 0;
    if (!fitsY) boardWrapEl.scrollTop = 0;
  }

  function renderBoard(){
    const needed = game.cells.length;
    if (boardEl.children.length !== needed){
      boardEl.innerHTML = '';
      for (let i = 0; i < needed; i += 1){
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'fun-mines-cell';
        btn.dataset.idx = String(i);
        btn.setAttribute('role', 'gridcell');
        btn.setAttribute('aria-label', 'Hidden cell');
        boardEl.appendChild(btn);
      }
    }

    for (let i = 0; i < needed; i += 1){
      const btn = boardEl.children[i];
      const cell = game.cells[i];
      btn.className = 'fun-mines-cell';
      btn.removeAttribute('data-n');
      btn.removeAttribute('data-mark');
      let text = '';
      let aria = 'Hidden cell';
      if (cell.open) btn.classList.add('is-open');
      if (cell.flagged && !cell.open) btn.classList.add('is-flagged');
      if (cell.open && cell.mine) btn.classList.add('is-mine');
      if (game.explodedIndex === i) btn.classList.add('is-exploded');

      if (cell.open){
        if (cell.mine){
          text = '✹';
          aria = 'Mine';
        } else if (cell.count > 0){
          text = String(cell.count);
          btn.dataset.n = String(cell.count);
          aria = `${cell.count} neighboring mines`;
        } else {
          text = '';
          aria = 'Empty cell';
        }
      } else if (cell.flagged){
        text = '⚑';
        btn.dataset.mark = 'flag';
        aria = 'Flagged cell';
      }
      btn.textContent = text;
      btn.setAttribute('aria-label', aria);
      btn.title = aria;
    }
    updateHud();
    requestAnimationFrame(syncBoardWrapLayout);
  }

  function finish(win){
    game.over = true;
    game.mouseDown = false;
    stopTimer();
    if (win){
      game.status = 'Cleared';
      for (const cell of game.cells){
        if (cell.mine) cell.flagged = true;
      }
    } else {
      game.status = 'Boom';
      openAllMines();
    }
    renderBoard();
  }

  function reveal(index){
    if (!game || game.over) return;
    const cell = game.cells[index];
    if (!cell || cell.open || cell.flagged) return;

    if (game.firstMove){
      placeMines(index);
      game.firstMove = false;
      game.status = 'Playing';
      startTimer();
    }

    if (cell.mine){
      cell.open = true;
      game.explodedIndex = index;
      finish(false);
      return;
    }

    if (cell.count === 0) revealFlood(index);
    else cell.open = true;

    if (checkWin()) finish(true);
    else renderBoard();
  }

  function toggleFlag(index){
    if (!game || game.over) return;
    const cell = game.cells[index];
    if (!cell || cell.open) return;
    cell.flagged = !cell.flagged;
    if (!game.firstMove && game.status !== 'Playing') game.status = 'Playing';
    renderBoard();
  }

  function reset(name){
    const cfg = levelCfg(name || levelEl.value);
    stopTimer();
    game = {
      rows: cfg.rows,
      cols: cfg.cols,
      mines: cfg.mines,
      cells: Array.from({ length: cfg.rows * cfg.cols }, () => ({ mine: false, count: 0, open: false, flagged: false })),
      time: 0,
      timerId: null,
      over: false,
      firstMove: true,
      status: 'Ready',
      mouseDown: false,
      explodedIndex: -1,
    };
    renderBoard();
  }

  boardEl.addEventListener('pointerdown', (e) => {
    const btn = e.target && e.target.closest ? e.target.closest('.fun-mines-cell') : null;
    if (!btn || !game || game.over) return;
    if (e.button === 0){
      game.mouseDown = true;
      updateFace();
    }
  });

  boardEl.addEventListener('pointerup', () => {
    if (!game) return;
    game.mouseDown = false;
    updateFace();
  });

  boardEl.addEventListener('pointerleave', () => {
    if (!game) return;
    game.mouseDown = false;
    updateFace();
  });

  boardEl.addEventListener('click', (e) => {
    const btn = e.target && e.target.closest ? e.target.closest('.fun-mines-cell') : null;
    if (!btn) return;
    reveal(Number(btn.dataset.idx));
    if (game){
      game.mouseDown = false;
      updateFace();
    }
  });

  boardEl.addEventListener('contextmenu', (e) => {
    const btn = e.target && e.target.closest ? e.target.closest('.fun-mines-cell') : null;
    if (!btn) return;
    e.preventDefault();
    toggleFlag(Number(btn.dataset.idx));
  });

  boardEl.addEventListener('keydown', (e) => {
    const btn = e.target && e.target.closest ? e.target.closest('.fun-mines-cell') : null;
    if (!btn) return;
    const index = Number(btn.dataset.idx);
    if (e.key === 'Enter' || e.key === ' '){
      e.preventDefault();
      reveal(index);
    } else if (e.key === 'f' || e.key === 'F'){
      e.preventDefault();
      toggleFlag(index);
    }
  });

  window.addEventListener('resize', () => requestAnimationFrame(syncBoardWrapLayout));

  on(levelEl, 'change', () => reset(levelEl.value));
  on(newBtn, 'click', () => reset(levelEl.value));
  on(faceEl, 'click', () => reset(levelEl.value));
  on(bottomBtnEl, 'click', () => reset(levelEl.value));

  reset(levelEl.value || 'medium');
}

// -------------------------------------------------------------
// Boot
// -------------------------------------------------------------
document.addEventListener("DOMContentLoaded", async () => {
  // ── Auth gate: wait for boot-guard before booting the app ────────────────
  // Fail-closed: if boot-guard.js never ran (load error, missing file), block the app.
  if (!window.__pfxBootGuard) {
    window.PFX_LOGIN_UI?.showLogin?.();
    return;
  }
  if (window.__pfxBootGuard) {
    let authResult;
    try {
      authResult = await window.__pfxBootGuard;
    } catch {
      authResult = { status: 'login' };
    }
    if (authResult?.status !== 'ok') {
      // Login/expired/denied UI already shown by boot-guard.js
      return;
    }
    // Propagate session to PFX_PERMISSIONS
    if (authResult.session && window.PFX_PERMISSIONS?.setSession) {
      window.PFX_PERMISSIONS.setSession(authResult.session);
    }
    if (!authResult._needsSignIn) window.PFX_LOGIN_UI?.hide?.();
    // Apply read-only badge and control disabling if applicable
    if (window.PFX_PERMISSIONS?.isReadOnly?.()) {
      window.PFX_READONLY?.apply?.();
    }
    // Initialize lease + media coordinator
    window.PFX_LEASE?.init?.((readOnly, reason) => {
      if (readOnly) window.PFX_READONLY?.apply?.();
      else window.PFX_READONLY?.remove?.();
    });
    window.PFX_MEDIA_COORD?.init?.((reason) => {
      // Other tab claimed playback — pause any active player in this tab
      document.querySelectorAll('video, audio').forEach(m => { try { m.pause(); } catch {} });
    });
  }

  await bootModules();

  // Populate build stamp in Settings/About tab (#pfxBuildStamp)
  try {
    const stampEl = document.getElementById('pfxBuildStamp');
    if (stampEl) {
      const tgt  = window.__PFX_TARGET__        || (window.pfxPlatform?.isMacApp ? 'desktop' : 'extension');
      const ver  = window.__PFX_BUILD_VERSION__ || window.chrome?.runtime?.getManifest?.()?.version || '—';
      const ts   = window.__PFX_BUILD_TIME__    || '—';
      const label = tgt === 'desktop' ? 'Desktop' : 'Extension';
      stampEl.textContent = `Build Target: ${label}  ·  v${ver}  ·  ${ts}`;
    }
  } catch(_) {}

  // Localization (About header selector) — applies across all tabs.
  try{ initI18nUI(); }catch{}

  wireMainTabs();
  applyTabPermissions();   // hide/restrict tabs based on RBAC session

  // macOS app: show Home tab and start on the home screen.
  // pfxPlatform.isMacApp is set by preload.js (reliable in all modes).
  // __PFX_TARGET__ is injected by build-renderer.js (belt-and-suspenders for packaged builds).
  const _isMacApp = !!(window.pfxPlatform?.isMacApp) || window.__PFX_TARGET__ === 'desktop';
  if (_isMacApp) {
    const homeTab = document.getElementById('pfxHomeTab');
    if (homeTab) homeTab.style.display = '';
    try { initHomeScreen(); } catch(e) { console.warn('[Home] init failed', e); }
    setMainTab('home');
    // Add Home button to header brand area so user can always return
    try {
      const brand = document.querySelector('header .brand');
      if (brand) {
        brand.style.cssText = 'visibility:visible; pointer-events:auto; cursor:pointer;';
        brand.title = 'Home';
        brand.addEventListener('click', () => setMainTab('home'));
      }
    } catch(_) {}
  } else {
    setMainTab(_firstAllowedTab() || "prepmark");
  }

  try { initPrepMark(); } catch(e) { console.warn('Prep & Mark init failed', e); }

  wireQS();
  _mbWireModal();
  wireEvtGroupTools();
  wireIO();
  wireHeader();
  wireTopAuxTabs();
  wireFunBoxMinesweeper();
  try { wireFunBoxSnake(); } catch(e) { console.warn('Snake init failed', e); }
  try { wireFunBoxPomodoro(); } catch(e) { console.warn('Pomodoro init failed', e); }
  try { wireFunBoxQuotes(); } catch(e) { console.warn('Quotes init failed', e); }
  wireExport();
  _wireSettingsSearch();
  wireInnerTabs();
  wireAMF();      // ✅ VFX Mapping (kept name for compatibility)
  wireVfxTaskRelayout(); // ✅ Move Task into Shot cell, hide QT filename text
  wireAEPBridge(); // ✅ Native Host (.aep) progress + messages
  wireUnifiedProjectFileButtons();
  wireProjectBar();
  wireValidation();
  wireAudit();

  // IMF Validation tab
  try {
    const { initIMFTab } = await import('./modules/imf/imf_ui.js');
    initIMFTab();
  } catch(e) { console.warn('[IMF] module failed to load', e); }

  // Proactively warm the proxy cache from disk so restored projects and all
  // tabs get proxy URLs immediately without waiting for the 2-second probe.
  try {
    const { warmProxyCacheFromStorage } = await import('./modules/proResProxy.js');
    warmProxyCacheFromStorage();
  } catch(e) { console.warn('[ProxyCache] warmup failed', e); }

  // Auto-check Native Host status silently on startup (no popup)
  try{ requestNativeHostStatusSilent(true); }catch{}

  // ── Resolve: passive background auto-connect ──────────────────────────────
  // Wires the top-bar pill and kicks off a passive detect. The check never
  // launches Resolve and never raises its GUI — it only asks the scripting
  // API if Resolve is currently running. The watcher (visibility/focus/
  // heartbeat) is started by project_setup.js's _pssSyncBoot.
  try { _wireResolvePill(); } catch (e) { console.warn('[Resolve] pill wire failed', e); }
  try {
    const api = window.__pfxProjectSetup;
    if (api?.autoConnectResolve) {
      api.autoConnectResolve().catch(() => {});
    }
  } catch (e) { console.warn('[Resolve] auto-connect kickoff failed', e); }

  // ── Electron menu navigation (pfx:fromMain → NAVIGATE_HOME / NAVIGATE_TAB) ──
  if (chrome?.runtime?.onMessage) {
    chrome.runtime.onMessage.addListener((msg) => {
      if (!msg || typeof msg !== 'object') return;
      const type = msg.type;
      if (type === 'NAVIGATE_HOME') {
        try { setMainTab('home'); } catch(_) {}
      } else if (type === 'NAVIGATE_TAB') {
        try {
          setMainTab(msg.tab || 'prepmark');
          if (msg.sub === 'vfx-pull') {
            // Give prepmark a frame to activate before firing the event
            requestAnimationFrame(() => {
              window.dispatchEvent(new CustomEvent('pfx:open-vfx-pull'));
            });
          }
        } catch(_) {}
      } else if (type === 'OPEN_SETTINGS') {
        try { setMainTab('about'); } catch(_) {}
      }
    });
  }

  try {
    cutDiff2Feature = createCutDiff2Feature({
      CutDiff,
      parseFromFiles,
      handleDroppedDataTransfer,
      pickTimelineFiles,
      stemNoExt,
      tcToFrames,
      esc,
      on,
      showError,
      buildEDLFiles,
    });
    cutDiff2Feature.mount();
  } catch(e) { console.warn('[CutDiff2] init failed', e); }

  try {
    plateLinkFeature = createPlateLinkFeature({ AMF, tcToFrames, framesToTC, stemNoExt, on, esc });
    // Lazy: mount() is called inside onTabActivated() on first activation
  } catch(e) { console.warn('[PlateLink2] init failed', e); }


  try {
    trlConformFeature = createTrlConformFeature({
      parseXMEML,
      parseEDL,
      parseFCPXML: null,
      tcToFrames,
      framesToTC,
      stemNoExt,
      on,
    });
    trlConformFeature.mount();
    window.PFX_exportTrlConfState = () => trlConformFeature.exportState();
    window.PFX_applyTrlConfState  = (s) => { try{ trlConformFeature.applyState(s); }catch{} };
  } catch(e) { console.warn('[TrlConform] init failed', e); }


  wireTableKeyboard();
  wireLocatorEditor();
  wireHandlesEditor();
  wireEDLTimeline();
  wireEDLCollapse();
  wireEDLPaneSwapAndLock();
  wireEDLPaneDivider();
  try{ wireMediaManager(); }catch{}
  try{ wireFeedback(); }catch{}
  try{ wireNoteTypesSettings(); }catch{}
  try{ wireShortcutsSettings(); }catch{}
  try{ wireCameraTemplatesSettings(); }catch{}
  try{ wireNativeHelperCard(); }catch{}
  try{ wireProxyOutputDir(); }catch{}
 // NOTE (PostFlowX): Card minimize/collapse UI was removed per latest UX request.
  // It was adding extra chevron buttons in card headers (red-box area) across EDL/Cut Diff.
  // If we ever need it again, re-enable the call below.
  // try{ initPfxCollapsibleUI(); }catch{}

  toggleHeartbeat("#btnBrowseFiles", true);
  toggleHeartbeat("#btnClear", false);

  renderKPIs([]);
  renderTable();
  try{ startEventTableWatchdog(); }catch{}
  try{ renderEDLTimeline(); }catch{}
  updateInspector();
  updateQSUI();
  syncAllOffWidth();
  on(window, "resize", syncAllOffWidth, { passive: true });
  on(window, "resize", scheduleEDLTimelineRerender, { passive: true });

  setAllOffActive(true);

  try{ applyPfxIconTheme(); }catch(e){ console.warn("PFX icon theme apply failed", e); }

  try{ _wirePfxTutorials(); }catch(e){ console.warn('[PFX] How to Use wiring failed', e); }

  // ── How to Use button — wired here so it works even when wireEDLTimeline exits
  //    early due to missing edlTlViewport (old EDL pane removed).
  try {
    const _tutMap = {
      edl: 'pullPrepTutorialModal', prepmark: 'pullPrepTutorialModal',
      cutdiff: 'cutDiffTutorialModal', cutdiff2: 'cutDiff2TutorialModal',
      shotmarker: 'markersTutorialModal', reviews: 'reviewsTutorialModal',
      amf: 'plateLinkTutorialModal', platelink2: 'plateLinkTutorialModal',
      // keep in sync with _tutModalMap above — both handlers fire on one click
      trlconf: 'tlcTutorialModal', imf: 'settingsTutorialModal', aceslook: 'settingsTutorialModal', about: 'settingsTutorialModal',
    };
    let _tutClose = null;
    document.getElementById('btnTutorial')?.addEventListener('click', () => {
      const tab = String(document.body?.dataset?.main || '');
      const modal = document.getElementById(_tutMap[tab] || '');
      if (!modal) return;
      if (modal.id === 'playerTransportTutorialModal') {
        try { _wirePlayerTransportDeepDive(); } catch (_) {}
      }
      if (_tutClose) _tutClose();
      modal.style.display = 'flex';
      function close() {
        modal.style.display = 'none';
        document.removeEventListener('keydown', _onEsc);
        _tutClose = null;
      }
      function _onEsc(e) { if (e.key === 'Escape') close(); }
      modal.querySelector('.pfx-tutorial-backdrop')?.addEventListener('click', close, { once: true });
      const cb = modal.querySelector('.pfx-tutorial-close');
      if (cb && !cb._tw2) { cb._tw2 = true; cb.addEventListener('click', close); }
      document.addEventListener('keydown', _onEsc);
      _tutClose = close;
    });
  } catch(e) { console.warn('How to Use button wire failed', e); }
});
